INSERT INTO `crs_tabledata696` VALUES ('16', '{E9C879D8-4730-4687-A0E4-ECCBD1E99009}', '60', 'INHE-0088', '2015-04-10 17:51:37', '0000-00-00 00:00:00', null, '', '', '', null, '0', 'ST20503销售合同评审流程（v1.2）20131219流程（2015年04月10日17:51）余冬纯\\ST20', null, 'SUDANESE ELECTRICITY DISTRIBUTION CO.LTD', 'SUDANESE ELECTRICITY DISTRIBUTION CO.LTD', '23398', 'ST20', 'ST20503', '3850000', '国际业务一部', '余冬纯', '余冬纯50% 马坚50%', '2015-04-10', '海运', '我司', '苏丹苏丹港', '深圳', '海运', '/', '散件', '01', '', '翻单产品', '原ST20406合同执行25000套及2000套三相；\r\n此合同合同号：INHESC16150404WW，项目代号ST20503\r\n如空运，空运费将额外T/T预付款收取。', '', '110000', '3850000', '0', '', '分批发货', '', null, '', '03', null, null, null, null, null, null, null, 'CFR苏丹苏丹港\r\n\r\n原100000 套单相SKD 散件和10000 套三相SKD 散件付款条件将改为:\r\n100%全款不可撤销混合付款信用证\r\n（开证行在受益人接到信用证通知，由受益人银行发出索汇电文到后，即期支付合同总金额10%预\r\n付款，即EUR385,000 给卖方，由受益人银行发出保函后，开证行在五个工作日内支付合同总金额\r\n10%预付款，即EUR385,000 给卖方，合同总金额的80%每批即期交付发票提单议付。）', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata696` VALUES ('17', '{E9C879D8-4730-4687-A0E4-ECCBD1E99010}', '60', 'INHE-0088', '2015-04-10 17:51:37', '0000-00-00 00:00:00', null, '', '', '', null, '0', 'ST20503销售合同评审流程（v1.2）20131219流程（2015年04月10日17:51）余冬纯\\ST20', null, 'SUDANESE ELECTRICITY DISTRIBUTION CO.LTD', 'SUDANESE ELECTRICITY DISTRIBUTION CO.LTD', '23398', 'ST20', 'ST20503', '3850000', '国际业务一部', '余冬纯', '余冬纯50% 马坚50%', '2015-04-10', '海运', '我司', '苏丹苏丹港', '深圳', '海运', '/', '散件', '01', '', '翻单产品', '原ST20406合同执行25000套及2000套三相；\r\n此合同合同号：INHESC16150404WW，项目代号ST20503\r\n如空运，空运费将额外T/T预付款收取。', '', '110000', '3850000', '0', '', '分批发货', '', null, '', '03', null, null, null, null, null, null, null, 'CFR苏丹苏丹港\r\n\r\n原100000 套单相SKD 散件和10000 套三相SKD 散件付款条件将改为:\r\n100%全款不可撤销混合付款信用证\r\n（开证行在受益人接到信用证通知，由受益人银行发出索汇电文到后，即期支付合同总金额10%预\r\n付款，即EUR385,000 给卖方，由受益人银行发出保函后，开证行在五个工作日内支付合同总金额\r\n10%预付款，即EUR385,000 给卖方，合同总金额的80%每批即期交付发票提单议付。）', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata696` VALUES ('18', '{E9C879D8-4730-4687-A0E4-ECCBD1E99011}', '61', 'INHE-0091', '2015-04-28 16:22:33', '0000-00-00 00:00:00', null, '', '', '', null, '0', 'M9项目销售合同评审流程（v1.2）20131219流程（2015年04月28日16:21）林丽璇\\M9', null, 'Electricity Supply Corporation of Malawi Limited', 'Electricity Supply Corporation of Malawi Limited', '23696', 'M9', 'M9', '1516234.5', '国际业务二部', '林丽璇', '林丽璇', '2015-04-29', '海陆联运', '我司', 'ESCOM STORES,BLANTYRE', '中国', '包装坚固完好，适合长时间运输', '根据技术规格进行验收', '多种', '02', '', '需要研发', '备注：请注意以上产品数量，将在当地安装承包商对计量地点的安全检查、更新了工程量清单后会有所调整。合同金额也会随产品数量的变更而有所改动。', '', '0', '0', '1370782.5', '{06927BA04E624C74B6E4BF4167FD3235D4CC22B6C7B643389146528155CECD45}_2._The_Updated_Price_schedule_20160831(signed).pdf', '', '', '', '', '02', null, null, null, null, null, null, null, '1、价格术语为CIP Blantyre。 以上单价包含保费、运费及代理佣金【具体佣金将另外发OA】。\r\n2、付款条件【T/T付款】\r\n1）国外供货的机械设备，软件及必备的备件\r\n   a)收到预付款保函，履约保函及发票后45天内支付20%预付款\r\n   b)收到发票及清关文件（提单及保单）后，业主项目经理签发支付证书之日起28天内支付70%\r\n   c)业主项目经理出具完工证书，签发支付证书之日起28天内支付5%\r\n   d)业主项目经理在保修期结束后，签发支付证书之日起28天内支付5%【保修期：完工日起', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
