INSERT INTO `crs_tabledata696` VALUES ('47', '{E9C879D8-4730-4687-A0E4-ECCBD1E99040}', '60', 'JXINHE-1277', '2015-04-29 14:52:17', '0000-00-00 00:00:00', null, '', '', '', null, '0', '销售合同评审流程（v1.2）20131219流程（2015年04月29日14:52）李婉君\\白云', null, '\"Aspan-Energy \" LTD', '\"Aspan-Energy \" LTD', '23724', '白云', '白云501', '504570', '国际业务一部', '李婉君', '邱洁', '2015-04-29', '空运或者陆运', '客户', '深圳', '深圳', '按空运和陆运运输标准', '符合IEC标准', '单、三相智能电表，配件', '02', '', '客户要求单相表的接线端子由压盘式更改为接线柱接线；\r\n单相表的数据存储时间由7天增加至45-50天；\r\n三相四线CT接入式电表GPRS/GSM通信，是该客户订单新增产品；\r\n三相GPRS外接模块，是用于外接已供货的不带通讯方式的CT表', '由于单相表需要研发修改接线端子，且需要增加，扩大储存容量，需要一定的时间，在客户支付预付款的60天内，向客户提供完整的测试报告，45天后供货单相表。', '', '10730', '434570', '70000', '', '2015年6月14日', '', null, '', '02', null, null, null, null, null, null, null, '1、 FCA 深圳\r\n2、 支付方式：50%T/T-下单前，50%T/T-发货前', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
