INSERT INTO `crs_tabledata696` VALUES ('80', '{E9C879D8-4730-4687-A0E4-ECCBD1E99073}', '0', 'INHE-0399', '2015-07-02 08:55:42', '0000-00-00 00:00:00', null, '', '', '', null, '0', 'KG502 销售合同评审流程（v1.2）20131219流程（2015年07月02日08:55）左三维\\KG', null, 'Khawja Electricity Meter Co., Ltd.', 'Khawja Electricity Meter Co., Ltd.', '24728', 'KG', 'KG502', '588000', '国际业务一部', '左三维', '左三维', '2015-08-05', '海运', '买家', 'FOB深圳', '深圳', '牢固纸箱同KG其它单', 'IEC', 'OEM、SKD出货', '02', '', '1-普通单相电能表 同KG501 DDS26B\r\n2-普通单相电能表带新掉零线窃电 同ST04-1F 最终版样机 （江西， 计然）', '1-普通单相电能表带新掉零线窃电 铭牌修改，如附件ST04-1F铭牌丝印图。\r\n2-轮显如附件，液晶显示效果图', '', '60000', '588000', '0', '', '', '', null, '', '02', null, null, null, null, null, null, null, '1，FOB-shenzhen离岸价，不包含保险和运费。 \r\n2，KG客户会用一部分TT电汇，剩余部分用信用证，货物分为两半，分2批发货。详细结算方式如附件合同 KG502 60K。\r\n', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
