INSERT INTO `crs_tabledata696` VALUES ('82', '{E9C879D8-4730-4687-A0E4-ECCBD1E99075}', '60', 'JXINHE-1277', '2015-07-07 14:48:38', '0000-00-00 00:00:00', null, '', '', '', null, '0', '销售合同评审流程（v1.2）20131219流程（2015年07月07日14:48）李婉君\\白云', null, '\"Aspan-Energy \" LTD', '\"Aspan-Energy \" LTD', '24807', '白云', '白云504', '50000', '国际业务一部', '李婉君', '邱洁', '2015-07-07', '空运', '客户', '深圳', '深圳', '无', '无', '系统及相关的服务', '02', '', '由软件部谌工前往白云项目现场进行软件升级服务和升级后系统的使用培训。', '无', '', '0', '0', '50000', '', '2015年8月15日', '', null, '', '02', null, null, null, null, null, null, null, '1. 价格术语： FCA 深圳\r\n2. 20%T/T在软件升级服务之前，80%T/T在软件升级服务完成之后。单价中不包含保费和运费\r\n3. 2016年即2016年1月1日-2016年12月31日开始收取的20000美金的软件服务费用在每年的年底结算，合同中2.5条有规定，以后每年以此类推。', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata696` VALUES ('83', '{E9C879D8-4730-4687-A0E4-ECCBD1E99076}', '60', 'INHE-0391', '2015-07-12 02:44:58', '0000-00-00 00:00:00', null, '', '', '', null, '0', '销售合同评审流程（v1.2）20131219流程（2015年07月12日02:44）桂弯弯\\ZAR', null, 'Makgaji Printing and Projects', 'Makgaji Printing and Projects', '24914', 'ZAR', 'ZAR01', '150000', '国际业务一部', '桂弯弯', '桂弯弯', '2015-07-12', '空运', '空运与海运差价由客户承担', ' 南非坦博国际机场', '深圳', '无', '见双方签订的技术规格', '见表格和合同', '01', '', '无', '系统能够AMR兰吉尔的149台ZMD405三相CT电表', '', '0', '0', '150000', '', '15天', '', null, '', '02', null, null, null, null, null, null, null, '软件：\r\n1.合同签订后15日内, 仅在买方预付软件系统总价的30%给卖方15天后，卖方才启动软件系统的安装、调试；\r\n2.自售电系统运行之日起30日内，买方支付软件系统总价的第一个25%\r\n3.自AMR运行之日60日内，买方支付软件系统总价的第二个25%\r\n4.自AMI运行和卖方收到第二笔付款之日起90日内，买方支付软件系统总价的第三个20%\r\n5.系统安装后一年内免费维护。\r\n6.系统安装一年后每年维护费为USD 36,000.\r\n7.软件维护支付日期为一年免费维护期结束之日起7 天内。', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
