INSERT INTO `crs_tabledata696` VALUES ('89', '{E9C879D8-4730-4687-A0E4-ECCBD1E99082}', '61', 'INHE-0051', '2015-09-23 10:49:44', '0000-00-00 00:00:00', null, '', '', '', null, '0', '销售合同评审流程（v1.2）20131219流程（2015年09月23日10:49）盛燕\\PY', null, 'The Kenya Power * Lighting Company Limited', 'The Kenya Power * Lighting Company Limited', '26493', 'PY', 'PY02', '39101280', '国际业务二部', '盛燕', '盛燕', '2015-09-23', '海运', '卖方', 'LOT1：Ruaraka Meter Store; LOT2：Likoni stores; LOT 3: Bulk stores ', '深圳', '适合海运', '标书技术规格', ' 预付费电能表', '02', '', '见附件技术规格', '1.交期要求严格，需合理安排交期\r\n2.用公司新款DIN表供货，需确保产品质量', '', '1165000', '39101280', '0', '', '如下', '', null, '', '02', null, null, null, null, null, null, null, '1.此项目要求DDP到交货地点，我们负责清关，支付关税，增值税等。 \r\n2.以上单价是含运费，关税和VAT的DDP单价（中标函上单价是不含关税和VAT的单价），FOB到DDP之间运费已注明\r\n3.交货到到客户指定地点。交货后提交付款发票后30天通过T/T付款（或者可以申请电力公司开立信用证，建议按照T/T分批收款）。 \r\n4.中标函和合同见附件，合同模板和PX02一致，都是些通用条款。\r\n5.交期要求为（交货到电力公司仓库，运输需约45天）：\r\nLOT1：2015年12月30日\r\nLOT2：2016年4月', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
