INSERT INTO `crs_tabledata696` VALUES ('94', '{E9C879D8-4730-4687-A0E4-ECCBD1E99087}', '61', 'INHE-0440', '2015-10-14 16:02:14', '0000-00-00 00:00:00', null, '', '', '', null, '0', '销售合同评审流程（v1.2）20131219流程（2015年10月14日16:02）汤伟\\DW', null, 'AmelioEner GmbH', 'AmelioEner GmbH', '26901', 'DW', 'DW', '1789', '国际业务二部', '汤伟(Will)', '汤伟', '2015-10-14', '空运', '买家', 'Huenenberg，瑞士', '深圳', '纸箱', '默认公司已有标准', '公司已有产品', '01', '', '无', '客户需要在最短的时间内收到这些产品完成样机测试，之前有购买我们四台样机，分别是三相直通GSM通讯样机一台，三相CT GSM通讯样机一台，三相直通以太网样机一台，三相CT以太网样机一台。', '', '0', '0', '1586', '', '2015/10/21', '', null, '', '02', null, null, null, null, null, null, null, 'CIF SHENZHEN 深圳成本+运费+保险价格\r\n成本：1586 USD 运费+保险：203 USD', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata696` VALUES ('101', '{E9C879D8-4730-4687-A0E4-ECCBD1E99094}', '60', 'INHE-0462', '2015-11-03 10:22:26', '0000-00-00 00:00:00', null, '', '', '', null, '0', '销售合同评审流程（v1.2）20131219流程（2015年11月03日10:22）曹亮\\KGT', null, 'KHAWJA ELECTRICITY METER CO., LTD', 'KHAWJA ELECTRICITY METER CO., LTD', '27287', 'KGT', 'KGT01', '16500', '国际业务一部', '曹亮', '王维', '2015-11-03', '海运', '买家承担', '孟加拉吉大港', '出货港待定', '包装牢固纸箱，方便海运', '发货日期起18个月内质保', 'DTS27 三相双费率表', '02', '', '无', '卖家提出箱唛设计后，3天之内买家应该确认并通知卖家。若买家延迟确认和通知卖家，卖家不承担任何责任。', '', '0', '0', '0', '{1F0CDE059D5744C2AB0F4D6C47BE275BD4CC22B6C7B643389146528155CECD45}_KGT01-SALES CONFIRMATION 170721.pdf', '全款到后30天内交第一批货物，第二批交货期待商定', '', '', '', '02', null, null, null, null, null, null, null, '1.付款方式：发货前TT付全款；\r\n2.FOB 交货形式，运费与保费买房承担', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
