INSERT INTO `crs_tabledata696` VALUES ('104', '{E9C879D8-4730-4687-A0E4-ECCBD1E99097}', '61', 'INHE-0381', '2015-11-12 22:44:12', '0000-00-00 00:00:00', null, '', '', '', null, '0', '销售合同评审流程（v1.2）20131219流程（2015年11月12日22:44）张柳芳\\DEL', null, 'Delta Electricals Limited', 'Delta Electricals Limited', '27562', 'DEL', 'DEL01', '14950', '国际业务二部', '张柳芳(Alexie)', '张柳芳', '2015-11-12', '空运', 'Delta Electricals Limited', '乌干达，Entebbed', '深圳', '纸箱', 'IEC，STS', '成品', '02', '', '无', '无', '', '50', '9600', '0', '', '2016.1.10', '', null, '', '02', null, null, null, null, null, null, null, '1.价格术语：生产前全额付款。（已收到客户全额）\r\n2.单价不包含保费和运费。保费和运费为：5350 USD。\r\n3.CIP Entebbed', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata696` VALUES ('107', '{E9C879D8-4730-4687-A0E4-ECCBD1E99100}', '60', 'INHE-0406', '2015-11-17 13:36:40', '0000-00-00 00:00:00', null, '', '', '', null, '0', 'RS项目销售合同评审流程（v1.2）20131219流程（2015年11月17日13:36）王毅\\RS', null, 'Naratay Energy, LLC', 'Naratay Energy, LLC', '27636', 'RS', 'RS', '1504', '国际业务一部', '王毅', '王毅', '2015-11-17', '待定', '客户', '深圳', '深圳', '标准包装', '工厂', '成品', '02', '', '1. DIN导轨安装单相二线分体式（Mesh-RF无线通信）代码智能电表，只需有功计量（1.0），表箱安装，带继电器。5A(80A),230V.\r\n2. 三相四线直接接入可更换模块代码智能电表，精度1.0（2.0）,3X230/400V, 5A(80A），RF模块\r\n3. 三相四线CT接入可更换模块代码智能电表，精度1.0（2.0）,5（6）A，3X230/400V，不带GPRS模块 \r\n4. 集中器，无需计量功能，集中器内置Mesh-RF通信模块，带GPRS模块。\r\n', '1. 保证RF-mesh组网集抄顺利。\r\n2. 试点项目地址在西伯利亚，-40°低温运行。', '', '15', '1104', '400', '', '付款后45天', '', null, '', '02', null, null, null, null, null, null, null, '1. FOB深圳价格\r\n2. 100%预付款\r\n', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
