INSERT INTO `crs_tabledata696` VALUES ('110', '{E9C879D8-4730-4687-A0E4-ECCBD1E99103}', '60', 'INHE-0406', '2015-11-17 13:36:40', '0000-00-00 00:00:00', null, '', '', '', null, '0', 'RS项目销售合同评审流程（v1.2）20131219流程（2015年11月17日13:36）王毅\\RS', null, 'Naratay Energy, LLC', 'Naratay Energy, LLC', '27636', 'RS', 'RS', '1504', '国际业务一部', '王毅', '王毅', '2015-11-17', '待定', '客户', '深圳', '深圳', '标准包装', '工厂', '成品', '02', '', '1. DIN导轨安装单相二线分体式（Mesh-RF无线通信）代码智能电表，只需有功计量（1.0），表箱安装，带继电器。5A(80A),230V.\r\n2. 三相四线直接接入可更换模块代码智能电表，精度1.0（2.0）,3X230/400V, 5A(80A），RF模块\r\n3. 三相四线CT接入可更换模块代码智能电表，精度1.0（2.0）,5（6）A，3X230/400V，不带GPRS模块 \r\n4. 集中器，无需计量功能，集中器内置Mesh-RF通信模块，带GPRS模块。\r\n', '1. 保证RF-mesh组网集抄顺利。\r\n2. 试点项目地址在西伯利亚，-40°低温运行。', '', '15', '1104', '400', '', '付款后45天', '', null, '', '02', null, null, null, null, null, null, null, '1. FOB深圳价格\r\n2. 100%预付款\r\n', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata696` VALUES ('111', '{E9C879D8-4730-4687-A0E4-ECCBD1E99104}', '61', 'INHE-0228', '2015-11-26 03:52:23', '0000-00-00 00:00:00', null, '', '', '', null, '0', '销售合同评审流程（v1.2）20131219流程（2015年11月26日03:52）谭雯\\CDN07', null, 'ERANOVE SA', 'ERANOVE SA', '27793', 'CDN07', 'CDN07', '83180.25', '国际业务二部', '谭雯', '谭雯', '2015-11-26', '空运', '我司', '阿比让', '深圳', '无特殊要求', 'IEC', '成品', '02', '', '1. 三相表的技术规格为CDN04的\r\n2. 但是添加最近在增加的三表防窃电功能：零火互换，负载接地。\r\n3. 三相表还需增加：电网掉电时，能够辨别哪一相掉电，并及时上报掉电事件及事件。', '1. 配件的交期，要求在12月11日之前交货。\r\n2. 三相表的交期要求在1月5日之前交货。', '', '300', '45400', '33188.25', '', '尽快', '', null, '', '03', null, null, null, null, null, null, null, '1. CPT ABIDJAN （无保险）\r\n2. 单价中不含运费，运费另收4592EUR。\r\n3. 此订单，代理将收取佣金，佣金是按差价来收取。具体每种产品的差价见附件。\r\n4. 结算方式：先发货，发货后客户见单证（空运提单，CO，PL，报关底单）在7天内付款。（已批准！）\r\n\r\n附件中是PO的草稿。', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata696` VALUES ('118', '{E9C879D8-4730-4687-A0E4-ECCBD1E99111}', '61', 'INHE-0051', '2015-12-13 14:30:53', '0000-00-00 00:00:00', null, '', '', '', null, '0', '销售合同评审流程（v1.2）20131219流程（2015年12月13日14:30）盛燕\\A40', null, 'The Kenya Power * Lighting Company Limited', 'The Kenya Power * Lighting Company Limited', '28200', 'A40', 'A40', '7137945.1', '国际业务二部', '盛燕', '盛燕', '2015-12-13', '海运', '卖方', 'BULK STORES, NAIROBI', '深圳', '适合海运', '标书技术规格', ' 预付费电能表', '02', '', '见附件技术规格', '需保证产品质量', '', '0', '0', '0', '', '如下', '', '', '', '02', null, null, null, null, null, null, null, '2.付款方式为：10%预付款 + 发货后T/T支付80% + 交货验收后支付余款10%\r\n\r\n其他内容不变', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
