INSERT INTO `crs_tabledata696` VALUES ('126', '{E9C879D8-4730-4687-A0E4-ECCBD1E99119}', '61', 'INHE-0091', '2015-12-18 09:04:54', '0000-00-00 00:00:00', null, '', '', '', null, '0', 'ESA项目 销售合同评审流程（v1.2）20131219流程（2015年12月18日09:04）林丽璇\\ESA', null, 'Nyamezela Consulting Engineers (Pty) Ltd.', 'Nyamezela Metering PTY Ltd', '28299', 'ESA', 'ESA-01', '1992250', '国际业务二部', '林丽璇', '盛燕', '2015-12-18', '海运', '我司', '德班', '中国任意港口', '适合海运及长途运输', 'ESKOM技术规格', '单相DIN导轨安装电表', '无库存', '', '请详见ESA项目技术规格。', '1、质保期：散件发货后18个月质保期，成品发货后5年质保期。\r\n2、第一批交货数量：35,000\r\n   1）DIN导轨安装单相二线分体式（PLC载波通信）代码智能电表：散件5,000，成品10,000\r\n   2）DIN导轨安装单相二线分体式（RF无线通信）代码智能电表：散件5,000，成品15,000', '', '0', '0', '1992250', '', '', '', '', '', '02', null, null, null, null, null, null, null, '1、价格术语CIF Durban,包含保费和运费\r\n2、合同总金额的20%在合同签订之日起10天内通过T/T支付，每批次发货货物总金额的80%通过卖家可接受的不可撤销保兑即期信用证支付，信用证须在启动生产前15天内由卖家收到。', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
