INSERT INTO `crs_tabledata696` VALUES ('161', '{E9C879D8-4730-4687-A0E4-ECCBD1E99154}', '61', 'INHE-0228', '2015-12-25 17:07:53', '0000-00-00 00:00:00', null, '', '', '', null, '0', '销售合同评审流程（v1.2）20131219流程（2015年12月25日17:07）谭雯\\CDN08', null, 'ERANOVE SA', 'ERANOVE SA', '28490', 'CDN08', 'CDN08', '2186910.5', '国际业务二部', '谭雯', '谭雯', '2015-12-25', '海运', '我司', '阿比让', '江西', '无特殊要求，托盘非木质', 'IEC', '成品', '无库存', '', '和CDN已经出货的三相表相比，增加了以下功能：\r\n计量零火互换、负载接地窃电方式下的用电量。\r\n', '同上。', '', '20872', '1896608', '290302.5', '', '2016年3月18日', '', null, '', '03', null, null, null, null, null, null, null, '1. 结算方式：远期60天LC，不保兑。 \r\n2. CFR ABIDJAN \r\n3. 单价不包含运费和保险。 \r\n注： \r\n1. 客户只下PO，不签合同。 \r\n2. SGE将拿佣金，佣金方式为差价，具体差价金额见附件。', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
