INSERT INTO `crs_tabledata696` VALUES ('210', '{4A3292F8-2011-4ED6-A8B9-529ACEE1FEFF}', '53', 'JXINHE-2433', '2016-01-29 14:54:03', '0000-00-00 00:00:00', '2016-03-04 15:39:52', 'unchecked', 'n', 'n', '', '1', 'INHESC2016012965/CZ01/合同评审', '', 'CZ ELECTRONICS MANUFACTURING (PTY) LTD.', 'CZ ELECTRONICS MANUFACTURING (PTY) LTD.', 'INHESC2016012965', 'CZ', 'CZ01', '1361.41', '工业园国际业务部', '黄倩', '黄倩', '2016-01-29', '客户来公司自取', '无运费', '深圳银河表计股份有限公司办公室', '深圳银河表计股份有限公司办公室\r\n', '无', '无', '无', '01', '公司默认要求', '演示箱内容包括：\r\r\r\r\r\r\n1台BS安装单相分体式可更换通信模块（PLC通信）代码预付费电能表\r\r\r\r\r\n1台BS安装三相分体式可更换通信模块（PLC通信）代码预付费电能表(不带键盘)\r\r\r\r\r\n1台DIN安装单相分体式（PLC通信）代码预付费电能表\r\r\r\r\n1台PLC通讯集中器\r\r\r\n2台CIP', '2016年1月26日已收到客户所付演示箱的全款，1月28日客户来深圳办公室已将演示箱取走。由于报表系统1月29日才恢复正常工作，现补加演示箱合同评审。', '', '0', '0', '1361.41', '{4A3292F820114ED6A8B9529ACEE1FEFF3E3FD1A05260451F8D948358003231C8}_Demo Kit Salse Contract演示箱销售合同中英文对照.doc', '2016年1月28日', '', '', '合同评审', '02', null, null, null, null, null, null, null, '价格术语：EXW price\r\n单价中不包含保费和运费', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata696` VALUES ('211', '{DBBF3D34-27B4-4AA9-91B8-7128F6FFE0B5}', '61', 'INHE-0228', '2016-01-29 15:46:05', '0000-00-00 00:00:00', '2016-03-04 15:39:07', 'unchecked', 'n', 'n', '', '1', 'INHESC2016012967/CDN04/合同评审', '', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'SOCIETE GENERALE D\'ELECTRONIQUE\r\n', 'INHESC2016012967', 'CDN', 'CDN04', '12705', '国际业务二部', '谭雯', '谭雯', '2016-01-29', '空运', '我司', 'ABIDJAN', '深圳', '无', 'IEC', '无', '01', '无', '无', '', '', '0', '0', '12705', '{DBBF3D3427B44AA991B87128F6FFE0B53E3FD1A05260451F8D948358003231C8}_CONTRAT ACCESSOIRES CIE.docx', '1月31日', '', '', '合同评审', '02', null, null, null, null, null, null, null, '2015年零零散散发过以上配件，但是当时未做合同评审。因此，此合同评审为补做的合同评审。所有货物都已交付。对应的合同号为：INHESC02150101TW\r\r\r。此合同放在CDN04项目下。\r\r\r\r\n\r\r\r\r\r\r\r\n1. CIP AIRPORT ABIDJAN\r\r\r\r\r\r\r\r\r\r\n2. 两台POS机已经包括了运费，4台集中器有出差人员带给客户，额外收的230美金的运费是给5台集中器和5台采集器。\r\r\r\r\r\r\r\r\n3.付款方式：发货前TT', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
