INSERT INTO `crs_tabledata696` VALUES ('217', '{F5CD27E2-6901-40EF-B20C-1DE83D25A083}', '60', 'INHE-0066', '2016-02-23 09:42:09', '0000-00-00 00:00:00', '2016-02-25 11:02:39', 'unchecked', 'n', 'n', '', '1', 'INHESC2016022373/PO1602/合同评审', '项目编号：白雪602，合同编号：PO#E1602', 'Energomera CJSC', 'Energomera CJSC', 'INHESC2016022373', '白雪', 'PO1602', '67973', '国际业务一部', '邱洁', '邱洁', '2016-02-23', '空运', '客户', '深圳', '深圳', '按空运运输标准', '按公司标准', '配件', '02', '无', '无', '', '', '0', '0', '67973', '{719B396F29E643B7872CC142EE1F9AC2D4CC22B6C7B643389146528155CECD45}_PO E1602 -增加.pdf', '2016-02-29', '{719B396F29E643B7872CC142EE1F9AC29E19E8E731434A848B97C6F1C79E3A54}_PO1602-中文.docx', '', '合同评审', '02', null, null, null, null, null, null, null, '支付方式：16975.2USDT/T-下单前支付，50997.8T/T-发货前支付。\r\n', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata696` VALUES ('218', '{99574504-87BA-4F2B-809A-411B8D86395B}', '60', 'INHE-0066', '2016-02-25 16:57:47', '0000-00-00 00:00:00', '2016-03-02 15:54:11', 'unchecked', 'n', 'n', '', '1', 'INHESC2016022574/E1601/合同评审', '', 'Energomera CJSC', 'Energomera CJSC', 'INHESC2016022574', '白雪', '白雪601', '1079680', '国际业务一部', '邱洁', '邱洁', '2016-02-25', '空运', '客户', '深圳', '深圳', '按空运标准', '按公司标准', '单相多费率智能电表和配件', '02', '新研发产品/变更产品：\r\r\n根据IEC529-89，批量供货产品需符合防护等级IP68\r\r\n在以下环境因素影响下需保证在使用寿命16年内计量单元具备工作性能：\r\r\n-温度：-40-+70C\r\r\n-相对湿度：-98%\r\r\n-最大日温差：30C\r\r\n-最大年温差：100C\r\r\n-大气降水强度：5分钟内达到4mm/分钟, 年均持续时间：2500小时\r\r\n-年均暴露于太阳辐射影响：3*109焦耳/平方米\r\r\n-独立体国家所有气候区使用，应需保证在有湿气进入外壳内计量单元仍具有工作性能。\r\r\n\r\r\n', '1、分批装运：3200套-不晚于2016年4月30日，13585套-不晚于5月15日，3249套-不晚于5月18日。供应商若违反达成一致的交期，则需向买方支付未发货物合同金额的0.5%的日罚款，直到真正履行发货。\r\r\r\n2、若产品不符合技术要求，买方将在签订索赔协议之日起的60天内把不符合要求的产品退回卖方，退货费用卖方承担。同时卖方在签订索赔协议之日起的15天内把已支付的货款退还买方，包括未发货但已支付预付款的货物。', '', '', '20040', '1070000', '9680', '{9957450487BA4F2B809A411B8D86395B3E3FD1A05260451F8D948358003231C8}_E1601.pdf', '2016-04-21', '{9957450487BA4F2B809A411B8D86395B7719915B5AFB4CFC8E75112B161686FE}_PO1601-中文.docx', '{9957450487BA4F2B809A411B8D86395B7842EE48FE5340F2BE4CBD5E93168F23}_Spe58.pdf', '合同评审', '02', null, null, null, null, null, null, null, '1、FCA深圳，2、20%-预付款，80%-发货前付清。', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
