INSERT INTO `crs_tabledata696` VALUES ('228', '{CD8A0F21-D24F-408F-A6AF-1E890D52FD59}', '66', 'INHE-0512', '2016-03-24 09:56:40', '0000-00-00 00:00:00', '2016-03-24 09:56:40', 'unchecked', 'n', 'n', '', '1', 'INHESC2016032497/合同评审', '', 'VBC LIMITADA', 'VBC', 'INHESC2016032497', 'VC', '01', '120', '国际业务三部', '杨振', '杨振', '2016-03-24', '空运', '我方承担', 'Av. Julius Nyerere No. 1597, Maputo-Mo?ambique\r\n', '深圳', '无', '', 'DDZ1513', '01', '', '防护等级IP54', '', '', '2', '120', '0', '{CD8A0F21D24F408FA6AF1E890D52FD593E3FD1A05260451F8D948358003231C8}_INHEPI16031402.pdf', '2016-3-30', '', '', '合同评审', '02', null, null, null, null, null, null, null, 'PI DHL运费260USD中实际包含运费140USD，样品费两台合计120USD', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata696` VALUES ('229', '{10846DAB-5F65-4A08-A573-A92D06DD020C}', '60', 'INHE-0066', '2016-03-29 17:32:25', '0000-00-00 00:00:00', '2016-03-31 16:34:45', 'unchecked', 'n', 'n', '', '1', 'INHESC2016032999/白雪604/合同评审', '', 'Energomera CJSC', 'Energomera CJSC', 'INHESC2016032999', '白雪', '白雪604', '1619520', '国际业务一部', '邱洁', '邱洁', '2016-03-29', '空运', '客户', '深圳', '深圳', '按空运标准', '按公司标准', '单相多费率智能电表和配件		\r\n', '02', '\r\r\n根据IEC529-89，批量供货产品需符合防护等级IP68\r\r\n在以下环境因素影响下需保证在使用寿命16年内计量单元具备工作性能：\r\r\n-温度：-40-+70C\r\r\n-相对湿度：-98%\r\r\n-最大日温差：30C\r\r\n-最大年温差：100C\r\r\n-大气降水强度：5分钟内达到4mm/分钟, 年均持续时间：2500小时\r\r\n-年均暴露于太阳辐射影响：3*109焦耳/平方米\r\r\n-独立体国家所有气候区使用，应需保证在有湿气进入外壳内计量单元仍具有工作性能。\r\r\n\r\r\n						\r\r\n', '1、分批装运：15030套-不晚于2016年5月25日，15030套-不晚于6月8日。卖方若违反达成一致的交期\r\r\n，则需向买方支付未发货物合同金额的0.5%的日罚款，直到真正履行发货。\r\r\r\r\n2、若产品不符合技术要求，买方将在签订索赔协议之日起的60天内把不符合要求的产品退回卖方，退货费用卖方承担。同时卖方在签订索赔协议之日起的15天内把已支付的货款退还买方，包括未发货但已支付预付款的货物。						\r\r\r\r\n', '', '', '30060', '1605000', '14520', '{10846DAB5F654A08A573A92D06DD020C3E3FD1A05260451F8D948358003231C8}_PO and Spe..pdf', '2016-05-25', '{10846DAB5F654A08A573A92D06DD020C7719915B5AFB4CFC8E75112B161686FE}_白雪Specification 61-中英俄.doc', '', '合同评审', '02', null, null, null, null, null, null, null, '1、FCA深圳\r\n2、支付条件：\r\n242 928 USD -不晚于 2016年4月1日支付\r\n242 928 USD -不晚于2016年4月8日支付\r\n566 832 USD - 第一批货 (15 030 pcs.)交货前支付\r\n566 832 USD - 第二批货 (15 030 pcs.)交货前支付\r\n', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
