INSERT INTO `crs_tabledata696` VALUES ('236', '{33D7CAD3-186D-448C-871E-8949FB5BEED7}', '61', 'INHE-0490', '2016-04-14 16:41:50', '0000-00-00 00:00:00', '2016-04-18 17:26:24', 'unchecked', 'n', 'n', '', '1', 'INHESC2016041413/雏菊/合同评审', '', 'Cashpower Sudamericana S.A.', 'Cashpower Sudamericana S.A.', 'INHESC2016041413', '雏菊', '雏菊01', '1860', '国际业务二部', '范辉英', '范辉英', '2016-04-14', 'DHL', '买方', '深圳', '深圳', '每2套表装一个箱子，共计三箱。', 'IEC', 'DDZ1513', '02', '铭牌要按客户要求特殊制作', '这些样机是用于做认证的，对质量要求高，且需要研发根据客户要求出具各项数据和资料。', '', '', '6', '1200', '660', '{33D7CAD3186D448C871E8949FB5BEED73E3FD1A05260451F8D948358003231C8}_SALES CONFIRMATION-雏菊项目销售合同.doc', '2016.04.28', '', '', '合同评审', '02', null, null, null, null, null, null, null, 'CPT阿根廷布宜诺斯艾利斯，100%TT预付，价格含运费不含保费。', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata696` VALUES ('237', '{78A3CD45-99F3-4C34-93A2-7C9419DC5CFA}', '60', 'INHE-0088', '2016-04-21 15:32:33', '0000-00-00 00:00:00', '2016-04-25 10:11:06', 'unchecked', 'n', 'n', '', '1', 'INHESC2016042116/DPM601/合同评审', '', 'DELTAPRIMA METERING SDN BHD', 'DELTAPRIMA METERING SDN BHD', 'INHESC2016042116', 'DPM', 'DPM601', '13700', '国际业务一部', '余冬纯', '余冬纯', '2016-04-21', '海运散货', '我司', 'CIF马来西亚巴生港', '', '', '', '暂无', '02', '常规预付费表', '', '', '', '100', '5740', '7960', '{78A3CD4599F34C3493A27C9419DC5CFA3E3FD1A05260451F8D948358003231C8}_INHESC2016042116.pdf', '2016-6-5', '{78A3CD4599F34C3493A27C9419DC5CFA7719915B5AFB4CFC8E75112B161686FE}_20160420 付款水单.jpg', '{78A3CD4599F34C3493A27C9419DC5CFA7842EE48FE5340F2BE4CBD5E93168F23}_DPM601技术要求.rar', '合同评审', '02', null, null, null, null, null, null, null, 'CIF马来西亚巴生港		\r\r\r\n单独收取保费和运费\r\r\r\n50%预付款，50%发货30天后付款，16年4月21日到账USD6850', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata696` VALUES ('238', '{525DCB52-11F9-408C-8DC7-F114C7DCDD30}', '61', 'INHE-0434', '2016-04-25 15:32:08', '0000-00-00 00:00:00', '2016-04-28 10:11:24', 'unchecked', 'n', 'n', '', '1', 'INHESC2016042517/YL/合同评审', '', 'SANA Meter Co.ltd', 'SANA Meter Co.ltd', 'INHESC2016042517', 'YL', 'YL', '77272', '国际业务二部', '钟云林(Andy)', '钟云林', '2016-04-25', '50pcs空运，500pc海运', '客户承担', '德黑兰', '深圳', '标准(货物应该包装在牢固的纸箱里，方便空运和海运)', 'IEC', 'DTZ1513', '02', '（1）具有M-BUS通讯功能；\r\r\n（2）DLMS/COSEM协议,且具有RS485通讯接口；\r\r\n（3）远程控制拉合闸（3种状态），远程告警，远程充值；\r\r\n（4）负荷曲线3种状态查询(平均，最小，最大) \r\r\n（5）2条可编程负荷曲线供水表/气表使用；\r\r\n（6）模块更换事件记录；\r\r\n（7）普通以及特殊负荷门限控制/设置；\r\r\n（8）防窃电事件记录及主动上报，包括开端盖、开表盖、过载、失压、反向、电流不平衡、磁场干扰等；\r\r\n（9）断电开盖检测；\r\r\n（10）断电可读；\r\r\n（11）使用寿命大于20年；\r\r\n（12）AES128加密机制', '', '', '', '0', '0', '11272', '', '2016-5-25', '', '{E42F7AE50AD3458D9D3EAC862397FEBFBA0F4BB9344A4053BE173BB06528647F}_20160428_SALES CONFIRMATION-YL.doc', '合同评审', '02', null, null, null, null, null, null, null, '1. 价格条款：CFR伊朗德黑兰\r\n2. 单价中不含保费和运费，运费另收，运费里不含保费。', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
