INSERT INTO `crs_tabledata696` VALUES ('242', '{602E8257-DAA7-F7FC-D513-113BDED413E1}', '55', 'INHE-0260', '2016-05-10 13:58:42', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'y', null, '1', null, null, 'Energomera CJSC', 'SUDANESE CHINESE METER FACTORY', 'INHESC2016051027', '白雪', '白雪605', '15834', '国际业务一部', '邱洁', '邱洁', '2016-05-10', '空运', '客户', '深圳', '深圳', '按空运运输标准', '按公司标准', '配件', '02', '翻单', '无', '', '', '0', '0', '15834', '{764DF18E18F84D64B0D408956142C88E3E3FD1A05260451F8D948358003231C8}_PO E1605.pdf', '2016-04-20', '{764DF18E18F84D64B0D408956142C88E7719915B5AFB4CFC8E75112B161686FE}_PO1603-中文.docx', '{78A3CD4599F34C3493A27C9419DC5CFA7842EE48FE5340F2BE4CBD5E93168F23}_DPM601技术要求.rar', '合同评审', '02', null, null, null, null, null, null, null, '1、FCA深圳。\r\n2、因金额不大，特申请货款在发货前100%TT付清。', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata696` VALUES ('243', '{8227AC82-FB81-416B-8436-4F60DCE643C3}', '61', 'INHE-0228', '2016-05-13 17:56:52', '0000-00-00 00:00:00', '2016-05-18 18:03:29', 'unchecked', 'n', 'n', '', '1', 'INHESC2016051331/06/合同评审', '', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'INHESC2016051331', 'CDN', 'CDN06', '88950', '国际业务二部', '谭雯', '谭雯', '2016-05-13', '空运', '我司', '阿比让', '江西', '非木质', 'IEC', '模块表', '02', '1.三相四线直接介入可更换通信模块代码智能表(不带模块) :此款产品和CDN出货的三相表不一样，需要支付DLMS via RS485，目的是用于兼容到BOUYUES的路灯抄表系统。此前也出过样机，调试成功。见OA《CDN06样机申请》。\r\n2.CT表没有特殊要求。 \r\n', '1. 客户已经发来PO的草稿，正式的PO在签字流程中。因此请先做合同评审和启动生产备料。\r\r\n2. 本来CDN06是专门针对CDN自己的路等项目的特殊表，但是电力公司将CT的订单也下在这个PO里面，因此CDN06的合同和生产通知单也将包括CT表。\r\r\n', '', '', '400', '83000', '5950', '{8227AC82FB81416B84364F60DCE643C33E3FD1A05260451F8D948358003231C8}_PO N°16000511 CA.pdf', '2016.7.20', '{8227AC82FB81416B84364F60DCE643C37719915B5AFB4CFC8E75112B161686FE}_CDN06 PO翻译.doc', '', '合同评审', '03', null, null, null, null, null, null, null, '1.CPT ABIDJAN\r\n2.单价不保函运费，另收运费5950EUR。\r\n3.结算方式，发货后60天TT付款。已OA审批、并审批。\r\n4.代理的佣金：直通表39.13EUR/表，CT表-47.88EUR/表。代理支付佣金税费。\r\n', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
