INSERT INTO `crs_tabledata696` VALUES ('253', '{CA99EE5C-3CE5-AC41-608A-EB759D693C0B}', '55', 'INHE-0260', '2016-06-13 17:12:14', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'y', null, '1', null, null, 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'Letech Technologies', 'INHESC2016061301', 'CDN', 'CDN06', '88950', '国际业务二部', '谭雯', '谭雯', '2016-06-13', '空运', '我司', '阿比让', '江西', '非木质', 'IEC', '模块表', '02', '1.三相四线直接介入可更换通信模块代码智能表(不带模块) :此款产品和CDN出货的三相表不一样，需要支付DLMS via RS485，目的是用于兼容到BOUYUES的路灯抄表系统。此前也出过样机，调试成功。见OA《CDN06样机申请》。\r\n2.CT表没有特殊要求。 \r\n', '1. 客户已经发来PO的草稿，正式的PO在签字流程中。因此请先做合同评审和启动生产备料。\r\r\n2. 本来CDN06是专门针对CDN自己的路等项目的特殊表，但是电力公司将CT的订单也下在这个PO里面，因此CDN06的合同和生产通知单也将包括CT表。\r\r\n', '', '', '400', '83000', '5950', '{8227AC82FB81416B84364F60DCE643C33E3FD1A05260451F8D948358003231C8}_PO N°16000511 CA.pdf', '2016.7.20', '{8227AC82FB81416B84364F60DCE643C37719915B5AFB4CFC8E75112B161686FE}_CDN06 PO翻译.doc', '', '合同评审', '03', null, null, null, null, null, null, null, '1.CPT ABIDJAN\r\n2.单价不保函运费，另收运费5950EUR。\r\n3.结算方式，发货后60天TT付款。已OA审批、并审批。\r\n4.代理的佣金：直通表39.13EUR/表，CT表-47.88EUR/表。代理支付佣金税费。\r\n', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata696` VALUES ('254', '{8D88ED29-794D-48D6-B13F-FD11E0ED3693}', '61', 'INHE-0222', '2016-06-15 11:13:20', '0000-00-00 00:00:00', '2016-06-29 15:04:05', 'unchecked', 'n', 'n', '', '1', 'INHESC2016061503/PSA10/合同评审', '', 'STAEKKA SAS', 'DISICO S.A.', 'INHESC2016061503', 'PSA10', 'PSA10', '191000', '国际业务二部', '张红丽', '张红丽', '2016-06-15', '海运/空运', '客户', '深圳', '江西', '标准海运或空运包装', 'IEC62053-21，IEC62055-31', 'DDZ1513', '02', '2000台订单为翻单产品，3000台为新研发产品。', '合同向对方说明：\r\r\r\r\r\n\r\r\r\r\r\nPSA10项目立项时用的客户名称为STAEKKA S.A.S.（PSA6合作代理），实际签合同使用客户名称为DISICO S.A.（PSA6项目直接投标方），合同签订前才得到确认，特此说明。\r\r\r\r\r\n\r\r\r\r\r\n', '', '', '5000', '191000', '0', '{8D88ED29794D48D6B13FFD11E0ED36933E3FD1A05260451F8D948358003231C8}_PSA10-合同.rar', '2016-07-30', '', '', '合同评审', '02', null, null, null, null, null, null, null, '1.合同价格术语：FOB深圳，不包含运费和保费。\r\r\r\r\r\r\n2.2000台订单，100%T/T付款，不带LCD，要求7月30日完成生产交货；\r\r\r\r\r\r\n3.3000台订单，合同签订后T/T预付30%，70%尾款发货前T/T支付，带LCD显示，要求8月13日完成生产；\r\r\r', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
