INSERT INTO `crs_tabledata696` VALUES ('261', '{EC80BD22-26ED-40B8-AC87-E8B455F94E20}', '60', 'INHE-0066', '2016-06-27 09:42:02', '0000-00-00 00:00:00', '2016-06-29 14:59:39', 'unchecked', 'n', 'n', '', '1', 'INHESC2016062701/白雪608/合同评审', '', 'Energomera CJSC', 'Energomera CJSC', 'INHESC2016062701', '白雪', '白雪608', '539840', '国际业务一部', '邱洁', '邱洁', '2016-06-27', '空运', '客户', '深圳', '深圳', '按空运标准', '按公司验收标准', '单相多费率智能电表和配件		\r\n		\r\n', '02', '翻单', '\r\r\n根据IEC529-89，批量供货产品需符合防护等级IP68\r\r\n在以下环境因素影响下需保证在使用寿命16年内计量单元具备工作性能：\r\r\n-温度：-40-+70C\r\r\n-相对湿度：-98%\r\r\n-最大日温差：30C\r\r\n-最大年温差：100C\r\r\n-大气降水强度：5分钟内达到4mm/分钟, 年均持续时间：2500小时\r\r\n-年均暴露于太阳辐射影响：3*109焦耳/平方米\r\r\n-独立体国家所有气候区使用，应需保证在有湿气进入外壳内计量单元仍具有工作性能。', '1、10020套-不晚于2016年8月5日，卖方若违反达成一致的交期\r\r\r\n，则需向买方支付未发货物合同金额的0.5%的日罚款，直到真正履行发货。\r\r\r\n2、若产品不符合技术要求，买方将在签订索赔协议之日起的60天内把不符合要求的产品退回卖方，退货费用卖方承担。同时卖方在签订索赔协议之日起的15天内把已支付的货款退还买方，包括未发货但已支付预付款的货物。						\r\r\r\n						\r\r\r\n', '', '10020', '535000', '4840', '{EC80BD2226ED40B8AC87E8B455F94E203E3FD1A05260451F8D948358003231C8}_Specification 65 vers.1.doc', '2016-08-5', '{EC80BD2226ED40B8AC87E8B455F94E207719915B5AFB4CFC8E75112B161686FE}_白雪Specification 65-中.doc', '', '合同评审', '02', null, null, null, null, null, null, null, '1、FCA深圳\r\r\n2、支付条件：\r\r\n161 952 USD -不晚于 2016年7月5日支付\r\r\n377 888 USD -不晚于2016年8月15日支付\r\r\n\r\r\n						\r\r\n', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
