INSERT INTO `crs_tabledata696` VALUES ('273', '{92244A9C-0523-4E44-84F5-DDDD64C9B6A3}', '61', 'INHE-0534', '2016-07-08 16:29:28', '0000-00-00 00:00:00', '2016-08-11 11:40:39', 'unchecked', 'n', 'n', '', '1', 'INHESC2016070807/MCA01/合同评审', '', 'Millennium Challenge Account - Malawi', 'Millennium \r\nChallenge Account \r\n- Malawi\r\n', 'INHESC2016070807', 'MCA', 'MCA01', '2737952', '国际业务二部', '徐聪', '林丽璇,李新国', '2016-07-08', '海陆联运', '银河', '29个变电站', '待定', '外购产品木箱包装', '按照客户确认技术规格验收', '', '02', '', '1.此项目是交钥匙工程，变电站项目，涉及29个变电站的整体设计方案，包括现场勘查、计量设备采\r\r\n购及现场施工等。\r\r\n\r\r\n', '', '', '0', '0', '2478579', '{D16E098C6A7549A5891AFD5A54C8D230D4CC22B6C7B643389146528155CECD45}_Inhemter MCA signed contract.pdf', '2016年9月10日', '{D16E098C6A7549A5891AFD5A54C8D2309E19E8E731434A848B97C6F1C79E3A54}_MCA 合同修改件六.docx', '', '合同评审', '02', null, null, null, null, null, null, null, '1. 产品单价 CIP Malawi \r\r\r\n2.付款方式：\r\r\r\n(a)签署合同及提交预付款保函后：预付合同金额10%\r\n(b)发货后：不可撤销保兑即期信用证支付合同金额50%\r\n(c)货物交付安装验收后：付款合同金额20%\r\n(d)测试调试验收后：付款合同金额20%', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
