INSERT INTO `crs_tabledata696` VALUES ('322', '{AB4129E0-7EA7-47BA-AFD0-CF3546CC2D3C}', '60', 'INHE-0066', '2016-10-31 10:15:58', '0000-00-00 00:00:00', '2016-11-09 16:35:43', 'unchecked', 'n', 'n', '', '1', 'PO#E1616/白雪616/合同评审', '', 'Energomera CJSC', 'Energomera CJSC', 'PO#E1616', '白雪', '白雪616', '2599200', '国际业务一部', '邱洁', '邱洁', '2016-10-31', '海运', '客户', '深圳', '深圳', '按海运运输标准', '按公司验收标准', '单相多费率只能电表和配件', '02', '新研发产品/变更产品：\r无需灌胶和喷三防漆\r\r\n根据IEC529-89，批量供货产品需符合防护等级IP68\r\r\r\n在以下环境因素影响下需保证在使用寿命16年内计量单元具备工作性能：\r\r\r\n-温度：-40-+70C\r\r\r\n-相对湿度：-98%\r\r\r\n-最大日温差：30C\r\r\r\n-最大年温差：100C\r\r\r\n-大气降水强度：5分钟内达到4mm/分钟, 年均持续时间：2500小时\r\r\r\n-年均暴露于太阳辐射影响：3*109焦耳/平方米\r\r\r\n-独立体国家所有气候区使用，应需保证在有湿气进入外壳内计量单元仍具有工作性能。\r\r\r\n\r\r\r\n						\r\r\r\n', '', '', '', '51500', '2575000', '24200', '{AB4129E07EA747BAAFD0CF3546CC2D3C3E3FD1A05260451F8D948358003231C8}_PO E1616.pdf', '2016-12-1', '{AB4129E07EA747BAAFD0CF3546CC2D3C7719915B5AFB4CFC8E75112B161686FE}_PO1616-中文.docx', '', '合同评审', '02', null, null, null, null, null, null, null, '1、FOB深圳2、20%T/T-预付款，80%T/T-发货前付清3、不含运费和保费', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata696` VALUES ('323', '{F14C459C-EC5E-4C2F-999C-C9114E9883F2}', '60', 'INHE-0066', '2016-11-08 15:59:30', '0000-00-00 00:00:00', '2016-11-10 17:36:14', 'unchecked', 'n', 'n', '', '1', 'INHESC2016110805/白云603/合同评审', '', '\"Aspan-Energy \" LTD', '\"Aspan-Energy \" LTD', 'INHESC2016110805', '白云', '白云603', '168550', '国际业务一部', '邱洁', '邱洁', '2016-11-08', '陆运', '客户把运费支付给我司，我司再把运费支付给货代。			\r\n', '深圳', '深圳', '按陆运运输标准', '按公司验收标准', '单相智能电表配件', '02', '翻单', '按2015年11月研发提供的最新样机供货。						\r\n', '', '', '0', '0', '168550', '{34FBA6210D98453FAE96BE59F927C59CD4CC22B6C7B643389146528155CECD45}_白云603运费客户签字-20170619.JPG', '2016年12月20日', '', '', '合同评审', '02', null, null, null, null, null, null, null, '1.FCA深圳 2.50%T/T-下单前支付，50%T/T尾款-发货前支付。	3、单价不包含保费和运费。					\r\r\r\n						\r\r\r\n						\r\r\r\n', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata696` VALUES ('324', '{E270AF30-C92E-404B-BD39-F0B86FD9CB0F}', '61', 'INHE-0222', '2016-11-10 10:32:08', '0000-00-00 00:00:00', '2016-11-24 09:13:19', 'unchecked', 'n', 'n', '', '1', 'INHESC2016110701\r\n/PSA10605/合同评审', '', 'STAEKKA SAS', 'MESSEN S.A.S', 'INHESC2016110701\r\n', 'PSA10', 'PSA10605', '450000', '国际业务二部', '张红丽', '张红丽', '2016-11-10', '海运', '客户', '深圳', '江西', '标准海运', 'IEC62055-31', 'DDZ1513', '02', '无', '1.此为PSA10项目翻单，项目编号PSA10605。\r\r\r\n2.请务必确保交期，要求12月10日从工厂发货。\r\r\n3.按合同数量赠送0.1%的备用表。', '', '', '12012', '450000', '0', '{E270AF30C92E404BBD39F0B86FD9CB0F3E3FD1A05260451F8D948358003231C8}_PSA10605-SALES CONFIRMATION-20161107.pdf', '2016-12-10', '', '', '合同评审', '02', null, null, null, null, null, null, null, '1.报价术语：FOB 深圳\r\n2.结算方式：30%预付款合同签订后3日内T/T支付，70%尾款发货前T/T支付。\r\n3.单价中不包含运费或保费。', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata696` VALUES ('325', '{90BCB98C-518F-4505-B848-FA192B683D3C}', '61', 'INHE-0051', '2016-11-10 14:21:54', '0000-00-00 00:00:00', '2016-11-24 09:12:52', 'unchecked', 'n', 'n', '', '1', 'INHESC2016111001\r\n/PY03/合同评审', '', 'The Kenya Power * Lighting Company Limited', 'The Kenya Power * Lighting Company Limited', 'INHESC2016111001\r\n', 'PY03', 'PY03', '8484588', '国际业务二部', '盛燕', '盛燕', '2016-11-10', '海运', '卖家', 'Ruaraka Meter Store，Nairobi,Kenya', '中国', '按照标书要求，需业务确认', '', '', '02', '见PY03招标技术规格', '', '', '', '180600', '7314300', '1170288', '{90BCB98C518F4505B848FA192B683D3C3E3FD1A05260451F8D948358003231C8}_PY03合同-待签字.pdf', '2017年1月30日', '{90BCB98C518F4505B848FA192B683D3C7719915B5AFB4CFC8E75112B161686FE}_PY03 合同 中英对照.docx', '', '合同评审', '02', null, null, null, null, null, null, null, '1.DAP不含VAT单价为40.5USD，每台VAT 6.48USD，推算FOB为37.90USD，FOB到DDP每台电表9.08USD\r\r\r\r\n2.付款方式为：交货到客户仓库后，提交发票等收款资料后30天内通过T/T付款\r\r\r\r\r\r\r\n3.中标函见附件合同文件中第44页，合同模板和此市场的PY02,PX项目一样，见附件中英对照合同。', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata696` VALUES ('326', '{ED77B25E-B0BF-41EF-94DE-08DA09874354}', '66', 'INHE-0579', '2016-11-10 15:11:23', '0000-00-00 00:00:00', '2016-11-24 09:11:52', 'unchecked', 'n', 'n', '', '1', 'INHESC2016101101/CG-02/合同评审', '', 'DREXEL INTERNATIONAL LTD', 'DREXEL INTERNATIONAL LTD\r\n', 'INHESC2016101101', 'CG', 'CG-02', '564', '国际业务三部', '孙娜', '宋宁', '2016-11-10', '空运', '我司', '迪拜', '中国任意港', '适合空运', '', 'BS型三相四线电能表\r\n', '01', '新研发产品/变更产品      \r\n', '无', '', '', '1', '544', '20', '{ED77B25EB0BF41EF94DE08DA098743543E3FD1A05260451F8D948358003231C8}_销售合同.pdf', '完成支付20天内交货', '', '', '合同评审', '02', null, null, null, null, null, null, null, '1、价格术语CIP，包括保险和运费 ，合同100%金额在发货前通过TT支付.   2、运保费为461美元. \r\r\r\n', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata696` VALUES ('327', '{E44411EA-6B96-4D1F-8A9E-B69D7D50895E}', '61', 'INHE-0576', '2016-11-17 08:29:57', '0000-00-00 00:00:00', '2016-11-17 10:16:42', 'unchecked', 'n', 'n', '', '1', 'INHESC2016110402\r\n/IMF02/合同评审', '', 'The kenya power lighting company limited', 'INHEMETER AFRICA COMPANY LIMITED', 'INHESC2016110402\r\n', 'A51', 'IMF02', '17342.42', '国际业务二部', '戴萍(Eileen)', '', '2016-11-17', '', '', '', '', '', '', '', '', '', '', '', '', '0', '0', '17342.42', '', '2016.10.30', '', '', '合同评审', '02', null, null, null, null, null, null, null, '', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata696` VALUES ('329', '{CDEB23A0-0B56-43EE-9EEE-F7F829217C12}', '61', 'INHE-0576', '2016-11-17 10:46:04', '0000-00-00 00:00:00', '2016-11-28 09:06:25', 'unchecked', 'n', 'n', '', '1', 'INHESC2016110402/IMF02/合同评审', '', 'INHEMETER AFRICA CO., LTD.', 'INHEMETER AFRICA CO., LTD.', 'INHESC2016110402', 'IMF', 'IMF02', '66838.7495', '国际业务二部', '戴萍(Eileen)', '', '2016-11-17', '海运', '', '\r\r\n', '', '', '', '', '', '', '1.对合同货描、单价、总价进行了变更，合同金额由【USD28,512.89】变为【USD 66,838.75】。\r\n\r\n2.价格术语变更为DDP（IAC工厂）', '', '', '0', '0', '66838.7495', '{C5B09284DBFF4C1F832A450F29EDD129D4CC22B6C7B643389146528155CECD45}_IMF02设备合同20180411 V1.docx', '2016.10.30', '{C5B09284DBFF4C1F832A450F29EDD1299E19E8E731434A848B97C6F1C79E3A54}_2016年10月10日建厂设备报关底单400220160000011803.pdf', '{C5B09284DBFF4C1F832A450F29EDD129BA0F4BB9344A4053BE173BB06528647F}_Value verification of equipment IAC签字版.pdf', '合同评审', '02', null, null, null, null, null, null, null, 'DDU到买家在肯尼亚内罗毕的工厂\r\r\r\n，T/T付款，提单日后60天内通过T/T支付合同总金额，\r\r\n单价中不包含运费', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata696` VALUES ('330', '{F554892D-C729-4B89-84B7-5BA72B752D4F}', '60', 'INHE-0535', '2016-11-18 09:43:56', '0000-00-00 00:00:00', '2016-11-24 09:11:22', 'unchecked', 'n', 'n', '', '1', 'INHESC2016111601/ST20615/合同评审', '', 'SUDANESE ELECTRICITY DISTRIBUTION CO.LTD.', 'Sudanese Chinese Meter Factory\r\n苏丹\r\n中国表厂\r\n', 'INHESC2016111601', 'ST20', 'ST20615', '13120000', '国际业务一部', '左亚楠', '王维', '2016-11-18', '海运', '卖方', '苏丹港', '任意中国港口', '货物应包装在牢固的纸箱里，方便海运', '按买卖双方提前商定的验货计划', '', '', '无', '', '', '', '320000', '13120000', '0', '{F554892DC7294B8984B75BA72B752D4F3E3FD1A05260451F8D948358003231C8}_ST20615SC.pdf', '按照5批交货，每批数量相同。第一批50%开船不晚于2016.12.15；另50%开船不晚于2016.12.25；其余批次货物在前批货物发出之日起60天内备好并发出。', '', '', '合同评审', '03', null, null, null, null, null, null, null, '1.价格术语：CFR Port Sudan, CFR苏丹港；  \r\r\r\r\r\r\r\r\r\n  结算方式及期限：由Omduran 银行开出不可撤销，不保兑即期循环信用证：\r\r\r\n1）金额不少于Euro 2624000；\r\r\r\n2）可循环次数不少于5次；\r\r\r\n3）信用证金额的10%预付款应在信用证开出之日起7天之内支付给受益人，受益人提供由受益人公司信头纸出具的保证函；\r\r\r\n4）发货后卖方将提交全套货运单据扫描件给信用证开出行用于议付信用证金额剩余90%的货款；\r\r\r\n5）收到信用证金额90%货款后，卖方在到款日当天将货运单据原件通过快递发给买方或者开证行（按照买\r方指示）\r\r\r\r\r\r\r\n\r\r\r\r\r\r\n\r\r2.包含运费\r：0.5%\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\r\r\r\n\r\r\r\n\r\r\r\n\r\r\r\n', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata696` VALUES ('331', '{E8458F55-FEAA-4572-9940-5C7231984270}', '66', 'INHE-0579', '2016-12-01 09:00:56', '0000-00-00 00:00:00', '2017-01-09 11:18:05', 'unchecked', 'n', 'n', '', '1', 'INHESC2016111401/CG-03/合同评审', '', 'DREXEL INTERNATIONAL LTD', 'DREXEL INTERNATIONAL LTD', 'INHESC2016111401\r\n', 'CG', 'CG-03', '405', '国际业务三部', '孙娜', '宋宁', '2016-12-01', '空运', '我司', '基加利', '中国任意机场', '适合空运', '', 'BS型三相四线电能表\r\n', '01', '新研发产品/变更产品      \r\n', '无', '', '', '1', '83', '322', '{E8458F55FEAA457299405C72319842703E3FD1A05260451F8D948358003231C8}_Sales Contract  for Sample Meters.doc.pdf', '完成支付20天内交货\r\n', '', '', '合同评审', '02', null, null, null, null, null, null, null, '1、价格术语CIP，合同100%金额在发货前通过TT支付.   2、单价不包含运费', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
