INSERT INTO `crs_tabledata696` VALUES ('353', '{E63CCD9D-9EE5-4389-8311-6790D8B22859}', '61', 'INHE-0222', '2017-02-17 13:51:25', '0000-00-00 00:00:00', '2017-02-20 15:56:27', 'unchecked', 'n', 'n', '', '1', 'INHESC2017021201/PSA10701/合同评审', '', 'STAEKKA SAS', 'MESSEN S.A.S', 'INHESC2017021201', 'PSA10', 'PSA10701', '224100', '国际业务二部', '张红丽', '张红丽', '2017-02-17', '标准海运', '客户', '深圳', '江西', '标准海运包装', 'IEC标准', 'DDZ1513， DTZ1513', '02', '无', '1.单相表5000套为PSA10项目翻单，项目编号PSA10701；\r\r\n2.三相表366套为PSA6项目翻单，项目编号PSA6701；\r\n3.两个项目为同一个采购方，同一家电力公司，所以签同一个合同。\r\n4.电力公司翻单交期很紧，要求两款产品30天内完成生产。', '', '', '5366', '224100', '0', '{E63CCD9D9EE5438983116790D8B228593E3FD1A05260451F8D948358003231C8}_PSA10701-SALES CONFIRMATION-20170215 (002).pdf', '2017-03-20', '', '', '合同评审', '02', null, null, null, null, null, null, null, '1.价格术语：FOB Shenzhen；\r\n2.结算方式：30%预付款合同签订后3日内T/T支付，70%尾款发货前两周内T/T支付；\r\n3.报价不含运费或保费。', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
