INSERT INTO `crs_tabledata696` VALUES ('358', '{80358E58-8097-4D64-A2DB-7D4B770FA6E5}', '61', 'INHE-0434', '2017-03-01 16:17:09', '0000-00-00 00:00:00', '2017-03-01 16:54:04', 'unchecked', 'n', 'n', '', '1', 'INHESC2017030103/合同评审', '', 'Ethiopian Electric Utility', 'Ethiopian Electric Utility', 'INHESC2017030103', 'SRM06', '01', '0', '国际业务二部', '钟云林(Andy)', '钟云林', '2017-03-01', '空运', '我司承担', '埃塞俄比亚首都亚迪斯亚贝巴', '江西工业园(如果确认是江西工业园负责生产)', '无特殊要求，保障产品不会在运输途中受损', '无特殊要求', 'DDZ1513和DTZ1513', '', '无特殊技术要求，此项目采用银河标准规格，向电力公司推广新技术和方案\r\n', '无特殊技术要求，此项目采用银河标准规格，向电力公司推广新技术和方案\r\n', '无，附件为电力公司和银河双方签字盖章MOU（代替合同），同时附上中英版。中英版已经过喻美娥校对。', '', '26', '0', '0', '{80358E5880974D64A2DB7D4B770FA6E53E3FD1A05260451F8D948358003231C8}_【SRM06】【MOU】 20170301.pdf', '2017年4月15号', '{80358E5880974D64A2DB7D4B770FA6E57719915B5AFB4CFC8E75112B161686FE}_SRM06(智能表试点MoU)中英文版-喻美娥.pdf', '{80358E5880974D64A2DB7D4B770FA6E57842EE48FE5340F2BE4CBD5E93168F23}_SRM06产品清单.pdf', '合同评审', '02', null, null, null, null, null, null, null, 'SRM06项目为银河承担项目费用', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata696` VALUES ('359', '{464DE864-5713-4660-958B-F01F356B714F}', '60', 'INHE-0549', '2017-03-02 08:21:35', '0000-00-00 00:00:00', '2017-03-06 14:54:34', 'unchecked', 'n', 'n', '', '1', 'INHESC2017022202/KM/合同评审', '', 'KAMA.SA', 'KAMA-SA', 'INHESC2017022202', 'KM', 'KM01', '5917677.56', '国际业务一部', '王秀明', '王维,王秀明', '2017-03-02', '海运', '我司，如果实际的运费和保险费用与合同不符，双方将以书\r\n面补充协议的形式协商确定最终的费用。在了解实际运费后，买方可选择向我方TT或LC支付运费和保险费。', '交付给马里的产品的卸货港为塞内加尔达喀尔港，交付给几内亚的为几内亚科纳克里港', '中国九江港\r\n', '牢固的纸箱', 'IEC62052-11, IEC62053-21，IEC62053-22', '1513DDZ1513，DTZ1513等', '02', '', '客户要求产品安装好后发货（只需接进线和出线就可以使用）', '', '', '93851', '3106932.77', '2810744.79', '', '给马里的货物为收到信用证后，给几内亚的三批货物为收到尾款后，三批交货截止日期为2018年3月31日，6月30日和12月30日', '', '{443F9ED777C542C28EA5B1A6BF4399AEBA0F4BB9344A4053BE173BB06528647F}_KM第三号补充协议.docx', '合同评审', '02', null, null, null, null, null, null, null, 'FOB JIUJIANG或客户指定的其他任意中国港口，结算方式是保兑90天远期信用证，产品单价中不包含运保费，但包含2%的客户佣金和1.5%的福费廷手续费。', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
