INSERT INTO `crs_tabledata696` VALUES ('469', '{47A1C780-1F06-4C94-BC6A-1A456FBCA278}', '61', 'INHE-0381', '2017-10-26 16:45:23', '0000-00-00 00:00:00', '2017-10-27 14:18:20', 'unchecked', 'n', 'n', '', '1', 'INHESC2017092402/BFN07/合同评审', '', 'TOGO ASSISTANCE SERVICES', 'TOGO ASSISTANCE SERVICES', 'INHESC2017102603', 'BFN', 'BFN07', '60800', '国际二部 INTL.Business Dept.2', '张柳芳(Alexie)', '胡蝶，张柳芳', '2017-10-26', '空运', '我司', 'CIP Ouadagoudou		\r\n', '江西九江', '纸箱包装', 'IEC', 'DTZ1513', '', '', '1. 因300台CT表挪用PSA项目物料，PSA项目产品将空运，空运费由此项目支出，5500USD。其中BFN05空运运费为4300USD，因此合同中总运费9800USD。\r\r\n2. 300台CT表在BFN04的样机制作上修改一些跳闸功能，无其他特殊要求。', '', '', '300', '51000', '9800', '{47A1C7801F064C94BC6A1A456FBCA2783E3FD1A05260451F8D948358003231C8}_BFN07合同 300台20171026.docx', '2017.10.31', '', '', '合同评审', '02', 'CIP Ouadagoudou', '签回合同', '12个月', '是，提单日后30天T/T。', '是', '否', '提单日后30天100%T/T', '单价不包含运费。', '02', '01', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata696` VALUES ('471', '{5832B34D-C66B-4923-8ACB-7D3881E8F1EB}', '61', 'INHE-0675', '2017-10-26 18:00:30', '0000-00-00 00:00:00', '2017-10-27 17:06:31', 'unchecked', 'n', 'n', '', '1', 'INHESC2017102601/BFN05/合同评审', '', 'TOGO ASSISTANCE SERVICES', 'TOGO ASSISTANCE SERVICES', 'INHESC2017102601', 'BFN', 'BFN05', '679864', '国际二部 INTL.Business Dept.2', '李佳嘉', '胡蝶', '2017-10-26', '海运', '客户希望我司购买保险，咨询后保险费用为1464USD', '瓦加杜古集装箱堆场，布基纳法索\r\r\r\r\n', '江西九江', '坚固纸箱', 'IEC', 'DTZ-1513', '02', '产品须严格按照技术规格表制作。', '在本合同下的3500台电表生产之前，银河有义务向TAS提供两台样机。TAS将把这两台样机送到SONABEL，确保这两台样机遵守本合同规定的技术规格，并让SONABEL确定样机。没有SONABEL对这两台样机的确定函，INHEMETER不能生产3500台电表。', '', '', '0', '0', '84864', '{191D40E597B642EEB622275EFE489513D4CC22B6C7B643389146528155CECD45}_BFN05合同 3500台 20180208.docx', '2017-12-26', '', '', '合同评审', '02', 'CPT Ouadagoudou, Burkina Faso', '本合同中的产品，将在卖方收到T/T支付的合同金额的20% #FE54`即135 680USD作为预付款后60天内，并在卖方收到覆盖80%合同金额的不可撤销的保兑的远期60天的信用证且信用证条款须被合同双方接受后，从卖方工厂发出。', '12个月', '否', '否', '否', '本合同中金额合计USD678 400，付款方式为合同金额的20%在签订合同10天之内作为预付款T/T支付，余款80%通过不可撤销的保兑的远期60天信用证支付。信用证应当在合同签订之后15天内被卖方收到，且在卖方工厂启动原材料备料前信用证的条款应当取得卖方的认可。', '否，9200USD已单独列出', '05', '01', '参见BFN04历史报价', null, null, null, null, null, null, null, null, null, null, null, null, null, null);
