INSERT INTO `crs_tabledata696` VALUES ('491', '{E69D6290-518A-49DC-8341-4109045785FB}', '61', 'INHE-0645', '2017-11-22 18:44:57', '0000-00-00 00:00:00', '2017-11-29 09:17:56', 'unchecked', 'n', 'n', '', '1', 'INHESC2017110601/BN11/合同评审', '', 'Société Générale d\"Electronique', 'Société Générale d\"Electronique', 'INHESC2017110601', 'BN', 'BN11', '372900', '国际二部 INTL.Business Dept.2', '朱偲赵燚', '朱偲赵燚', '2017-11-22', '5000台单相表要求先用空运的方式发出，剩下的电表使用海运方式。', '买家', '贝宁，科托努', '银河江西工厂', '标准纸箱包装', 'IEC', 'DDZ1513', '01', '', 'BN11 客户希望把原来TN11 的货转发给BN11， 对于单相表需要更改铭牌和SGC码，由此会产生返工费，目前单相表已生产完，三相表还未生产。', '', '', '0', '0', '31173', '{5B951CF40E9643AB96D91A3929BAE634D4CC22B6C7B643389146528155CECD45}_BN合同单相表v.20171212.docx', '2018-1-15', '', '', '合同评审', '02', 'CIF 科托努，贝宁', '最迟于收到预付款和被银河认可的信用证，并且TAS确认样机合格后60天后，从INHEMETER的工厂发出', '卖方所提供货物的保修期为从卖方工厂发货之日起12个月。', '否', '否', '否', '20%预付款，即196423.8 USD在合同签订后10天内通过T/T支付，TAS收到INHEMETER的样机并确认合格后，INHEMETER开始生产， 80%余款，即785695.2 USD 使用不可撤销的由一级信用银行保兑的远期60天的信用证支付。信用证应当发货前被INHEMETER收到，且在INHEMETER工厂启动原材料备料前，信用证的条款应当取得INHEMETER的认可', '单价中不包含保费和运费，但包含3USD/台的返工费', '02', '01', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null);
