INSERT INTO `crs_tabledata696` VALUES ('498', '{F24E7391-9EC1-468F-A703-D3D1BAA3C88E}', '61', 'INHE-0228', '2017-11-24 10:49:48', '0000-00-00 00:00:00', '2017-11-28 08:34:15', 'unchecked', 'n', 'n', '', '1', 'INHESC2017112301\r\n/WEN/合同评审', '', 'METRIMA AB', 'METRIMA AB', 'INHESC2017112301\r\n', 'WEN', 'WEN01', '3300', '国际二部 INTL.Business Dept.2', '谭雯', '谭雯', '2017-11-24', '快递', '我司', '瑞典', '中国', '无', 'IEC', '二代模块表', '02', '', '1.Meter must be MID approved and certified.\r\r\r\r\n2.Meter must be CE approved and stamped.\r\r\r\r\n3.Meters must be MID A or better for direct meters, MID B or better for CT meters.\r\r\r\r\n4.Meter must have an operating range -40C - + 70C.\r\r\r\r\n5.Meter must have a P1 plug according to an open standard, but it is notdecided which standard.\r\r\r\r\n6.In addition most customers require 12kV impulse withstand according to\r EN 50470-1, 1.2/50μS.\r\r\n7.P1 port is required\r\r\n\r8.WMBUS is required\r\r\n\r\r\n\r\r\r\n', '', '', '8', '3300', '0', '{F24E73919EC1468FA703D3D1BAA3C88E3E3FD1A05260451F8D948358003231C8}_WEN合同 20171124.pdf', '要求样机完成时间是11月20日，但是研发只能完成一半，剩下的一半现要求12月底完成。', '{F24E73919EC1468FA703D3D1BAA3C88E7719915B5AFB4CFC8E75112B161686FE}_WEN项目技术要求.pdf', '', '合同评审', '02', 'CPT LINKOPING,SWEDEN', '全款收款', '1', '否', '否', '未知', '生产前TT', '样机收费包含快递费，未明确。不含保险。', '02', '01', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata696` VALUES ('499', '{4A081189-99BF-41A9-9EBF-D1A3FF5BBD92}', '61', 'INHE-0612', '2017-11-30 09:10:55', '0000-00-00 00:00:00', '2017-12-05 09:36:13', 'unchecked', 'n', 'n', '', '1', 'INHESC2017112702\r\n/ADC01/合同评审', '', 'Cashpower Sudamericana S.A.', 'CASHPOWER SUDAMERICANA S. A.\r\n', 'INHESC2017112702', 'ADC', 'ADC01', '28325', '国际二部 INTL.Business Dept.2', '陈晨', '陈晨', '2017-11-30', '空运', '买方', '布宜诺斯艾利斯机场', '江西工业园', '银河标准', '符合IEC标准', 'DDZ1513', '02', '', '取消25个RF-CIU和DHL262$运费，将500套产品修改为475套产品带PLC通讯+25套产品带RF通讯。变更前的金额为28937.00$,变更后的金额为28325.00$.客户另外多付的尾款为621$,多出来的金额可作为下次订单中使用。', '', '', '0', '0', '4200', '{2D73014CBF4F4382AC2DA42FB2DC0B6BD4CC22B6C7B643389146528155CECD45}_ADC01新合同.pdf', '2018年1月30日', '', '', '合同评审', '02', 'CIP BUENOS AIRES AIRPORT, ARGENTINA', '货物将在卖方收到买方T/T支付的合同全款后60天内，从卖方工厂发出', '从卖方工厂发货之日起12个月', '否', '否', '否', '100% T/T 预付', '不包括，空运费和保险另收共计 4200 USD', '02', '01', '', null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata696` VALUES ('500', '{67A284ED-13C6-45CE-8895-0F140A943ED9}', '60', 'INHE-0088', '2017-12-05 13:33:01', '0000-00-00 00:00:00', '2017-12-06 16:48:13', 'unchecked', 'n', 'n', '', '1', 'INHESC2017061903/ST20711/合同评审', '', 'SUDANESE ELECTRICITY DISTRIBUTION CO.LTD.', 'SUDANESE ELECTRICITY DISTRIBUTION CO.LTD.', 'INHESC2017061903', 'ST20', 'ST20711', '2752555', '国际一部 INTL.Business Dept.1', '余冬纯', '余冬纯', '2017-12-05', '海运', '我司', '苏丹苏丹港', '中国任意港口', '海运', '客户验货', '第1-6项为原合同包含产品类型，第7-10项为新增类型，同时为保证金额一致，第1-6项数量调低，匀给第7-第10项，差额 EUR53加入运费.', '02', '翻单及新研发产品', '生产前样品验货及不超过3个批次验货（6个批次）		\r\n', '', '', '0', '0', '158053', '{7A8232D0E3234733879A8FF9AB68E08DD4CC22B6C7B643389146528155CECD45}_181112 AMENDMENT.rar', '收到预付款或每个批次货款后60天内', '', '', '合同评审', '03', 'CFR苏丹苏丹港', '该批次货款收齐，该批次第二个预付款保函对应货款收到之日起30天内', '5年，质保部件列表请见合同附件', '否', '否', '是，如果由于供应商未能遵守第5条规定的时间进度造成延迟，供方每一周将给买方支付延迟部分的工作价值的0.5%作为违约赔偿金，最多不超过延迟部分的10%', '开立10%不可撤销履约保函有效期6个月，100%预付款保函，保函到期（每个批次第一个60天，第二个30天）失效，发货前收款', '300A计量箱FOB单价EUR405，运费单价EUR17#FE54`CT计量箱单价不含运保费；单独收取海运费EUR28000', '01', '01', 'ST20708、ST20710', null, null, null, null, null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata696` VALUES ('501', '{BCBBBA91-9ED7-4BED-AEB4-FE9500E66157}', '60', 'INHE-0549', '2017-12-07 08:43:11', '0000-00-00 00:00:00', '2017-12-08 15:23:48', 'unchecked', 'n', 'n', '', '1', 'SM95507PU/NF7/合同评审', '', 'Office National de l`électricité et de l`Eau Potable - Branche électricité', 'Office National de l`électricité et de l`Eau Potable - Branche électricité', 'SM95507PU', 'NF7', 'NF7-01', '163643.64', '国际一部 INTL.Business Dept.1', '王秀明', '王秀明', '2017-12-07', '海运', '我司', '卡萨布兰卡', '江西九江', '必须按照十个区域提供单独的包装。每个包将包含接收实体的名称。\r\r\n', '', 'BS安装一体式三相四线CT接入式中压电表，不带通信模块', '02', '', '', '', '', '1974', '157643.64', '6000', '{BCBBBA919ED74BEDAEB4FE9500E661573E3FD1A05260451F8D948358003231C8}_NF7合同原文.pdf', '预计2018年2月', '{BCBBBA919ED74BEDAEB4FE9500E661577719915B5AFB4CFC8E75112B161686FE}_NF7合同翻译.docx', '', '合同评审', '02', 'CFR卡萨布兰卡', '收到信用证以及发货通知', '临时验收日起2年', '否', '否', '是', '远期60天信用证', '是，运费是USD2250', '01', '01', '', '02', '', '01', '01', 'NF7合同技术规范', null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata696` VALUES ('502', '{BCB82FED-3280-4153-B6F4-FE6CA803FCD9}', '61', 'INHE-0645', '2017-12-10 16:24:50', '0000-00-00 00:00:00', '2017-12-20 16:26:01', 'unchecked', 'n', 'n', '', '1', 'INHESC2017121001/BN12/合同评审', '', 'Société Générale d\"Electronique', 'Société Générale d\"Electronique', 'INHESC2017121001', 'BN', 'BN12', '645602', '国际二部 INTL.Business Dept.2', '朱偲赵燚', '朱偲赵燚', '2017-12-10', '海运', '买家', '科托努，贝宁', '江西银河工厂', '标准纸箱包装', 'IEC', 'DDZ1513', '01', '', '客户要求将原来TN11的货转发给BN11，技术规格相同，三相表尚未生产，需要进行生产。\r\r\n同时将买家TOGO ASSISTANCE SERVICES(TAS)改为Société Générale d\'Electronique（SGE）', '', '', '7500', '637500', '8102', '{BCB82FED32804153B6F4FE6CA803FCD93E3FD1A05260451F8D948358003231C8}_BN合同三相表v.20171212.pdf', '2018/3/1', '', '', '合同评审', '02', 'CIF 科托努，贝宁', '最迟于收到预付款和被银河认可的信用证60天后，从INHEMETER的工厂发出', '卖方所提供货物的保修期为从卖方工厂发货之日起12个月', '否', '否', '否', '货物的CIF总金额为USD 642800，付款方式为：20%预付款，即128560  USD在合同签订后10天内通过T/T支付，INHEMETER开始生产， 80%余款，即514240  USD 使用不可撤销的由一级信用银行保兑的远期60天的信用证支付。信用证应当发货前被INHEMETER收到，且在INHEMETER工厂启动原材料备料前，信用证的条款应当取得INHEMETER的认可。', '否', '02', '01', '', '02', '', '01', '01', 'BN11项目样机出厂设置文件', null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata696` VALUES ('503', '{35E97C22-68FD-47B3-831A-C9F8F007A98B}', '61', 'INHE-0434', '2017-12-13 06:02:54', '0000-00-00 00:00:00', '2017-12-18 10:08:19', 'unchecked', 'n', 'n', '', '1', '1. INHESC2017121202\r\n2. INHESC2017121203/EAR01/合同评审', '', 'RAYMAN PLC', 'RAYMAN PLC', 'INHESC2017121202\r', 'EAR', 'EAR01', '247269', '国际二部 INTL.Business Dept.2', '钟云林(Andy)', '钟云林', '2017-12-13', '海运', '客户承担', '江西九江', '深圳或上海', '按银河标准', '按银河标准', '沿用ITL项目产品型号', '', '', '1. EAR项目对于工装夹具和生产耗材暂不报价，未来和SKD一起报价执行。ITL项目包括工装夹具和耗材；EAR不包括。但EAR项目设备价格和规格参照ITL；\r\r\r\r\r\n2. 另外，培训和安装费用因海关和银行需要，价格加到了工厂设备，所以EAR工厂设备实际比ITL工厂设备报价高。ITL培训费为30000美金、安装人工费为25000美金，EAR项目将培训费和安装人工费(合计55000美金)加到了“工厂设备”里；', '', '', '0', '0', '247269', '{35E97C2268FD47B3831AC9F8F007A98B3E3FD1A05260451F8D948358003231C8}_20171213_EAR项目设备合同INHESC2017121202.pdf', '2018年2月1日', '{35E97C2268FD47B3831AC9F8F007A98B7719915B5AFB4CFC8E75112B161686FE}_20171213_EAR项目所需设备和工具(中英文，含报价）.pdf', '', '合同评审', '02', 'FOB九江', '上述货物将在卖方收到100%合同金额的不可撤销的保兑的即期信用证后60天内，从卖方工厂发出，信用证条款须被合同双方接受', '卖方所提供货物的保修期为从卖方交货之日起12个月；', '否', '待定', '无', '合同全款通过不可撤销的保兑即期信用证在发货前支付。信用证应当在合同签订之后30天内被卖方收到，且信用证的条款应当取得卖方的认可；', '不包含', '02', '02', 'ITL', '02', '', '02', '02', '', null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata696` VALUES ('504', '{DC95F4E2-3D5B-4F8D-B477-64FFA7A42FF4}', '61', 'INHE-0434', '2017-12-14 01:36:32', '0000-00-00 00:00:00', '2017-12-18 16:30:51', 'unchecked', 'n', 'n', '', '1', 'INHESC2017121203/EAR02/合同评审', '', 'RAYMAN PLC', 'RAYMAN PLC', 'INHESC2017121203', 'EAR', 'EAR02', '100000', '国际二部 INTL.Business Dept.2', '钟云林(Andy)', '钟云林', '2017-12-14', '海运', '客户承担', '江西九江', '深圳或上海', '按银河标准', '按银河标准', '\r\r\nBS安装单相可更换通信模块代码智能电表\r\r\n', '', '', '1. 此合同货款原本包含在EAR设备合同里，但因处理后续清关和银行开信用证需要，经与客户沟通，将此笔货款(10万美金)从EAR设备合同里分出来重新制作一份合同；\r\n2. 经与客户沟通，用对等金额(10万美金)的整机制作合同，后续待收到货款后将与客户沟通后续处理事宜；', '', '', '2000', '100000', '0', '{DC95F4E23D5B4F8DB47764FFA7A42FF43E3FD1A05260451F8D948358003231C8}_20171213_EAR项目整机合同INHESC2017121203.pdf', '2017年3月20日', '', '', '合同评审', '02', 'FOB九江', '上述货物将在卖方收到通过T/T方式支付100%合同金额后90天内，从卖方工厂发出', '卖方所提供货物的保修期为从卖方交货之日起12个月', '否', '否', '否', '合同金额的100%在签订合同10天之内通过T/T方式支付', '不包含', '05', '02', 'CDN', '02', '', '02', '02', '', null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata696` VALUES ('505', '{C1C5CE56-534E-4018-A7CB-4E1279AB7903}', '61', 'INHE-0578', '2017-12-18 14:50:09', '0000-00-00 00:00:00', '2017-12-19 16:47:48', 'unchecked', 'n', 'n', '', '1', 'INHESC2017121201/ESA12/合同评审', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'Nyamezela Metering PTY Ltd.', 'INHESC2017121201', 'ESA', 'ESA12', '1720000', '国际二部 INTL.Business Dept.2', '覃湘君(June)', '覃湘君', '2017-12-18', '海运', '银河承担', 'CIF德班', '江西或深圳', '按照ESA项目要求', '按照ESA项目要求', 'DDZ1513', '02', '无', '要求散件由银河提供打包带', '', '', '0', '0', '0', '{9DD230DE215E4F7180137ADD1B94969FD4CC22B6C7B643389146528155CECD45}_ESA12 Sales Confirmation  V.20180126--两次发货.pdf', '2018年1月18日', '', '', '合同评审', '02', 'CIF德班，南非', '1. 发货前收到TT支付的416,000USD；2. 发货前结清ESA09中信保放账账款以用于ESA12发货。', '成品发货后5年，散件发货后18个月。', '是', '是', '否', '生产前TT支付344,000.00 USD；发货前TT支付416,000.00 USD；提单日后90天内，TT支付960,000.00 USD.', '单价包含运保费，每台电表0.25美元。', '03', '02', 'ESA11', '02', '', '02', '02', '', null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata696` VALUES ('506', '{313995EB-8164-4746-9EF6-F093F3C7527A}', '61', 'INHE-0381', '2017-12-19 06:36:08', '0000-00-00 00:00:00', '2017-12-21 08:34:51', 'unchecked', 'n', 'n', '', '1', 'INHESC2017121801/CDN19-Y2/合同评审', '', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'INHESC2017121801', 'CDN', 'CDN19-Y2', '13700', '国际二部 INTL.Business Dept.2', '张柳芳(Alexie)', '张柳芳，胡蝶', '2017-12-19', '快递（DHL）', '我司', '阿比让', '深圳', '无', '无', 'i9000s', '02', '无。', '2017年2月份深圳银河采购过该产品项目代号CDN19-Y，用于实施后付费移动抄表项目。由于雨季，客户库存被淹，现要实施试点，掌机数量不够，因此再采购10台。', '', '', '0', '0', '13700', '{313995EB816447469EF6F093F3C7527A3E3FD1A05260451F8D948358003231C8}_CDN19-Y V20171218(1).docx', '2018.01.19', '', '', '合同评审', '02', 'CPT Abidjan', '签订合同', '12个月', '是', '否', '否', '100%后T/T', '不含', '02', '01', '', '02', '', '02', '02', '', null, null, null, null, null, null, null, null, null);
