INSERT INTO `crs_tabledata696` VALUES ('508', '{6698595F-1304-4C15-8846-3076740A7DFC}', '61', 'INHE-0434', '2017-12-21 00:37:25', '0000-00-00 00:00:00', '2017-12-25 10:50:43', 'unchecked', 'n', 'n', '', '1', 'INHESC2017122001/EAR03/合同评审', '', 'RAYMAN PLC', 'RAYMAN PLC', 'INHESC2017122001', 'EAR', 'EAR03', '150000', '国际二部 INTL.Business Dept.2', '钟云林(Andy)', '钟云林', '2017-12-21', '海运', '客户承担', '江西九江', '深圳或上海', '按公司标准', '按公司标准', 'BS安装单相可更换通信模块代码智能电表\r\r\n', '', '', '1. EAR建厂SKD订单(EAR03)现在无法确认，因为没单，规格不定。但客户已经签建厂设备合同，在打款。目的国是严重外汇管制国家，超过5000美元必须LC。因而，客户希望提前申请外汇支持SKD物料。因而，我们先签一张50美元/台表的SKD物料合同，约定后续可以更改规格和单价等#FE54`\r\r\n2. EAR03报价已申请，OA主题：EAR03项目SKD散件报价申请；技术规格已附在那OA里；王总同意了报价申请；', '', '', '3000', '150000', '0', '{6698595F13044C1588463076740A7DFC3E3FD1A05260451F8D948358003231C8}_20171222_EAR03 Contract(SKD Raw Material).pdf', '2018年3月20日', '{6698595F13044C1588463076740A7DFC7719915B5AFB4CFC8E75112B161686FE}_20171221_EAR03技术规格.jpeg', '', '合同评审', '02', 'FOB九江', '上述货物将在卖方收到100%合同金额的不可撤销的保兑的即期信用证后60天内，从卖方工厂发出，信用证条款须被合同双方接受', '卖方所提供货物的保修期为从卖方交货之日起12个月', '否', '否', '否', '合同全款通过不可撤销的保兑即期信用证在发货前支付。信用证应当在合同签订之后30天内被卖方收到，且信用证的条款应当取得卖方的认可', '不包含', '05', '01', '', '02', '', '01', '01', 'EAR03项目SKD散件报价申请', null, null, null, null, null, null, null, null, null);
