INSERT INTO `crs_tabledata696` VALUES ('524', '{5EF730EE-6211-46F8-B7B1-1FB418C9D3C4}', '61', 'INHE-0675', '2018-02-07 17:52:58', '0000-00-00 00:00:00', '2018-03-02 14:54:39', 'unchecked', 'n', 'n', '', '1', 'INHESC2018020101/MTD01合同评审', '', 'GLOBAL ENGINEERING ENERGY and CONSTRUCTION', 'Global Engineering Energy&Construction', 'INHESC2018020101', 'MTD', 'MTD01', '5000', '国际二部 INTL.Business Dept.2', '李佳嘉', '王子强', '2018-02-07', 'DHL', '我司，合同中包含运费', '突尼斯任意机场', '江西九江', '坚固纸箱', '', 'DDT-1513/DTZ1513', '01', '', '本合同产品技术规格均参照CDN项目技术规格。为规避风险，附件中技术规格为简化版，且合同交期为60天，但客户需求急，业务希望尽快发货。', '相比上次合同评审相比，1.2类型电表从10台变为4台，3类型电表从10台变为2台。运费为400USD。除此之外无其他变动。\r\n', '', '10', '1200', '3800', '{5EF730EE621146F8B7B11FB418C9D3C43E3FD1A05260451F8D948358003231C8}_GEEC中英销售合同 V.20180301.doc', '2018/04/08', '{5EF730EE621146F8B7B11FB418C9D3C47719915B5AFB4CFC8E75112B161686FE}_MTD Specification(仅供客户确认及合同签订使用).docx', '', '合同评审', '02', 'CIP（突尼斯任意机场）', '货物将在卖方收到买方T/T支付的合同全款后60天内，从卖方工厂发出。', '12个月', '否', '否', '否', '货款将以美元结算，并采用T/T方式支付，付款方式如下：签订合同10天内并在卖方准备生产原材料之前T/T支付100%的合同款项。', '否，运保费为400USD', '02', '01', '', '02', '', '01', '02', '', null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata696` VALUES ('525', '{0E0E425F-CB43-4837-B739-D70312B004DD}', '61', 'INHE-0500', '2018-02-08 20:05:48', '0000-00-00 00:00:00', '2018-02-09 15:21:46', 'unchecked', 'n', 'n', '', '1', 'INHESC2018020801\r\n/ASL01/合同评审', '', 'GSA Ltd', 'GSA Ltd\r\n', 'INHESC2018020801\r\n', 'ASL', 'ASL01', '13150', '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '李忠鹏', '2018-02-08', '空运', '银河承担', 'Tirana, Albania\r\n', '银河指定地点出货', '银河标准', '银河标准', 'DTZ1513，BOX300，BOX200，BOX500', '02', '技术规格以银河标准执行', '1.此销售合同下所采用的卖方的全套SmartVend、SmartView和Smarttools将免费提供给买家一年的使用权，免费使用日期从签订合同之日起算，在一个自然年的最后一天结束。\r\r\r\n关于此销售合同下所采用的卖方的全套SmartVend、SmartView和Smarttools的功能和特性，仅限于卖方现有和现成的功能和特性，不包含任何和第三方的交互接口工作，也不包含任何有关设计和修改的工作。\r\r\r\n2.卖方需要提供给买方关于此合同下的产品和系统必需的远程技术支持和培训，以助于买方项目的实施开展。\r\r\r\n', '', '', '33', '10850', '2300', '{0E0E425FCB434837B739D70312B004DD3E3FD1A05260451F8D948358003231C8}_ASL01销售合同20180208.docx', '2018年3月31日', '', '', '合同评审', '02', 'CIP Tirana', '收到买方T/T支付的合同全款后自2018年2月25日起的45天内，从卖方工厂发出。', '银河标准', '否', '否', '否', '签订合同10天内T/T支付100%的合同款项', '不包含', '02', '01', 'ASL01', '02', '', '01', '01', '', null, null, null, null, null, null, null, null, null);
