INSERT INTO `crs_tabledata696` VALUES ('535', '{D50CB688-1E48-4860-B17E-F4B77C76BE1C}', '61', 'INHE-0440', '2018-03-23 18:29:20', '0000-00-00 00:00:00', '2018-03-29 09:28:35', 'unchecked', 'n', 'n', '', '1', 'INHESC2018032201/ITL02/合同评审', '', 'Africarriers Ltd', '\r\r\r\nINHEMETER (T) LIMITED', 'INHESC2018032201', 'ITL', 'ITL02', '467248.61', '国际二部 INTL.Business Dept.2', '汤伟(Will)', '汤伟', '2018-03-23', '海运', '卖方', '坦桑尼亚，达累斯萨拉姆', '中国，九江', '牢固的纸箱里，方便海运', '按技术规格要求', 'DDZ 1513 和 DTZ 1513', '02', '参考技术规格Annex 1 的要求，详细技术规格，请参考Specs(1)', '1.SKD的内盒包装, MCU和CIU的包装印上INHEMETER (T) LIMITED 和 www.inhemetertz.com，\r\r 外盒包装到货后，允许客户贴上MADE IN TANZANIA的标签。                                   2.SKD单相和单相整机含代理佣金USD 6600，SKD每台0.5美元，整机每台8美元。                   3.SKD单相的报价郭总监和王总已确认，ITL02整机报价宋总已确认。                            4.运费根据跟单组的报价1800/40 HQ（有效至3月31日）, 发货时如果运费高于此报价，客户TT补运费差价，FOB条款，我司承担工厂到九江港的内陆运费。                                        \r\r\r\r5.TTN项目和ITL项目合作客户一致，由于不能调用ITL的立项信息，所以以TTN项目，发起ITL02的合同评审。\r\r\n', '', '', '0', '0', '15648.61', '{830F5B9DA7094AFDA0202C313DB1A47CD4CC22B6C7B643389146528155CECD45}_ITL02 10000 SKD Single Phase Meter_20180425.docx', '5月15日', '{830F5B9DA7094AFDA0202C313DB1A47C9E19E8E731434A848B97C6F1C79E3A54}_Annex 1.Technical Data Schedule for Single Phase Meter.docx', '{830F5B9DA7094AFDA0202C313DB1A47CBA0F4BB9344A4053BE173BB06528647F}_PI for SKD20180425.xlsx', '合同评审', '02', 'CIF Dar es Salaam', '货物将在卖方收到T/T支付的合同金额的20%作为预付款及覆盖80%合同金额的不可撤销的保兑的远90天的信用证后，45天内，从卖方工厂发出。', '从卖方工厂发货之日起18个月', '否', '否', '否', '合同金额的20%在签订合同10天之内作为预付款T/T支付，余款80%通过不可撤销的保兑的远期90天信用证支付。信用证应当在合同签订之后15天内被卖方收到，且在卖方工厂启动原材料备料前信用证的条款应当取得卖方的认可。', '不包含', '05', '01', '', '02', '', '01', '01', 'TNT项目技术解析-20180122', null, null, null, null, null, null, null, null, null);
