INSERT INTO `crs_tabledata696` VALUES ('564', '{5FBB66F7-505B-47ED-86A8-4D9E52058452}', '61', 'INHE-0440', '2018-06-06 02:50:25', '0000-00-00 00:00:00', '2018-06-11 15:01:17', 'unchecked', 'n', 'n', '', '1', 'INHESC2018060401/ITL03/合同评审', '', 'Africarriers Ltd', 'Inhemeter (T) Limited', 'INHESC2018060401', 'ITL', 'ITL03', '1189881.29', '国际二部 INTL.Business Dept.2', '汤伟(Will)', '汤伟', '2018-06-06', '海运		\r\n', '运保费增加4204.62美元', '坦桑尼亚，达累斯萨拉姆		\r\n', '中国，九江		\r\n', '牢固的纸箱里，方便海运		\r\n', '按TANESCO最新技术规格要求		\r\n', 'DDZ 1513 和 DTZ 1513		\r\n', '02', '参考技术规格Annex 1 和 Annex 2 的要求，详细技术规格，请参考OA【TTA项目申请技术规格解析支持】里面电力公司的技术要求。					\r\r\r\r\r\n', '1.SKD的内盒包装, MCU和CIU的包装印上INHEMETER (T) LIMITED 和 www.inhemetertz.com， 外盒包装到货后，允许客户贴上MADE IN TANZANIA的标签。表箱上面的贴纸生产时根据客户要求定制。        2.SKD单相和三相含代理佣金USD 10500，SKD单相每台0.5美元，三相每台1美元。                 3.ITL03报价宋总已确认。【ITL03报价申请】                                              4.运费根据跟单组的报价2250/40 HQ, 发货时如果运费高于此报价，客户TT补运费差价，FOB条款，我司承担工厂到九江港的内陆运费。                                                    					\r\r\r\r\r\r\r\r\r\r\n', '', '', '28200', '1153200', '36681.29', '{39DCB1E5EA33490C824D5D1B7FD66551D4CC22B6C7B643389146528155CECD45}_ITL03 28200 SKD Single and Three Phase Meters_20180828-9.docx', '2018-07-30', '', '', '合同评审', '02', 'CIF Dar es Salaam', '在卖方收到覆盖100%合同金额的不可撤销的保兑的远期90天的信用证。信用证条款须被合同双方接受后，45天内，从卖方工厂发出。', '从卖方工厂发货之日起18个月', '否', '否', '否', '合同金额的100%通过不可撤销的保兑的远期90天的信用证支付。信用证应当在合同签订之后15天内被卖方收到，且在卖方工厂启动原材料备料前信用证的条款应当取得卖方的认可。信用证下的远期汇票将会即期议付，承兑费用和贴现费用由信用证申请人承担。', '不包含', '05', '01', '', '02', '', '01', '01', 'TTA项目申请技术规格解析支持', '是', '单相表每台0.5美元，三相表每台1美元', null, null, null, null, null, null, null);
