INSERT INTO `crs_tabledata696` VALUES ('587', '{957E745A-06F3-48CD-9BBD-4D010D8ACEE6}', '61', 'INHE-0636', '2018-07-17 13:52:21', '0000-00-00 00:00:00', '2018-07-19 15:17:34', 'unchecked', 'n', 'n', '', '1', 'INHESC2018071301/KF03/合同评审', '', 'The Kenya Power * Lighting Company Limited', 'The Kenya Power * Lighting Company Limited', 'INHESC2018071301', 'KF03', 'KF03', '5760347.7', '国际二部 INTL.Business Dept.2', '倪明杰', '谭东羊', '2018-07-17', '海陆联运', '卖方', '买方仓库', '中国任意港口', '按照标书要求', '', 'DDZ1513', '02', '1. DIN4，底部进线底部出线，进线靠近底端\r（目前PY03、KF02是底部进线底部出线，出线靠近底端。）\r\r\r\r\r\r\r\r\n2.双回路双继电器，火线和零线 一体式继电器  或者  两个独立继电器 都能接受。\r\r\r\r\r\r\n3.MCU和CIU需要满足IP54', '0.由于KF03 立项时对应的客户名称为 KPLC，但实质上，此为IAC与深圳银河的合同；KPLC与IAC的合同会由IAC发起。\r\r\r\r\r\r\r\n1.KF03项目115,000套电表全部按照成品供货给IAC（同KF02 9.6万套成品的出货状态），需要按照开箱不良率98.8%，由深圳银河提供230套备品，即总供货数量为115,230套。\r\r\n', '', '', '115230', '5760347.7', '0', '{957E745A06F348CD9BBD4D010D8ACEE63E3FD1A05260451F8D948358003231C8}_KF03销售合同INHE和IAC20180713.docx', '合同签订后50天从工厂发货。\r\n具体发货时间需要根据电力公司\r\n更新的PO时间来确定', '', '', '合同评审', '02', 'DDP(买方仓库)(含增值税)', '在合同签订日期后50天内，从卖方工厂发出（此为深圳银河与IAC的合同条款；实际发货时间，依据电力公司更新的PO交期）', '卖方所提供货物的保修期为从卖方工厂发货之日起12个月（此为深圳银河与IAC的合同条款；IAC与KPLC的质保期为“满意交付后54个月或者发货后60个月，期效晚者为准”）', '是', '依据实际情况', '否', '每批发货的货值在提单日后120天采用T/T全款支付', '包含，DDP(买方仓库)(含增值税)单价为49.99USD，其中江西工厂至IAC仓库运保费为0.9USD', '05', '01', '', '02', '', '02', '01', 'KF03样机申请（投标申请过样机，技术规格已经审核），在报价申请OA“KF03投标报价申请”也提示过杨总技术规格。', '需要', 'FOB单价USD37.96，佣金为8% FOB，即USD3.04/套表', null, null, null, null, null, null, null);
