INSERT INTO `crs_tabledata696` VALUES ('598', '{B10D6339-55FC-496D-B758-90DE4539E689}', '60', 'INHE-0066', '2018-08-13 08:42:15', '0000-00-00 00:00:00', '2018-08-17 18:26:13', 'unchecked', 'n', 'n', '', '1', 'INHESC2018081001\r\r\n/白云803/合同评审', '', '”Aspan-Energy“LTD', '”Aspan-Energy“LTD', 'INHESC2018081001', '白云', '白云803', '205250', '国际一部 INTL.Business Dept.1', '邱洁', '邱洁', '2018-08-13', '陆运', '客户', '深圳', '深圳', '按国际陆运运输标准', '按公司验收标准。', '三相智能电表、集中器', '02', '翻单', '无', '', '', '500', '65250', '140000', '{B10D633955FC496DB75890DE4539E6893E3FD1A05260451F8D948358003231C8}_白云803合同-500шт трехфазных счетчиков и 200шт.концентраторов-INHESC2018081001.doc', '2018年9月20日', '', '', '合同评审', '02', 'FCA深圳', '款到发货', '3年', '否', '否', '否', '50%T/T-预付款，50%T/T-发货前支付。', '', '02', '02', '白云701', '02', '', '02', '02', '无', '否', '无', '02', '', null, null, null, null, null);
INSERT INTO `crs_tabledata696` VALUES ('599', '{04FAE341-92F9-4170-A93A-AB30ECCBE2E3}', '61', 'INHE-0654', '2018-08-13 14:11:09', '0000-00-00 00:00:00', '2018-08-29 16:40:20', 'unchecked', 'n', 'n', '', '1', 'INHESC2018072601/CHL01/合同评审', '合同条款里的贸易术语，保险表达有误，已经更改，重新走一遍流程，对此抱歉！', 'EDALTEC GRUPO', 'EDALTEC GRUPO ', 'INHESC2018081403', 'CHL', 'CHL01', '34000', '国际二部 INTL.Business Dept.2', '李明(Ming)', '李明', '2018-08-13', '海运', '买方', '深圳港口', '江西工业园', '公司标准', '符合IEC标准', 'DDZ1513', '02', '', '1，由于电表材料采购周期较长，客户先下单独电表的单，具体的通讯方式已经模块数量的匹配后续确认。电表要支持集抄功能，并且要支持停电上报的功能。                                      2，产品的规格按CHL认证样机来制作完成，根据样机申请单以及客户提出来的需求，整理的技术规格，比较粗略，但是这是目前能整理出来的技术规格，后续需要技术支持协助完善，产品认证的证书上注明了两点要满足#FE54`IEC62053-21：2003，IEC62052-11：2003.                                   3，CHL项目代理于今年4月份刚做完认证，花了近1万美金左右，也实属不易。                     4,客户已经支付50%的预付款。', '', '', '1000', '34000', '0', '{04FAE34192F94170A93AAB30ECCBE2E33E3FD1A05260451F8D948358003231C8}_CHL01销售合同20180823.pdf', '2018/10/10', '{B31F109AFEAD40F3A7B31AA31D606B00C0C041FDE37D48DDBD71A1405A7C684E}_CHL01技术规格20180823.docx', '', '合同评审', '02', 'FOB深圳', '收到全款后发货', '发货之日起12个月', '否', '否', '是', '50%生产前T/T预付款，50%发货前T/T尾款', '不包含', '02', '01', '', '02', '', '02', '01', 'CHL样机申请', '否', '否', '02', '', null, null, null, null, null);
