INSERT INTO `crs_tabledata696` VALUES ('601', '{0F9C7179-8C5A-4D1F-B325-09606C03716A}', '61', 'INHE-0636', '2018-08-14 17:34:33', '0000-00-00 00:00:00', '2018-08-17 10:18:01', 'unchecked', 'n', 'n', '', '1', 'INHESC2018072601/PRK01/合同评审', '', 'PowerGen Renewable Energy', 'PowerGen Renewable Energy', 'INHESC2018072601', 'PRK', 'PRK01', '300', '国际二部 INTL.Business Dept.2', '倪明杰', '谭东羊', '2018-08-14', '空运或者快递', '买方承担', '深圳\r\r\n（采用客户DHL账号958860413，送货至PowerGen Renewable Energy, Miotoni Road, Off Ngong Road，Karen, Nairobi，Kenya）', '深圳银河', '依据合同', '依据合同', 'DDZ1513', '02', '', '1.客户先采购3台样机进行试点，试点成功后再批量采购。\r\r\r\r\r\r\n2.技术规格客户已经签字确认（请见合同附件），技术规格主要依据PZ01项目的技术规格。\r\r\n', '', '', '3', '300', '0', '{0F9C71798C5A4D1FB32509606C03716A3E3FD1A05260451F8D948358003231C8}_PRK项目样机合同 银河待签字.pdf', '卖方收到货款后的60 天内交货\r\n(货款已于2018年8月14日收到)', '', '', '合同评审', '02', 'FCA（SHENZHEN）', '卖方收到货款后的60天内交货', '从卖方工厂发货之日起12 个月', '否', '否', '否', '双方签署合同后的5个工作日内，买方TT 支付100%货款（2018年8月14日已经收到客户全款）', '为FCA（SHENZHEN）价格,不包含运保费', '02', '01', '', '02', '{0F9C71798C5A4D1FB32509606C03716AEA23E848092D41CC83988AEE534D6267}_PRK样机付款凭证.jpg', '01', '02', '', '否', '无', '02', '', null, null, null, null, null);
