INSERT INTO `crs_tabledata696` VALUES ('603', '{BE990E15-EE88-4B34-8ECD-169929E9552E}', '60', 'INHE-0066', '2018-08-17 10:11:04', '0000-00-00 00:00:00', '2018-08-21 07:55:06', 'unchecked', 'n', 'n', '', '1', 'INHESC2018081601/白云804/合同评审', '', '\"Aspan-Energy \" LTD', '\"Aspan-Energy \" LTD', 'INHESC2018081601', '白云', '白云804', '4833', '国际一部 INTL.Business Dept.1', '邱洁', '邱洁', '2018-08-17', '陆运', '客户', '深圳', '深圳', '按陆运运输标准', '按公司验收标准', '单、三相智能电表配件', '02', '无', '无', '', '', '0', '0', '4833', '{BE990E15EE884B348ECD169929E9552E3E3FD1A05260451F8D948358003231C8}_白云804合同-客户已签.PDF', '2018年9月10日', '', '', '合同评审', '02', 'FCA深圳', '款到发货', '3年', '否', '否', '否', '50%TT-预付款，50%TT-尾款发货前付清', '否', '02', '01', '', '02', '', '02', '02', '', '否', '无', '02', '', null, null, null, null, null);
INSERT INTO `crs_tabledata696` VALUES ('604', '{EDFCDA79-5C4C-4A6E-846D-5AC494C9FBEF}', '61', 'INHE-0440', '2018-08-18 16:11:45', '0000-00-00 00:00:00', '2018-08-22 14:10:38', 'unchecked', 'n', 'n', '', '1', 'INHESC2018081503/TTA01/合同评审', '', 'INHEMETER (T) LIMITED', 'INHEMETER (T) LIMITED', 'INHESC2018081503', 'TTA', 'TTA01', '6248236.39', '国际二部 INTL.Business Dept.2', '汤伟(Will)', '汤伟', '2018-08-18', '海运', '卖方', '坦桑尼亚，达累斯萨拉姆	', '中国，九江		', '牢固的纸箱里，方便海运', 'TTA项目技术规格', 'DDZ 1513 ', '02', '参考技术规格Annex 1 要求，详细技术规格，请参考OA【TTA项目申请技术规格解析支持】里面有翻译的技术规格要求。', '1.SKD的内盒包装, MCU和CIU的包装印上INHEMETER (T) LIMITED 和 www.inhemetertz.com， 外盒包装到货后，允许客户贴上MADE IN TANZANIA的标签。表箱上面的贴纸生产时根据客户要求定制。                      2.SKD单相含代理佣金USD 80000，SKD单相每台0.5美元（税后）。                                  3. TTA报价宋总已确认。【TTA项目报价申请 】                                               4.运费根据跟单组的报价1900/40 HQ, 发货时如果运费高于此报价，客户TT补运费差价。FOB报价，我司承担工厂到九江港的内陆运费。', '', '', '0', '0', '168236.39', '{EAAE9DDCDF9A477BB19CB9AE26C471B1D4CC22B6C7B643389146528155CECD45}_TTA项目合同(ITL签字版本）.pdf', '2018年11月1日至2019年3月1日', '', '', '合同评审', '02', 'CIF 达累斯萨拉姆', '在卖方收到覆盖100%合同金额的不可撤销的保兑的远期180天的信用证。信用证条款须被合同双方接受后，60天内，从卖方工厂发出。每批次信用证开立日期和发货日期，请参考合同。', '从卖方工厂发货之日起18个月', '否', '否', '否', '合同金额的100%通过不可撤销的保兑的远期180天的信用证支付。信用证应当在合同签订之后15天内被卖方收到，且在卖方工厂启动原材料备料前信用证的条款应当取得卖方的认可。信用证下的远期汇票将会即期议付，承兑费用和贴现费用由信用证申请人承担。付款方式，王总已经在OA【坦桑尼亚市场2018年出差报告】同意。', '不包含', '05', '01', '', '02', '', '01', '01', 'TTA项目申请技术规格解析支持', '是', '单相表每台需支付0.5美元(税后）', '02', '', null, null, null, null, null);
INSERT INTO `crs_tabledata696` VALUES ('605', '{89A25887-28BB-4962-998F-BAB62035CA91}', '61', 'INHE-0500', '2018-08-20 17:26:04', '0000-00-00 00:00:00', '2018-08-29 16:38:39', 'unchecked', 'n', 'n', '', '1', 'INHESC2018082002\r\n/ZWS01/合同评审', '', 'Finmark Industries (Pvt) Ltd.', 'ZIMBABWE ELECTRICITY TRANSMISSION & DISTRIBUTION COMPANY\r\n', 'INHESC2018082002\r\n', 'ZWS', 'ZWS01', '4369380', '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '李忠鹏', '2018-08-20', '海运', '客户承担', 'CIP 电力公司仓库送货到门\r\r\n', '江西工厂', '同ZEC订单', 'ZEC电力公司需要安排VAT，流程请参照ZEC订单', 'DDZ1513，DTZ1513', '02', '', '1.此中标合同的技术部分已发客服部评审，详情请见OA“ZWS项目（中标项目）技术合同评审申请”；\r\n2.此合同的商务部分，合同履约保函由代理FHL开立，银河不负责开立履约保函；付款条件方面经过和郭总监商议、代理FHL商议，建议先签订合同，再和电力公司协商付款条件。', '', '', '39000', '4369380', '0', '{89A2588728BB4962998FBAB62035CA913E3FD1A05260451F8D948358003231C8}_ZWS投标项目中标合同---商务部分.pdf', '电力公司正式采购订单后8至12周交付至电力公司仓库', '{89A2588728BB4962998FBAB62035CA917719915B5AFB4CFC8E75112B161686FE}_ZWS投标项目中标合同---商务部分--中英对照20180827.doc', '', '合同评审', '02', 'CIP ZETDC Warehouse', '按照标书要求：赊销发货。待电力公司协商解决。', '货物接收后24个月，产品出现质量问题30天内免费更换；需要提供0.5%的备品。', '是，目前只是签订合同，不接受电力公司赊销条款，待电力公司协商解决。', '中信保不受理区域', '是，因供应商问题交付延迟，每延迟一周按照总合同金额的0.3%进行罚款，最高至合同总金额的4%，如果超过最高罚款金额4%，电力公司有权取消合同的执行。', '按照标书要求：货物交付到门后发票日30天后付款。待电力公司协商解决。', '包含:1. 4000台DIN导轨单相表，海运费和保险费：2美金每台，清关费：0.82美金每台；2. 15000台 BS单相表，海运费和保险费：2.2美金每台，清关费：0.91美金每台；3. 20000台BS三相表，海运费和保险费：3.2美金每台，清关费：2.25美金每台', '01', '01', '', '01', '', '01', '01', 'ZWS项目（中标项目）技术合同评审申请', '是', '原始报价单价中包含15%代理佣金，由于最终实际报价代理FHL在单价中分别增加了价格，最终的佣金比例需要和代理协商，先签订合同', '02', '', null, null, null, null, null);
