INSERT INTO `crs_tabledata696` VALUES ('622', '{5EF37F6A-EDF9-4A40-B6B5-0F8ADAE09D8B}', '61', 'INHE-0654', '2018-09-21 13:30:58', '0000-00-00 00:00:00', '2018-09-27 09:59:26', 'unchecked', 'n', 'n', '', '1', 'INHESC2018092101/PSA10801/合同评审', '', 'MESSEN S.A.S', 'MESSEN S.A.S', 'INHESC2018092101', 'PSA10', 'PSA10801', '3756', '国际二部 INTL.Business Dept.2', '李明(Ming)', '李明', '2018-09-21', '空运', '买方', '空运：深圳', '江西工业园', '公司标准', '符合IEC标准', '', '', '', '1，已收到客户30%的预付款。2，合同金额较小，同时代理要求的交期较紧急，希望20-25天内可以完成采购以及生产。3，PSA10当时是中标当地的国电EPM,CIP直采是适用于该项目上的电表，自上次供货后，电力公司与银河至今还未有采购订单，代理也是想通过供显示单元，再进一步加深电力公司对银河产品的使用印象。', '', '', '0', '0', '3756', '{5EF37F6AEDF94A40B6B50F8ADAE09D8B3E3FD1A05260451F8D948358003231C8}_PSA10801销售合同.pdf', '2018/10/10', '', '', '合同评审', '02', 'FCA深圳', '收到全款后发货', '发货起12个月', '否', '否', '是', '30%生产前T/T付款，70%发货前T/T尾款', '不包含', '02', '01', '', '02', '', '02', '01', 'PSA10翻单CIP报价', '否', '否', '02', '', null, null, null, null, null);
INSERT INTO `crs_tabledata696` VALUES ('623', '{6CC976F9-A903-4FCD-BCAC-DCDE02304585}', '61', 'INHE-0725', '2018-09-25 11:56:44', '0000-00-00 00:00:00', '2018-09-27 09:59:02', 'unchecked', 'n', 'n', '', '1', 'INHESC2018092102/GZA02/合同评审', '', 'ZAHYON SOLUTIONS LTD', 'ZAHYON SOLUTIONS LTD', 'INHESC2018092102', 'GZA', 'GZA02', '6850', '国际二部 INTL.Business Dept.2', '赵政洁(Oscar)', '钟云林 赵政洁', '2018-09-25', '空运', '卖方', '尼日利亚拉各斯机场（机场三字代码：LOS）', '深圳', '货物应该包装在牢固的纸箱里，方便海运或空运', '银河标准', 'DTZ1513', '01', '银河标准', '1.该客户为GR项目客户，近日客户反馈通过GR02项目合同中签订的客户公司（GMA Global Resources Limited)账户需要花费较长时间才能转钱到我公司账户，因此现在希望能用另一家子公司的名义签订合同——ZAHYON SOLUTIONS LTD以防止出现第三方支付。之前GR项目已出现过这种问题，因此我方已就ZAHYON SOLUTIONS LTD立过项（GZA项目）；\r\r\r\r\n2.现向公司申请使用公司名称ZAHYON SOLUTIONS LTD（客户子公司）签订合同以防止第三方支付并加快收款速度。之前GR02项目作废，项目代号以GZA02为准。\r\r\r\r\n\r\r\r\r\n', '', '', '70', '5950', '900', '{6CC976F9A9034FCDBCACDCDE023045853E3FD1A05260451F8D948358003231C8}_GZA02 Sales Contract_20180921.pdf', '10月19日', '{6CC976F9A9034FCDBCACDCDE023045857719915B5AFB4CFC8E75112B161686FE}_GZA02 Technical Specifications_20180921.pdf', '', '合同评审', '02', 'CIP Lagos Airport, Nigeria', '卖方将在收到买方T/T支付的合同100%全款后30天内备妥待运', '从卖方交货之日起12个月', '否', '否', '否', '合同金额的100%全款在签订合同10天内作为预付款T/T支付', '否', '05', '01', '', '02', '', '01', '02', '', '否', '无', '02', '', null, null, null, null, null);
