INSERT INTO `crs_tabledata696` VALUES ('644', '{83AA6AFB-6619-44CE-948F-AADBBBCD0312}', '61', 'INHE-0500', '2018-11-07 03:10:56', '0000-00-00 00:00:00', '2018-11-08 16:52:42', 'unchecked', 'n', 'n', '', '1', 'INHESC2018110701\r\n/EOI12/合同评审', '', 'Finmark Industries (Pvt) Ltd.', 'PARAMOUNT CABLES PRIVATE LIMITED\r\r\n', 'INHESC2018110701\r\n', 'EOI', 'EOI12', '662000', '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '李忠鹏', '2018-11-07', '空运', '客户承担', '哈拉雷国际机场', '江西工厂', '银河标准', '银河标准', 'DDZ1513', '01', '', '1.卖家应在每批次销售给买方的订单中准备额外1%的电表作为质保更换的备品#FE54`\r\r\n2.使用EOI库存订单，请按照表号顺序装箱。', '', '', '2090', '543400', '118600', '{83AA6AFB661944CE948FAADBBBCD03123E3FD1A05260451F8D948358003231C8}_Sales Contact  20181107---EOI12.docx', '在卖方收到买方T/T支付的合同全款后10天内，从卖方工厂发出', '', '', '合同评审', '04', 'CIP Harare', '上述货物将在卖方收到买方T/T支付的合同全款后10天内，从卖方工厂发出。', '24个月', '否', '否', '否', '合同金额的100%在签订合同30天内并在发货前作为预付款T/T支付。', '不含', '05', '01', '', '02', '', '01', '01', 'ZWS和EOI项目技术解析', '否', 'N/A', '02', '', '', null, null, null, null);
INSERT INTO `crs_tabledata696` VALUES ('645', '{36810D05-B8D0-4F47-83E7-7C4F47FB364F}', '61', 'INHE-0593', '2018-11-12 09:55:44', '0000-00-00 00:00:00', '2018-11-12 10:10:55', 'unchecked', 'n', 'n', '', '1', 'INHESC2018111201/BFN11/合同评审', '', 'SOCIETE GENERALE D`ELECTRONIQUE', 'SOCIETE GENERALE D`ELECTRONIQUE', 'INHESC2018111201', 'BFN10', 'BFN11', '760400', '国际二部 INTL.Business Dept.2', '胡蝶', '张柳芳,胡蝶', '2018-11-12', '海运', '客户', '多哥洛美港口', '中国', '纸箱', '泰纳检验', 'DDZ1513/DTZ1513', '01', '满足', '本订单中的三相表，希望能使用TN11库存三相表', '', '', '32000', '760000', '400', '{36810D05B8D04F4783E77C4F47FB364F3E3FD1A05260451F8D948358003231C8}_BFN11.zip', '2018/12/25', '', '', '合同评审', '02', 'CIF 洛美, 多哥', '上述产品将在卖方收到全部预付款及卖方认可的信用证之后50天内完成生产发货', '12个月', '否', '否', '否', '本合同金额USD773  400通过如下方式支付： （1）合同金额的10%（预付款）在卖方启动生产备料之前，买方通过TT支付； （2）合同金额的90%通过信用证支付，具体方式如下：-10%通过信用证即期付款-80%通过不可撤销的保兑信用证支付，于发货后交单议付，付款期限为提单日之后90天。', '不包含', '03', '01', '无', '02', '', '01', '01', 'BFN09/10 生产 反向电流处理', '否', '无', '02', '', '', null, null, null, null);
INSERT INTO `crs_tabledata696` VALUES ('646', '{2DC2E698-B2D1-4C71-BD5C-2D8F0816B06C}', '61', 'INHE-0654', '2018-11-14 09:25:20', '0000-00-00 00:00:00', '2018-11-15 15:38:34', 'unchecked', 'n', 'n', '', '1', 'INHESC2018092601/ADD01/合同评审', '', 'Cashpower Sudamericana S.A.', 'CASHPOWER SUDAMERICANA S.A', 'INHESC2018092601', 'ADD', 'ADD01', '2499956', '国际二部 INTL.Business Dept.2', '李明(Ming)', '李明', '2018-11-14', '5000台电表走海运', '银河', '港口：中国深圳', '江西工业园', '公司标准', 'IEC标准', 'DDZ1513', '02', '', '1，供货产品是同ADC为一个市场，注意产品之前做过认证的样机为“雏菊”PLC是支持前后端通信的，切勿出错，同时用户显示单元要求可充电版的CIU-R，并供货时满足用户显示单元上有剩余电量显示。2，此合同不包括软件部分，软件费用单独收取。3，该市场认证，进出口十分严格，切勿出错。', '', '', '60000', '2310000', '0', '{2885D30366DE468BB7B33CC30C8EA5BAD4CC22B6C7B643389146528155CECD45}_Addendum of Sales Contract ADD01第五批销售合同附录.docx', '待定', '', '', '合同评审', '02', 'CIF(阿根廷布宜诺斯艾利斯港口）', '10%的T/T预付款收齐，90%的中信保确认有额度', '发货之日起36个月', '否', '是', '是', '买方会为每批订单提供（EDENOR）签署后的采购订单（PO）；CSA将会把EDENOR要求的每一批次的产品数量告知银河表计，同时支付每批货物CIF货值的10%（预付）到银河表计银行的账户上。每批货物90%的余款在提单日后的120天内通过T/T支付给INHEMETER。', '包括，每台运保费为1.5美金', '03', '01', '', '02', '', '02', '01', 'ADD项目的报价申请单', '否', '否', '02', '', '', null, null, null, null);
INSERT INTO `crs_tabledata696` VALUES ('647', '{65F524C2-31E6-4319-8557-790633DB5F8E}', '61', 'INHE-0500', '2018-11-15 13:17:10', '0000-00-00 00:00:00', '2018-11-20 13:54:03', 'unchecked', 'n', 'n', '', '1', 'INHESC2018111501\r\n/EOI13/合同评审', '', 'Finmark Industries (Pvt) Ltd.', 'PARAMOUNT CABLES PRIVATE LIMITED\r\n', 'INHESC2018111501\r\n', 'EOI', 'EOI13', '492999.9838', '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '李忠鹏', '2018-11-15', '空运', '客户承担', '哈拉雷国际机场', '江西工厂', '按照表号顺序装箱，其他按照EOI出货标准', 'EOI项目验收标准', 'DDZ1513，DTZ1513', '01', '', '1.请按照表号顺序装箱；\r\r\r\n2.请使用EOI库存订单；\r\r\n3.EOI13客户和EOI12客户为同一个客户FHL，客户要求1%备品，EOI12已经审批过，EOI13订单按照1%的备品要求，DIN导轨表为 150+2=152台，BS三相表 为 500+5=505台，备品已经平摊到单价中。\r\r\n\r\r\n', '', '', '657', '433999.9838', '59000', '{65F524C231E643198557790633DB5F8E3E3FD1A05260451F8D948358003231C8}_Sales Contact  20181115---EOI13.docx', '在卖方收到买方T/T支付的合同全款后10天内，从卖方工厂发出', '', '', '合同评审', '04', 'CIP Harare', '上述货物将在卖方收到买方T/T支付的合同全款后10天内，从卖方工厂发出。', '24个月', '否', '否', '否', '合同金额的100%在签订合同30天内并在发货前作为预付款T/T支付。', '不含', '05', '01', '', '02', '', '01', '01', 'ZWS和EOI技术解析', '否', 'N/A', '02', '', '', null, null, null, null);
