INSERT INTO `crs_tabledata696` VALUES ('711', '{2EF641A6-EEE6-4B25-9E5B-C55B4463AC22}', '61', 'INHE-0500', '2019-03-28 03:15:03', '0000-00-00 00:00:00', '2019-04-03 17:34:47', 'unchecked', 'n', 'n', '', '1', 'INHESC2019030501\r\n/ZCO01/合同评审', '', 'Econet Wireless Zimbabwe', 'Distributed Power Africa Services (Pty) Ltd\r\n', 'INHESC2019030501\r\n', 'ZCO', 'ZCO01', '26180', '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '李忠鹏', '2019-03-28', '空运', '客户承担', '津巴布韦哈拉雷国际机场', '江西工厂', '银河标准', '银河标准', 'DDZ1513，DTZ1513，I6300', '', '', '1.ZCO01项目为ZEC市场智能电表试点项目，银河和当地最大的电信运营商ECONET直接签订试点项目合同合作，项目商务信息详情请见ZCO立项申请表；\r\r\r\r\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\r\r\n2.ZCO的技术规格全部按照银河技术标准，不做任何修改，技术实施方案以银河标准为主，详情请见OA：ZCO项目技术支持申请；\r\r\r\r\r\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\n3.请公司支持ZCO智能电表试点项目的实施和扩展到电力公司合同实施；\r\r\r\r\r\r\r\r\r\r\r\n\r\r\r\r\r\r\n\r4.由于技术支持申请OA之前并未转给丁总审核，导致丁总对项目技术方案不清晰未通过，已将技术解析OA转给丁总重新评审，所以重新走了销售合同评审。\r\r\r\r\r\r\r\r\r\n', '', '', '62', '4530', '21650', '{2EF641A6EEE64B259E5BC55B4463AC223E3FD1A05260451F8D948358003231C8}_Sales Contract for Meters.docx', '收到买方T/T支付的合同全款后35天内，从卖方工厂发出。\r\n', '{2EF641A6EEE64B259E5BC55B4463AC227719915B5AFB4CFC8E75112B161686FE}_Sales Contract for Software.docx', '', '合同评审', '02', 'CIP Harare', '上述货物将在卖方收到买方T/T支付的合同全款后35天内，从卖方工厂发出。', '12个月', '否', '否', '否', '合同金额的100%在签订合同10天内作为预付款在发货前T/T支付。', '不含', '02', '01', '', '02', '', '01', '01', 'ZCO项目技术支持申请', '否', 'N/A', '02', '', '02', '★★★', null, null, null);
