INSERT INTO `crs_tabledata696` VALUES ('720', '{797AB87D-1C0A-4C1A-B26C-81F24807A460}', '97', 'INHE-0662', '2019-04-15 09:27:12', '0000-00-00 00:00:00', '2019-05-02 22:32:16', 'unchecked', 'n', 'n', '', '1', 'INHESC2019041001/ITL05/合同评审', '', 'Africarriers Ltd', 'Inhemeter (T) Limited', 'INHESC2019041001', 'ITL', 'ITL05', '69474.34', '商务组(Commerce Division)', '陈丽', '汤伟', '2019-04-15', '海运', '客户', '中国', '银河工厂', '银河标准', '银河标准', '设备', '02', '', '1.三相电表生产设备的原FOB报价为44225美金，客户建议将5000美金的佣金加在报价中，最终的三相电表生产设备的报价为49225美金。该项目为直接采购。\r\r\r\r\n2.附件合同客户已签。', '', '', '0', '0', '69474.34', '{797AB87D1C0A4C1AB26C81F24807A4603E3FD1A05260451F8D948358003231C8}_ltl05 客户签字的三相设备和PI.pdf', '20190506', '', '', '合同评审', '02', 'CIF Dar es Salaam', '本合同项下的货物将在卖方收到50%的预付款后30天内，从卖方工厂发出', '安装之日起12个月', '否', '否', '如果卖方完成生产但买方未能达到本合同装运条件时，买方必须从完成生产第二天开始向卖方支付罚金。', '预付款合同金额的50%将在签订合同后7天内通过T/T支付。余款合同金额的50%将在发货前7天内通过T/T支付。', '否', '05', '01', '', '02', '', '01', '02', '未OA通过客服审批，设备清单和规格由江西工厂雷经理推荐', '是，佣金已经含在三相电表生产设备的报价中', '佣金为5000美金', '02', '', '', '', null, null, null);
