INSERT INTO `crs_tabledata696` VALUES ('725', '{879670B2-FC8B-458B-8F57-A6F3BA1E85B7}', '61', 'INHE-0578', '2019-04-28 14:51:03', '0000-00-00 00:00:00', '2019-05-05 09:03:26', 'unchecked', 'n', 'n', '', '1', 'INHESC2019042801\r\n/EOI30/合同评审', '', 'Finmark Industries (Pvt) Ltd.', 'PARAMOUNT CABLES PRIVATE LIMITED\r\n', 'INHESC2019042801\r\n', 'EOI', 'EOI30', '78419.0032', '国际二部 INTL.Business Dept.2', '覃湘君(June)', '李忠鹏,覃湘君', '2019-04-28', '空运', '银河承担（客户支付空运及保险费用）', 'CIP 哈拉雷', '江西工厂', '按照EOI项目包装要求', '按照EOI项目验收标准', 'DDZ1513，DTZ1513', '01', '无', '1. 此客户为EOI05-1，EOI12,13,14,23项目客户，要求1%的备品；\r\r\r\r\r\n2. 根据要求，已将备品体现在数量中，产品单价为体现备品后的价格；\r\r\r\n3. 实际合同总金额保留2位小数，总金额为78,419欧元。						\r\r\n', '', '', '1313', '65820.0032', '12599', '{879670B2FC8B458B8F57A6F3BA1E85B73E3FD1A05260451F8D948358003231C8}_Sales Contact  20190428---EOI30.pdf', '2019年4月30日', '', '', '合同评审', '03', 'CIP Harare', '收到T/T合同全款5天内安排发货。', '发货后24个月。', '否', '否', '否', '签订合同30天内T/T支付合同全款。', '不包含', '05', '01', '详见OA\"EOI01项目报价审批\"。', '02', '', '02', '01', 'ZWS和EOI项目技术解析', '否', '否', '02', '无', '', '', null, null, null);
INSERT INTO `crs_tabledata696` VALUES ('726', '{CF038189-27C9-47D2-92AD-49BA062730AB}', '61', 'INHE-0772', '2019-05-02 00:39:52', '0000-00-00 00:00:00', '2019-05-05 16:39:01', 'unchecked', 'n', 'n', '', '1', 'NAWEC/OPO/COMM(9741)/GBA02\r\n/合同评审', '', '冈比亚国家水电公司', 'NATIONAL WATER AND ELECTRICITY COMPANY LTD (NAWEC)', 'NAWEC/OPO/COMM(9741)', 'GBA', 'GBA02', '29950', '国际二部 INTL.Business Dept.2', '张子琦(Miranda)', '张子琦', '2019-05-02', '空运', '银河', '冈比亚班珠尔国际机场', '深圳', '同GBA01', '银河默认标准', 'TTA', '01', '变更：除了电流变更为5（60）A，其他技术参数保持与GBA01订单一致。客户已确认，详见客户订单中规格描述。除贴纸和电表面板同GBA01\r，其他物料可共用TTA物料。\r见附件：GBA01_BS安装单相一体式(RF通信)代码预付费电能表_出厂设置文件_VA.0\r\r\r\r\n						\r\r\r\r\r\r\r\r\n', '因我司前一批交货4000台电表还在海上月底到达，电力公司急需本批电表在5月14日前到达冈比亚缓解压力。经协商，客户同意接受电流5（60）A，即可用TTA物料进行生产交货，挪用TTA物料已获郭总同意。', 'GBA02的付款条件变更为：发货前100%TT付款； 付款后发货。', '', '1000', '29950', '0', '{CF03818927C947D292AD49BA062730AB3E3FD1A05260451F8D948358003231C8}_GBA02订单PO.pdf', '2019-5-11', '{CF03818927C947D292AD49BA062730AB7719915B5AFB4CFC8E75112B161686FE}_GBA01_BS安装单相一体式(RF通信)代码预付费电能表_出厂设置文件_VA.0.pdf', '', '合同评审', '02', 'CIP 班珠尔国际机场', '100%付款后发货', '12个月', '否', '否', '是', '发货前100%T/T', '含空运费，3.995美金/台电表', '02', '02', 'GBA01', '02', '', '01', '01', '', '是', '1美金一台电表', '02', '', '', '', null, null, null);
INSERT INTO `crs_tabledata696` VALUES ('727', '{FC108101-F435-4708-A2B0-EE1ABFE8962E}', '61', 'INHE-0578', '2019-05-02 18:36:14', '0000-00-00 00:00:00', '2019-05-05 14:23:40', 'unchecked', 'n', 'n', '', '1', 'INHESC2019043001\r\n/EOI32/合同评审', '', 'Finmark Industries (Pvt) Ltd.', 'FRISERV INVESTMENTS (PRIVATE) LTD\r\n', 'INHESC2019043001\r\n', 'EOI', 'EOI32', '26372', '国际二部 INTL.Business Dept.2', '覃湘君(June)', '李忠鹏,覃湘君', '2019-05-02', '空运', '银河承担（客户已支付运保费）', 'CIP Harare', '江西工厂', '按照EOI项目要求', '按照EOI项目要求', 'DDZ1513', '01', '无', '4月30日晚已收到全款，需尽快安排发货。', '', '', '420', '22260', '4112', '{FC108101F4354708A2B0EE1ABFE8962E3E3FD1A05260451F8D948358003231C8}_EOI32_Sales Contact  20190502---420 DIN.pdf', '2019年5月5日', '', '', '合同评审', '02', 'CIP Harare', '收到T/T合同全款5天内安排发货', '发货后24个月', '否', '否', '否', '发货前100% T/T结清。', '否', '05', '01', '“EOI01项目报价审批”', '02', '', '02', '01', 'ZWA和EOI项目技术解析', '否', '否', '02', '否', '', '', null, null, null);
INSERT INTO `crs_tabledata696` VALUES ('728', '{AB4A2B77-64A9-4450-996A-BF2379DA5E12}', '97', 'INHE-0662', '2019-05-05 20:06:46', '0000-00-00 00:00:00', '2019-05-09 18:09:28', 'unchecked', 'n', 'n', '', '1', 'KP1/6E.3/PT/3/18/A66/LME01/合同评审', '', 'The Kenya Power * Lighting Company Limited', 'The Kenya Power & Lighting Company Limited', 'KP1/6E.3/PT/3/18/A66', 'LME', 'LME01', '2764791.06', '商务组(Commerce Division)', '陈丽', '谭东羊', '2019-05-05', '海运', '客户', 'KPLC各地仓库', '江西银河工业园', '标书要求', '标书要求', 'DDZ1513和外购微型断路器', '02', '', '1.中标通知和合同为两种金额，欧元和本地币，其中欧元金额为2,702,113.5欧元，肯先令为7,122,450.00.本地币主要用来支付内陆运输费和清关等费用。本合同流程无法输入两种币种，故将本地币折算为欧元，实际本地运输费用为7,122,450肯先令，折算为欧元为62677.56欧元，使用即时汇率：1肯先令=0.0088欧元。\r\r\n2. 同样的产品价格不一样，主要是运送的目的地不一样。', '', '', '99155', '2414108.24', '350682.82', '{AB4A2B7764A94450996ABF2379DA5E123E3FD1A05260451F8D948358003231C8}_LME合同草稿.docx', '合同签订后6个月（最快）', '', '', '合同评审', '03', 'CIP电力公司不同仓库，分别是：CIP KPLC Eldoret Stores；CIP KPLC Kisumu Stores；CIP KPLC Nakuru Stores；CIP KPLC Ruaraka Stores', '客户到江西工厂验货后', '货物验收后365天', '否', '否', '是，未按时发货金额的0.5%/周', '1.预付款：签订合同后60天支付合同金额的10%，需提交同等金额的银行保证金以及付款申请。2.发货：合同金额的80%将通过不可撤销的保兑信用证在60天内支付，需提交发票，提单，箱单，保单，保修证书，检验证书以及原产地证书等。3. 验收：合同金额的10%将于客户签发验收证明并提交付款申请后60天内支付。', '是，运保费见上。', '01', '01', 'LEA和LME项目报价申请', '02', '', '01', '01', 'LEA和LME项目技术解析申请', '是', '0.5美金/表', '02', '', '', '', null, null, null);
