INSERT INTO `crs_tabledata696` VALUES ('735', '{1F94FF21-6C83-49FA-8397-15A8B5EDC550}', '61', 'INHE-0772', '2019-05-17 19:15:19', '0000-00-00 00:00:00', '2019-05-27 08:25:33', 'unchecked', 'n', 'n', '', '1', 'P163568/GBB01/合同评审', '', '冈比亚国家水电公司', '冈比亚国家水电公司', 'P163568', 'GBB', 'GBB01', '48800', '国际二部 INTL.Business Dept.2', '张子琦(Miranda)', '张子琦', '2019-05-17', '空运', '银河', '冈比亚班珠尔', '深圳', '无', '系统上线后验收', 'i6300', '02', '', '10%预付款保函需要在合同签约后28天内开具，但项目开发周期28个工作日。经了解，工行现开保函需要3周（1周开户，2周开保函），保函会延迟收款进度，故建议GBB的预付款保函在本地开保函。', '', '', '0', '0', '0', '', '2019-06-07', '', '', '合同评审', '02', 'CIP-BANJUL GAMBIA', '收到70%发货款后', '12个月', '部分赊销，余款20%属于赊销', '是', '是', 'T/T；1.开预付款保函，客户支付预付款。2.demo确认后，支付发货款70%；3.系统上线验收后支付20%尾款', '是，掌机空运费401.5美金，单台掌机5.5美金', '01', '01', '', '02', '', '01', '01', 'GBB项目---90台掌机及数据库', '是', '3000美金', '02', '', '02', '★★★', '{1F94FF216C8349FA839715A8B5EDC5504654CAE914AA4B25B6892952453EBAEB}_合同0521.rar', null, null);
INSERT INTO `crs_tabledata696` VALUES ('736', '{501930B4-2970-4B5B-A135-3F9009C85A96}', '61', 'INHE-0819', '2019-05-20 19:46:01', '0000-00-00 00:00:00', '2019-05-27 10:30:40', 'unchecked', 'n', 'n', '', '1', 'C0880/DMC01/合同评审', '', '马达加斯加电力公司', 'jiro sy rano malagasy (JIRAMA)', 'C0880', 'DMC', 'DMC01', '350400', '国际二部 INTL.Business Dept.2', '付为(Adam)', '付为', '2019-05-20', '安全模块空运		\r\n', '我司承担		\r\n', '13, Rue Rabezavana, Lot : SIAG 15 Bis Ambodifilao,Antananarivo 马达加斯加电力公司		\r\n', '南非		\r\n', '无', 'STS标准		\r\n', 'SMARTSTS', '02', '', '此合同为英文版合同，由于客户要求合同语言为法语且不要擅自改动原合同，故将在英文版合同上做出修改意见，红色部分为业务和客户最后协商的修改意见，黄色部分为客户第一次修改内容，业务待合同评审后一并向客户提出整个需要修改的条款。', '', '', '0', '0', '0', '', '签合同之后交付\r\n', '', '', '合同评审', '02', 'DDP', '双方签署合同后', '一年', '赊销', '是', '否', '后付费，交付后30天100%TT付款', '安全模块单价包含运费，预估200usd', '02', '01', '', '02', '', '01', '01', 'DMC项目软件报价', '否', '无', '01', '两个安全模块\r\n', '01', '★★', '{501930B429704B5BA1353F9009C85A964654CAE914AA4B25B6892952453EBAEB}_合同文件.rar', null, null);
INSERT INTO `crs_tabledata696` VALUES ('737', '{3C3214F1-7BBD-4882-9865-A14135444F9F}', '61', 'INHE-0440', '2019-05-21 19:09:26', '0000-00-00 00:00:00', '2019-05-24 11:52:00', 'unchecked', 'n', 'n', '', '1', 'INHESC2019051801/TTL01/合同评审', '', 'INHEMETER (T) LIMITED', 'INHEMETER (T) LIMITED		\r\n', 'INHESC2019051801', 'TTL', 'TTL01', '9998501.75', '国际二部 INTL.Business Dept.2', '汤伟(Will)', '汤伟', '2019-05-21', '海运', '买家', '坦桑尼亚，达累斯萨拉姆', '中国，九江', '需要栈板，牢固纸箱，方便海运', 'TTL项目技术规格要求', 'DDZ 1513', '02', '详细技术规格，请参考OA【TTL项目技术解析申请】里面有翻译的技术规格要求。', '1.SKD的内盒包装, MCU和CIU的包装印上INHEMETER (T) LIMITED 和 www.inhemetertz.com， 外盒包装到货后，允许客户贴上MADE IN TANZANIA的标签，我司提供贴纸给客户。表箱上面的贴纸生产时根据客户要求定制。                      2.SKD单相含代理佣金USD 50000，SKD单相每台0.5美元（税后）。                                  3. TTL报价宋总已确认。【TTL项目报价申请 】                                               4.运费根据跟单组的报价2500/40 HQ, 发货时如果运费高于此报价，客户TT补运费差价。FOB报价，我司承担工厂到九江港的内陆运费和杂费。						\r						\r	\r', '', '', '220000', '9800000', '0', '{B4D4CC077C7F4CA79FCC39E9B5C2F6B4D4CC22B6C7B643389146528155CECD45}_TTL01_220000_SKD_Single_and_Three_Phase_Meters_20190801-FINAL.pdf', '2019年7月30日至2019年10月30日', '{B4D4CC077C7F4CA79FCC39E9B5C2F6B49E19E8E731434A848B97C6F1C79E3A54}_TTL01-5 SALES CONTRACT.pdf', '', '合同评审', '02', 'CIF，达累斯萨拉姆', '在卖方收到覆盖100%合同金额的不可撤销的保兑的远期180天的信用证。信用证条款须被合同双方接受后，45天内，从卖方工厂发出。每批次信用证开立日期和发货日期，请参考合同。', '从卖方工厂发货之日起18个月', '否', '否', '否', '合同金额的100%通过不可撤销的保兑的远期180天的信用证支付。信用证应当在合同签订之后15天内被卖方收到，且在卖方工厂启动原材料备料前信用证的条款应当取得卖方的认可。远期信用证将被卖家贴现，承兑费用和贴现费用由买家承担。', '不包含', '03', '01', '', '02', '', '01', '01', 'TTL项目技术解析申请', '是', '单相表每台需支付0.5美元(税后）', '02', '', '', '', '', null, null);
