INSERT INTO `crs_tabledata696` VALUES ('740', '{C1E5F006-53D6-4E63-BB54-98B6655BB09B}', '97', 'INHE-0773', '2019-05-27 10:58:50', '0000-00-00 00:00:00', '2019-05-28 17:24:06', 'unchecked', 'n', 'n', '', '1', 'INHESC2019052101\r\n/EOI36/合同评审', '', 'Finmark Industries (Pvt) Ltd.', '(JW) MR ITAI MANYANGA\r\r\n', 'INHESC2019052101\r\n', 'EOI', 'EOI36', '20000', '商务组(Commerce Division)', '林丹敏', '李忠鹏,覃湘君', '2019-05-27', '空运', 'CIP，银河承担（客户已支付运保费）', 'Harare哈拉雷国际机场\r\r\n', '中国任意机场\r\n', '按照EOI项目标准', '按照EOI项目标准		\r\n', 'DDZ1513；DTZ513 \r\r\n\r\r\n', '01', 'EOI库存订单销售；见OA\"EOI项目库存表生产安排\"\r\r\n', '受津巴布韦外汇管制，客户Matcol (Pvt) Ltd公司付不出款；\r\r\r\r\r\r\r\r\r\r\r\n合同2万美金从澳大利亚的个人账户名称(JW) MR ITAI MANYANGA中付款，目前已入账；\r\r\r\r\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\r\r\r\r\n目前合同的买家和签署方均已协调为付款的个人，并在合同中明确了收货方为Matcol (Pvt) Ltd；此点已经过上市办确认：此单与个人签订合同，避免了第三方付款，属个人交易（此单金额较小，可操作）；请公司评审\r\r\n', '', '', '311', '17005', '2995', '{C1E5F00653D64E63BB5498B6655BB09B3E3FD1A05260451F8D948358003231C8}_Sales Contact _EOI36_320DIN + 6 three phase_20190523.pdf', '20190528', '', '', '合同评审', '02', 'CIP；Harare哈拉雷国际机场', '货物将在卖方收到买方T/T支付的合同全款后10天内，从卖方工厂发出', '从卖方工厂发货之日起24个月', '否', '否', '否', '本合同项下的货款将采用美元支付，付款方式为：合同金额的100%在签订合同后作为预付款在发货前T/T支付。', '否；单价不包含保费和运费', '05', '01', 'EOI01项目报价审批', '02', '', '02', '01', 'EOI和ZWS技术解析申请', '否', '否', '02', '', '', '', '', null, null);
