INSERT INTO `crs_tabledata696` VALUES ('742', '{35EDDC4D-EBBD-FD30-12BF-B92178BA6889}', '61', 'INHE-0500', '2019-05-30 11:35:24', '', null, 'unchecked', 'n', 'n', null, '1', 'INHESC2019030501', '', null, null, 'INHESC2019030501', null, null, '26180', null, null, null, null, null, null, '第一批收货地点不变（已发货）：\r\nConsignee Name: Econet\r\nAddress: No.2 Old Mutare Road, Msasa Harare, Zimbabwe	\r\n	\r\n第二批收货地点变更为：\r\nConsignee Name: Distributed Power Africa\r\nConsignee \r\nAddress: Anslow Office Park, 8 Anslow Crescent, Bryanston, South Africa \r\n', null, null, null, null, null, null, '1.合同变更后：BS安装单相可更换通讯模块智能电表，带单相GPRS通讯模块和PLC显示单元，一共20台；\r\n2.合同变更后：空运和保险费用：1630美金；\r\n3.合同变更后：上述货物将在卖方收到买方T/T支付的合同全款后45天内，从卖方工厂发出。经沟通，双方均同意分两批次完成发货；\r\n4.合同变更后：去除：“配合以上1和2使用的电线杆安装单相单表位表箱，带断路器和接线端子配件，一共28台。”', null, null, '46', '4550', '0', '{C00EEEF3E6AB4DCC94B39C14A9ED749CD4CC22B6C7B643389146528155CECD45}_Sales_Contract_for_Software.pdf', null, '', '{C00EEEF3E6AB4DCC94B39C14A9ED749CBA0F4BB9344A4053BE173BB06528647F}_(Revised) Sales Contract for Software.pdf', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null);
