INSERT INTO `crs_tabledata696` VALUES ('744', '{67D711D9-9132-4C35-A5FA-B0EF5C1A5580}', '60', 'INHE-0066', '2019-05-31 14:05:33', '0000-00-00 00:00:00', '2019-06-04 12:42:26', 'unchecked', 'n', 'n', '', '1', 'INHESC2019052702/白云807/合同评审', '', '\"Aspan-Energy \" LTD', '\"Aspan-Energy \" LTD', 'INHESC2019052702', '白云', '白云807', '105600', '国际一部 INTL.Business Dept.1', '邱洁', '邱洁', '2019-05-31', '陆运', '客户', '深圳', '深圳', '按陆运运输标准', '按公司验收标准', '单、三相智能电表', '02', 'BS安装单相多费率智能电表-为2016年12月提供过白云项目所需要的：单相表低成本载波通信样机，详见OA：白云项目单相表低成本载波样机申请，客户接受样机的载波通信不是瑞斯康方案。但客户要求批量供货需采用瑞斯康的载波方案，确保电表可以和现有白云项目的集抄系统和集中器通信。', '', '', '', '5100', '105600', '0', '{67D711D991324C35A5FAB0EF5C1A55803E3FD1A05260451F8D948358003231C8}_白云807-客户已签.pdf', '2019年8月15日', '', '', '合同评审', '02', 'FOB深圳', '款到发货', '3年', '否', '否', '否', '50%TT-预付款，50%TT-发货前支付', '否', '02', '01', '', '02', '', '02', '02', '', '否', '无', '02', '', '', '', '', null, null);
INSERT INTO `crs_tabledata696` VALUES ('745', '{5D69841C-B50A-4020-8FB6-22B63EE5EDCE}', '66', 'INHE-0634', '2019-05-31 18:24:15', '0000-00-00 00:00:00', '2019-06-05 09:27:54', 'unchecked', 'n', 'n', '', '1', 'INHESC2019053001\r\n/RMY01/合同评审', '', 'Sipromad Group Company Limited', 'Global Technologies\r\n', 'INHESC2019053001\r\n', 'RMY', 'RMY01', '584466.9', '国际三部 INTL.Business Dept.3', '陈雁', '陈雁', '2019-05-31', '空运', '银河', '江西或者深圳均可，无限制', '马达加斯加Ivato机场', '无特殊要求', '无特殊要求', 'DDZ1513+DTZ1513+BOX-DIN04+TG245500+PG430500+PG460500', '02', '', '45A差动断路器要求是5-45A规格，供应商现有的规格是15-45A，不符合要求。现正加急处理中，先审批合同流程节省时间，客户方可安排支付预付款，待断路器规格确定以后再修改合同。', '', '', '7200', '278516.6', '305950.3', '{5D69841CB50A40208FB622B63EE5EDCE3E3FD1A05260451F8D948358003231C8}_Slales contract For Tender N° _002_19AONPIC2_OFID.docx', '2019年7月30日', '{5D69841CB50A40208FB622B63EE5EDCE7719915B5AFB4CFC8E75112B161686FE}_Fiche technique.pdf', '{5D69841CB50A40208FB622B63EE5EDCE7842EE48FE5340F2BE4CBD5E93168F23}_中文翻译-规格书关键内容-V3.docx', '合同评审', '02', 'CIP Ivato机场', '上述货物将在卖方收到T/T支付的合同金额的30%作为预付款及覆盖50%合同金额的不可撤销的即期信用证后60天内，从卖方工厂发出；前提是信用证条款须被合同双方接受。由于本合同项下有20%货款是在发货前10天T/T支付，如果买方未及时支付，交货时间应相应推迟。', '3年（标书硬性条款）', '否', '否', '否', '合同金额的30%在签订合同10天内作为预付款T/T支付；20%货款在发货前10天T/T支付；50%余款通过不可撤销的即期信用证支付。', '是，（CIP-FOB）价差÷总数量18530=6.18美金', '03', '01', '', '02', '', '01', '01', 'RMY项目解析申请', '否', '无', '02', '', '02', '★★★', '', null, null);
INSERT INTO `crs_tabledata696` VALUES ('746', '{E03E8E51-DD25-4BAC-B2BC-3D8D7AAEDE0B}', '60', 'INHE-0790', '2019-06-03 08:41:05', '0000-00-00 00:00:00', '2019-06-05 09:27:06', 'unchecked', 'n', 'n', '', '1', 'INHESC2019042501/JES10/合同评审', '', 'JES Instrumentation * Controls', 'ALLURE TRADING DMCC', 'INHESC2019042501', 'JES', 'JES10', '71520.6', '国际一部 INTL.Business Dept.1', '莫亚检', '莫亚检', '2019-06-03', '海运', '客户承担', '深圳', '深圳', '常规包装', '常规标准', '', '02', '无', '', '', '', '580', '58251', '4500', '{9E653DE94CBE4E85B4D212F1E4C2FDCED4CC22B6C7B643389146528155CECD45}_Sales Contract for JES.pdf', '卖方收到买方T/T支付的合同全款后45天内，从卖方工厂发出。', '', '{9E653DE94CBE4E85B4D212F1E4C2FDCEBA0F4BB9344A4053BE173BB06528647F}_合拆分同.zip', '合同评审', '02', 'FOB Shenzhen', '卖方收到买方T/T支付的合同全款后45天内，从卖方工厂发出。', '从卖方工厂发货之日起12个月', '否', '否', '无', '合同金额的30%在签订合同前作为预付款T/T支付，70%余款在发货前T/T支付。', '否', '05', '01', '报价参照JES09报价，报价已经公司审核。', '02', '', '02', '02', '', '否', '无佣金', '02', '', '', '', '', null, null);
INSERT INTO `crs_tabledata696` VALUES ('747', '{41390074-04F3-4F22-9F28-2B5DFB2ADB9E}', '61', 'INHE-0578', '2019-06-03 17:36:02', '0000-00-00 00:00:00', '2019-06-05 09:29:38', 'unchecked', 'n', 'n', '', '1', 'INHESC2019050801/EOI33/合同评审', '', 'Finmark Industries (Pvt) Ltd.', 'Helcraw Electrical (Pvt) Ltd', 'INHESC2019050801', 'EOI', 'EOI33', '520000', '国际二部 INTL.Business Dept.2', '覃湘君(June)', '李忠鹏,覃湘君', '2019-06-03', '空运', '银河承担', 'CIP Harare', '江西工厂', '按照EOI项目要求', '按照EOI项目要求', 'DTZ1513', '02', '', '1. 5.7日收到客户TT支付20%预付款，5.10日申请下单生产，要求交期为6.20日；\r\n2. 本订单将分批次发货（见合同），第一批300台使用现有库存，后续使用新生产电表。', '', '', '4000', '520000', '0', '{4139007404F34F229F282B5DFB2ADB9E3E3FD1A05260451F8D948358003231C8}_Sales Contract  20190603---4000 BS3P Meters_Revised.pdf', '2019年6月20日', '', '', '合同评审', '02', 'CIP Harare', 'TT收到每批次全款金额后5天内安排发货对应批次货物。', '发货后24个月。', '否', '否', '否', 'TT收到每批次全款金额后安排发货对应批次货物。', '包含空运费和保费，空运费为12.58USD（分批发货平均价格），保费为0.14USD。', '05', '01', 'EOI01项目报价审批', '02', '', '02', '01', 'ZWS和EOI项目技术解析', '否', '否', '02', '', '', '', '', null, null);
INSERT INTO `crs_tabledata696` VALUES ('748', '{1AF45F51-4155-49C6-9C3F-D4B02461D88C}', '61', 'INHE-0642', '2019-06-04 03:45:33', '0000-00-00 00:00:00', '2019-06-10 15:41:18', 'unchecked', 'n', 'n', '', '1', 'ESC 0061/ICB/G/FY2018-19\r\n/M15/合同评审', '请准确理解合同付款条件', 'ELECTRICITY SUPPLY CORPORATION OF MALAWI LIMITED', 'ESCOM', 'INHESC2019060401\r\r\n', 'M15', 'M15', '2842605', '国际二部 INTL.Business Dept.2', '潘正豪(James)', '潘正豪', '2019-06-04', '海陆联运', '银河', 'ESCOM Receiving store, Chichiri, Blantyre, Malawi', '江西工厂', '', '', '', '02', '底部接线，IP67等参数，详见技术参数', '合同有两处错误，一处是签字处的公司名称，采购经理已经更改，第二是交期上的表箱数量，采购经理表示将会在PO中更正', '', '', '50000', '1740500', '973470', '{1AF45F51415549C69C3FD4B02461D88C3E3FD1A05260451F8D948358003231C8}_M15项目合同.pdf', '收到预付款后的12周内交付第一批，12-18周交付第二批', '', '', '合同评审', '02', 'CIF', '1. 收到20%预付款加FAT和培训费用后开始生产2. 收到40%总货值发货25000台电表以及20500个表箱3. 收到40%总货值发货25000台电表以及20500个表箱', '48 个月', '否', '否', '0.5%每周', '预付款：20%产品总金额加上FAT和培训金额第一批货物款项：总货物金额的40%在第一批货物发货前交付第二批货物款项：总货物金额的40%在第二批货物发货前交付', '（1）电表：FOB单价：$30.20，运费：$0.62，保费：$0.06（2）两表位表箱：FOB单价：$14.00 运费：$2.01 保费：$0.06（3）四表位表箱：FOB单价：$25.00 运费：$4.68 保费: $0.06（4）六表位表箱：FOB单价：$41.50 运费：$7.80 保费: $0.06', '01', '01', '', '02', '', '01', '01', 'M国市场-M15项目技术解析申请', '否', '否', '02', '', '', '', '', null, null);
INSERT INTO `crs_tabledata696` VALUES ('749', '{4CE640FF-B221-4062-B3EE-89DF3F4E0E9E}', '97', 'INHE-0549', '2019-06-05 17:53:52', '0000-00-00 00:00:00', '2019-06-11 13:58:43', 'unchecked', 'n', 'n', '', '1', 'INHESC2019052801\r\n/CAM01-2/合同评审', '', 'Société IYA', 'Société IYA', 'INHESC2019052801\r\n', 'CAM', 'CAM01-2', '73392', '商务组(Commerce Division)', '王秀明', '王秀明', '2019-06-05', '海运', '客户', '江西九江', '江西九江', '无', '无', 'DTZ1513', '01', '', '马里的IYA公司拿我司三款样机参与马里电力公司投标，中了其中三相预付费代码表的标。但是由于预付款由香港开怀实业有限公司帮其转账支付，尾款由其自己支付，故我把原来与香港公司签订的合同按照实际收款金额拆成了两个，即我司直接与香港开怀实业有限公司和马里IYA公司分别签署销售合同,以避免第三方支付。由于马里的IYA公司多转了USD388尾款，我把与其签署的合同单价调高了0.45美元以方便入账。						\r\r\r\r\r\r\r\r\r\n', '', '', '960', '73392', '0', '{4CE640FFB2214062B3EE89DF3F4E0E9E3E3FD1A05260451F8D948358003231C8}_CAM01-2合同.pdf', '2019年6月', '', '', '合同评审', '02', 'FOB JIUJIANG, CHINA', '在卖方收到买方100%的付款后60天内完成生产和发货。', '从工厂发货之日起12个月', '否', '否', '否', '合同金额的100%在发货前T/T 支付。', '否', '03', '03', '', '02', '', '01', '01', 'CAM项目技术解析', '否', '无', '02', '', '', '', '', null, null);
INSERT INTO `crs_tabledata696` VALUES ('750', '{D840AAA6-6668-43E8-BD65-EFCCAD2F5F14}', '61', 'INHE-0500', '2019-06-05 20:59:10', '0000-00-00 00:00:00', '2019-06-26 10:21:56', 'unchecked', 'n', 'n', '', '1', 'INHESC2019060501\r\n/CDE01/合同评审', '请重签合同', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'Nyamezela Metering (Pty) Ltd\r\n', 'INHESC2019060501\r\n', 'CDE', 'CDE01', '241000', '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '李忠鹏,覃湘君', '2019-06-05', '客户指定货代空运或者海运', '客户承担', '货交客户指定货代深圳', '江西工厂', '按照ESA项目成本包装，具体请和业务确认', '请按照CDE解析解析和客服输出技术规格执行验收', 'DDZ1513，DTZ1513，BOX160', '02', '', '1.CDE市政中标合同为12个月框架性采购合同，为银河&NYC首次中标此市场8大大都市市政公司项目，预计合同总需求数量为：\r\nBS单相二线一体式可更换通讯模块表智能电表，带单相GPRS通讯模块表和外置天线 约1万台；\r\nBS单相二线一体式可更换通讯模块表智能电表，带单相GPRS通讯模块表和外置天线 约5000台；\r\n中电流表箱，BOX160，约500台；\r\nCT/VT多功能电表，预计500台。\r\n\r\n2.如OA“CDE市政中标项目库存申请”：\r\n李忠鹏于6月13日应邀到市政公司做售前技术培训和交流，接触到了电力公司核心技术管理层（Bulk Metering Manager，Prepaid Metering Manager，Senior Revenue Assurance Manager等）以及支持NYC的技术层面内线，如以上OA反馈基本一致：\r\n\r\n2.1.参加会议的工程师明显分为两个派系，其中2名白人工程师支持Elster，在技术会议上专挑刁钻的问题针锋相对，并特别拿出了Elster上个合同供货的CT表和模块，当着所有人的面说我们的CT表没有Elster好，并质疑我们的功能不完善。好在基本的问题我们的现场实操都顺利展示，并且主导会议的两名核心人员（Bulk Metering Manager和Senior Revenue Assurance Manager）都为NYC站台，所以实际会议除了一个技术问题外（另技术解析OA反馈），其他功能性展示顺利通过。\r\n\r\n2.2.NYC的合同周期只有11个月，从2019年6月10日签合同日开始算起，根据现场Bulk Metering Manager和Senior Revenue Assurance Manager建议，我们一定要迅速供货，这样他们作为用服部门才能快速帮我们安装到现场。据目前他们两人的反馈：直通单相表和三相表至少有2万个用户需要换表（当前市政公司除了Elster在上个合同供应了2200台 智能CT表外，直通单相和三相居民用户使用的均是非智能电表和机械表），BOX160预计有500个用户需求，CT表可能会少点，但是他们会极力帮忙推。\r\n\r\n2.3.南非市政公司付款都很迅速，根据我了解的目前中标的几个小市政公司，基本上送货后一个星期内都给NYC付了款。\r\n\r\n2.4.如之前CDE和CDL项目演示汇报，市政公司需要我们开放协议给其AMR系统供应商，公司已经审批，需要抓紧找研发何工协助提供。\r\n\r\n2.5.结合目前N4的状况，业务强烈建议公司不要再等待，恳请公司尽快开始审批以上李忠鹏的库存建议，同时李忠鹏在跟进完成在发货前NYC支付掉已下单的400台订单款项。\r\n\r\n研发需要时间准备程序，工厂更加需要时间生产，最后浪费掉的是我们自己的合同剩余时间！', '', '', '2100', '241000', '0', '', '要求在45天内生产完成\r\r\n', '', '{D840AAA6666843E8BD65EFCCAD2F5F147842EE48FE5340F2BE4CBD5E93168F23}_20190615_CDE01 Sales Confirmation_INHESC2019060501.docx', '合同评审', '02', 'FCA SHENZHEN', '第一批发货安排：买方应在生产完成前10天T/T支付该合同全款金额。上述货物将在生产完成后7天内从卖方工厂发出。第二批发货安排：买方应在第一批电表发货后的90天内T/T支付该合同全款金额。上述货物将在卖方收到买方合同金额100%付款后7天内从卖方工厂发出。', '卖方所提供货物的保修期为从卖方工厂发货之日起18个月。', '否', '否', '否', '本合同项下的货款将采用美元支付，付款方式如下：第一批发运合同金额的100%需要在生产完成前10天通过T/T支付。第二批发运合同金额的100%需要在第一批电表发货后的90天内通过T/T支付。', '不含', '03', '01', '', '02', '', '01', '01', 'CDE技术解析申请', '否', 'N.A', '02', '', '02', '★★★', '', null, null);
INSERT INTO `crs_tabledata696` VALUES ('751', '{1597022C-2914-4861-8F8B-065548DB687D}', '97', 'INHE-0549', '2019-06-06 08:33:20', '0000-00-00 00:00:00', '2019-06-11 13:57:46', 'unchecked', 'n', 'n', '', '1', 'INHESC2019022601/CAM01-1/合同评审', '', 'Société IYA', 'Hong Kong Kaihuai Industry CO., Limited\r\n香港开怀实业有限公司		\r\n', 'INHESC2019022601', 'CAM', 'CAM01-1', '79040', '商务组(Commerce Division)', '王秀明', '王秀明', '2019-06-06', '海运		\r\n', '客户		\r\n', '江西九江		\r\n', '江西九江		\r\n', '无		\r\n', '无		\r\n', 'DTZ1513', '01', '马里的IYA公司拿我司三款样机参与马里电力公司投标，中了其中三相预付费代码表的标。但是由于预付款由香港开怀实业有限公司帮其转账支付，尾款由其自己支付，故我把原来与香港公司签订的合同按照实际收款金额拆成了两个，即我司直接与香港开怀实业有限公司和马里IYA公司分别签署销售合同,以避免第三方支付。由于马里的IYA公司多转了USD388尾款，我把与其签署的合同单价调高了0.45美元以方便入账。						\r\r\r\r\r\r\r\r\n						\r\n', '', '', '', '1040', '79040', '0', '{1597022C291448618F8B065548DB687D3E3FD1A05260451F8D948358003231C8}_CAM01-1合同.pdf', '2019年6月', '', '', '合同评审', '02', 'FOB JIUJIANG, CHINA', '在卖方收到买方100%的付款后60天内生产和发货。', '从工厂发货之日起12个月', '否', '否', '否', '合同金额的100%在发货前T/T 支付。', '否', '03', '01', '', '02', '', '01', '01', 'CAM项目技术解析', '否', '无', '02', '', '', '', '', null, null);
INSERT INTO `crs_tabledata696` VALUES ('752', '{EF5B364A-FE68-4CB9-9004-5EFBFE8F2569}', '97', 'INHE-0773', '2019-06-15 19:01:10', '0000-00-00 00:00:00', '2019-06-17 10:02:18', 'unchecked', 'n', 'n', '', '1', 'INHESC2019061401\r\n/EOI37/合同评审', '', 'Finmark Industries (Pvt) Ltd.', 'Mining and Industrial Suppliers (Pvt) Ltd', 'INHESC2019061401\r\n', 'EOI', 'EOI37', '52890', '商务组(Commerce Division)', '林丹敏', '李忠鹏,覃湘君', '2019-06-15', '空运', 'CIP, 银河承担（客户已支付运保费）', 'Harare 哈拉雷国际机场', '中国任意机场', '按照EOI项目标准', '按照EOI项目标准', 'DDZ1513,DTZ1513', '01', 'EOI项目库存订单销售；见OA标题“EOI项目库存单生产安排”', 'EOI37的买方为Inhegrid Co., Ltd.珠海银河智能电网有限公司，与客户签订合同、交易、发货；6/14收到本合同金额全款的银行水单', '', '', '700', '46300', '6590', '{EF5B364AFE684CB990045EFBFE8F25693E3FD1A05260451F8D948358003231C8}_Sales Contract for 500DIN+200 BS 3P Meters_20190614.pdf', '2019-06-17', '', '', '合同评审', '03', 'CIP，Harare哈拉雷国际机场', '在卖方收到买方T/T支付的合同全款后10天内，从卖方工厂发出', '从卖方工厂发货之日起24个月', '否', '否', '否', '本合同下的付款货币为欧元；合同金额的100%须在签订合同需在签订合同后作为预付款在发货前T/T支付', '否，单价不含运费和保费', '05', '01', 'EOI01项目报价审批', '02', '', '02', '01', 'EOI和ZWS项目技术解析', '否', '否', '02', '', '', '', '', null, null);
