INSERT INTO `crs_tabledata696` VALUES ('757', '{BF4E34AE-751D-457A-9A47-9C9096ED3199}', '66', 'INHE-0634', '2019-07-04 08:56:57', '0000-00-00 00:00:00', '2019-10-18 16:28:08', 'unchecked', 'n', 'n', '', '1', 'INHEPI19070301/KNT02/合同评审', '', 'Kinetic Myanmar Technology Co., Ltd', '黄世富', 'KMT/KCKM-03929/2019', 'KNT', 'KNT02', '4320', '国际三部 INTL.Business Dept.3', '陈雁', '陈雁', '2019-07-04', '客服前往现场时随身携带', '银河', '仰光', '江西-深圳', '保证货物不破损不影响正常使用', '无', 'IHM4000', '01', '', '客户追加购买一台集中器，解决KNT01现场剩余50台表计通讯问题。现该集中器已经在现场运行使用，现补走销售流程，安排客户支付货款。由于客户美元账户有问题迟迟无法汇出，故安排第三方付款，客户已经承诺2019年10月16日可以签回附件中2份第三方付款委托函和受托函。', '', '', '1', '4320', '0', '{BF4E34AE751D457A9A479C9096ED31993E3FD1A05260451F8D948358003231C8}_KMT-KCKM-03929-19.PDF', '2019年7月3日', '{BF4E34AE751D457A9A479C9096ED31997719915B5AFB4CFC8E75112B161686FE}__KMT-KCKM-03929-19.docx', '{BF4E34AE751D457A9A479C9096ED31997842EE48FE5340F2BE4CBD5E93168F23}_paid party sign and stamp.docx', '合同评审', '04', 'DDP 仰光', '货物已经在现场使用', '1年', '否', '否', '否', '100%TT转账', '否', '02', '02', 'KNT01', '01', '{BF4E34AE751D457A9A479C9096ED3199EA23E848092D41CC83988AEE534D6267}_Kinetic sign and stamp.docx', '01', '01', 'KNT项目云平台维护', '否', '无', '02', '', '00', '★', '', null, null);
