INSERT INTO `crs_tabledata696` VALUES ('761', '{A908630B-3182-4711-88C5-5D037B81E499}', '61', 'INHE-0772', '2019-07-16 13:50:25', '0000-00-00 00:00:00', '2019-08-12 22:36:13', 'unchecked', 'n', 'n', '', '1', 'INHESC2019071602/GBC01/合同评审', 'GBC合同资料更新，支付方式已明确，信保已承保，客户名字已更正', '冈比亚国家水电公司', 'NATIONAL WATER AND ELECTRICITY COMPANY LTD', 'GM-NAWEC-72939-GO-RFB', 'GBC', 'GBC01', '387217.97', '国际二部 INTL.Business Dept.2', '张子琦(Miranda)', '张子琦', '2019-07-16', '海运', '银河', 'NAWEC Stores, Banjul, The Gambia', '九江', '银河标准，电表面板印电力公司LOGO', '银河标准', '', '02', 'LPU计量箱变更，箱体尺寸，CT安装在箱外，客户接受新方案，详细如技术规格附件的照片要求', '1.LOT3的产品单价为平均价：该标段特殊，有15个电流规格，只影响CT的规格，不影响电表，CT对价格影响小。按均价填写，不一一单列。 2.合同种支付方式明确，T/T.	\r\r\r\n', '', '', '2000', '360217.97', '0', '{A908630B3182471188C55D037B81E4993E3FD1A05260451F8D948358003231C8}_GBC合同及附件.rar', '6周', '{A908630B3182471188C55D037B81E4997719915B5AFB4CFC8E75112B161686FE}_变更后 LOT3 技术方案.rar', '', '合同评审', '02', 'CIP NAWEC Stores, Banjul, The Gambia', '交期内发货', '730天', '是，90%金额属于赊销。', '是,信保已承保，有额度', '是，违约金0.5%/周，罚金最高不超过10%。', 'T/T, 预付款10%合同金额在收到履约保函后30天内支付；80%货款见单即付（装箱单，提单，发票）；10%余款在采购方出具验收证明后30天内支付', '是，报价总运费总计24000美金。因CT表箱规格未确定，装箱单数据需以最最终技术规格的装箱单为准。', '01', '01', '', '02', '', '01', '01', 'GBC项目申请技术解析支持', '是', 'FOB报价的8%；单相表3.2美金一台；软件佣金2000美金；CT表位21.524美金一台', '02', '', '02', '★★★', '', null, null);
INSERT INTO `crs_tabledata696` VALUES ('762', '{093525D3-0722-4216-86CE-F46685E9DBF9}', '66', 'INHE-0634', '2019-07-17 16:46:55', '0000-00-00 00:00:00', '2019-07-17 17:40:29', 'unchecked', 'n', 'n', '', '1', 'INHESC2019053001/RMY01/合同评审', '', 'Sipromad Group Company Limited', 'Global Technologies', 'INHESC2019053001', 'RMY', 'RMY01', '464466.94', '国际三部 INTL.Business Dept.3', '陈雁', '陈雁', '2019-07-17', '海运', '银河', '江西工厂', '江西工厂', '可以进行飞机装运，保护货物完好', '电力局2名官员以及代理到江西工厂进行验货', '见附件合同第一条：产品规格', '02', '', '', '', '', '7200', '242890.1', '221576.84', '{D226D2D99FFF4CAF95E542EDCCB02663D4CC22B6C7B643389146528155CECD45}_RMY01销售合同-变更-20191009.docx', '2019年9月19日', '{D226D2D99FFF4CAF95E542EDCCB026639E19E8E731434A848B97C6F1C79E3A54}_RMY技术附件.pdf', '{D226D2D99FFF4CAF95E542EDCCB02663BA0F4BB9344A4053BE173BB06528647F}_RMY_运费拆分表-20191009.xlsx', '合同评审', '02', 'CIP Ivato Airport Madagascar', '上述货物将在卖方收到T/T支付的合同金额的30%作为预付款及覆盖50%合同金额的不可撤销的保兑即期信用证后60天内，从卖方工厂发出；前提是信用证条款须被合同双方接受。交期60天的计算从收到30%T/T预付款或者不可撤销的保兑即期信用证后以较晚的日期开始计算。由于本合同项下有20%货款是在发货前10天T/T支付，如果买方未及时支付，交货时间应相应推迟。', '3年（标书硬性条款）', '否', '否', '是。如果卖方未能根据合同中的发货条件及时发货，则卖方向买方支付罚金。付款延迟的前10天不必缴纳罚金，超过10天以后罚金收费比例为按照合同总货值的0.5%每周收取，如果延迟少于一周则视为一周处理。', '合同金额的30%在签订合同10天内作为预付款T/T支付；20%货款在发货前10天T/T支付；50%余款通过不可撤销的保兑即期信用证支付。信用证应当在合同签订之后15天内被卖方收到，且在卖方工厂启动原材料备料前信用证的条款应当取得卖方的认可。', '是。保费是货值1.1倍，运费约115000美元。', '03', '01', '无', '02', '', '01', '01', 'RMY项目解析申请', '否', '无', '02', '否', '02', '★★★', '', null, null);
