INSERT INTO `crs_tabledata696` VALUES ('773', '{FC73CE40-FEC3-4FFE-AB2D-FA1DF5530BC8}', '61', 'INHE-0440', '2019-08-22 07:28:57', '0000-00-00 00:00:00', '2019-08-23 16:45:32', 'unchecked', 'n', 'n', '', '1', 'INHESC2019080101/TTL02/合同评审', '合同编号请核实', 'INHEMETER (T) LIMITED', 'INHEMETER (T) LIMITED', 'INHESC2019080101', 'TTL', 'TTL02', '1153415.48', '国际二部 INTL.Business Dept.2', '汤伟(Will)', '汤伟', '2019-08-22', '海运', '买家', '坦桑尼亚，达累斯萨拉姆', '中国，九江', '需要栈板，牢固纸箱，方便海运', 'TTL项目技术规格', '单相DDZ 1513 三相DTZ 1513', '01', '单相表参考TTA项目出货进行翻单生产，三相表需要按照和EDMI的AMR软件兼容要求进行生产。', '1.SKD的内盒包装, MCU和CIU的包装印上INHEMETER (T) LIMITED 和 www.inhemetertz.com， 外盒包装到货后，允许客户贴上MADE IN TANZANIA的标签，我司提供贴纸给客户。表箱上面的贴纸生产时根据客户要求定制。                                                                        2.SKD单相佣金FOB每台0.5美元，SKD三相佣金FOB每台3美元。                                  3.TTL报价宋总已确认。【TTL项目报价申请 】                                               4.运费根据跟单组的报价2500/40 HQ。FOB报价，我司承担工厂到九江港的内陆运费和杂费。          ', '', '', '26000', '1130800', '22615.48', '{FC73CE40FEC34FFEAB2DFA1DF5530BC83E3FD1A05260451F8D948358003231C8}_TTL01-1 TTL02 24000+2000 SKD Single Phase and Three Phase Meters 20190801.pdf', '20190828', '{FC73CE40FEC34FFEAB2DFA1DF5530BC87719915B5AFB4CFC8E75112B161686FE}_技术规格.pdf', '{FC73CE40FEC34FFEAB2DFA1DF5530BC87842EE48FE5340F2BE4CBD5E93168F23}_TTL01-1 TTL02 担保函.pdf', '合同评审', '02', 'CIF，达累斯萨拉姆', '本合同项下的货物将在卖方收到31%的预付款后30天内，从卖方工厂发出。', '卖方所提供货物的保修期为从卖方工厂发货之日起18个月。', '是', '是', '否', '预付款合同金额的31%(USD 357,558.80)将在签订合同后7天内通过T/T支付。余款合同金额的69%(USD 795,856.68)将在提单日后90天内通过T/T支付。余款合同金额的69% (USD 795,856.68) 将采用Sinosure投保，买家需要在发货前提供担保方AFRICARRIERS LIMITED签署的担保函原件。承担采用赊销方式所产生的融资费用和保费。买方应及时支付卖方的所有货款和本条款提及的费用。', '不包含保费和运费', '03', '01', 'TTL项目报价申请', '02', '', '01', '01', 'TTL项目技术解析申请', '是', '单相FOB 0.5 USD 每台，三相FOB 3 USD 每台', '02', '', '', '', '', null, null);
INSERT INTO `crs_tabledata696` VALUES ('774', '{CD32C39C-E7D0-4B7B-A0EF-4B98F0075E08}', '66', 'INHE-0634', '2019-08-22 17:48:59', '0000-00-00 00:00:00', '2019-08-26 17:21:29', 'unchecked', 'n', 'n', '', '1', 'INHESC2019091601/RMY02/合同评审', '', 'Sipromad Group Company Limited', 'Global Technologies', 'INHESC2019091601\r\n', 'RMY', 'RMY02', '95774.81', '国际三部 INTL.Business Dept.3', '陈雁', '陈雁', '2019-08-22', '100%海运', '银河', '深圳或者江西，无特殊限制', '马达加斯加IVATO机场', '无特殊要求', '无特殊要求', 'DDZ1513#FE54`BOX-DIN04#FE54`TG245500', '02', '', '同RMY01，追加订单，做成RMY02执行。', '', '', '1603', '49612.85', '46161.96', '{CD32C39CE7D04B7BA0EF4B98F0075E083E3FD1A05260451F8D948358003231C8}_Sales Contract-20190822.docx', '2019年10月15日', '{CD32C39CE7D04B7BA0EF4B98F0075E087719915B5AFB4CFC8E75112B161686FE}_20190822150025766.pdf', '', '合同评审', '02', 'CIP IVATO', '上述货物将在卖方收到T/T支付的合同金额的30%作为预付款及覆盖70%合同金额的不可撤销的保兑即期信用证后60天内，从卖方工厂发出；前提是信用证条款须被合同双方接受。交期60天的计算从收到30%T/T预付款或者不可撤销的保兑即期信用证后以较晚的日期开始计算。如果买方未及时支付，交货时间应相应推迟。', '3年（标书要求，同RMY01）', '否', '否', '是，如果卖方未能根据合同中的发货条件及时发货，则卖方向买方支付罚金。付款延迟的前10天不必缴纳罚金，超过10天以后罚金收费比例为按照合同总货值的0.5%每周收取，如果延迟少于一周则视为一周处理。', '本合同项下的货款将采用美元支付，付款方式如下：合同金额的30%在签订合同10天内作为预付款T/T支付；50%余款通过不可撤销的保兑即期信用证支付。信用证应当在合同签订之后15天内被卖方收到，且在卖方工厂启动原材料备料前信用证的条款应当取得卖方的认可。', '是，单相表运保费2.65美元/台；单相表箱22.66美元/每台；断路器1.38美元/每个', '03', '02', 'RMY投标报价申请', '02', '', '01', '01', 'RMY项目生产预安排', '否', '无', '02', '', '02', '★★★', '', null, null);
INSERT INTO `crs_tabledata696` VALUES ('775', '{0DB0EA81-D4DC-465D-BE4A-18A6952A7B4C}', '97', 'INHE-0549', '2019-08-23 15:30:09', '0000-00-00 00:00:00', '2019-08-28 09:00:12', 'unchecked', 'n', 'n', '', '1', 'GLP01/INHESC2019072504/合同评审', '', 'Inhegrid', '珠海银河智能电网有限公司', 'INHESC2019072504', 'GLP', 'GLP01', '459996.55', '商务部(Commerce Division)', '王秀明', '姜盼(Nadine Jiang)', '2019-08-23', '海陆联运', '珠海银河智能电网有限公司', '江西工厂', '蛇口港', '牢固的纸箱', '以双方确认的产品规格为准，卖方交付产品时，买方当场验收并向卖方出具验收合格证明文件，产品交付之日起3日内，买方未组织验收、未出具验收合格证明文件或未提出验收异议的，视为默认产品已验收合格', '', '02', '', '', '', '', '535', '230561.8', '229434.75', '{93F7AE4CA63543C9B85C3B22E5684D7CD4CC22B6C7B643389146528155CECD45}_GLP项目深圳银河和珠海配电销售合同.pdf', '2019-10-10', '', '', '合同评审', '04', 'CIP刚果金戈马', '合同签订后，卖方于45天内完成生产。', '自卖方工厂发货之日起18个月', '是', '否', '否', '月结', '不含', '05', '01', '', '02', '', '01', '01', 'GLP项目申请技术支持apply for technical support for GLP project', '否', '无', '02', '', '00', '★', '', null, null);
