INSERT INTO `crs_tabledata696` VALUES ('779', '{4A0AE95E-9E92-4D2C-85E9-2307BFA0966B}', '61', 'INHE-0843', '2019-09-09 00:58:59', '0000-00-00 00:00:00', '2019-09-11 16:26:53', 'unchecked', 'n', 'n', '', '1', 'INHESC2019090401/MXP01/合同评审', '', 'Protecsa Ingeniería S.A. de C.V.', 'Powermex Energy S.A de C.V.', 'INHESC2019090401', 'MXP', 'MXP', '340120.72', '国际二部 INTL.Business Dept.2', '刘畑杏(Laura)', '刘畑杏', '2019-09-09', '海运、空运\r\n', '银河', '15,000套海运，CIF Manzanillo, Mexico；5,000套空运，CIP Queretaro International Airport, Mexico', '合同项下的15,000套货物的运输方式为海运，起运港为中国深圳，卸货港为墨西哥曼萨尼约。合同项下的5,000套货物的运输方式为空运，起运地为中国香港，目的机场为墨西哥克雷塔罗国际机场。\r\n', 'SKD包装', '客户验货', 'iR10', '02', '1.主板上移除测试模式切换按钮，但是依然保留此功能用于软件操作#FE54`\r\r\r\n2.主板新增三个LED位置：第一盏（红色）电源灯（闪烁为正常状态，常亮为异常事件）；第二盏无功（黄色）电能指示灯；第三盏（绿色）有功电能指示灯；\r\r\n3.红外端口移到电表右侧，符合客户目前产品的外观要求；\r\n4.单继电器、单CT', '', '', '', '0', '0', '0', '', '收到合同金额的20%T/T预付款后50天内完成生产\r\r\n', '', '{4E2D95C9DDFB4B6E9B31F920CCA48D0EBA0F4BB9344A4053BE173BB06528647F}_MXP01项目销售合同变更补充协议_20200515.docx', '合同评审', '02', 'CIF Manzanillo, Mexico', '收到合同金额的20%T/T预付款后50天内完成生产', '从卖方工厂发货之日起12个月', '否', '否', '否', '合同金额的20%在签订合同5个工作日之内作为预付款T/T支付，合同金额的10%在签订合同15个工作日之内作为预付款T/T支付，余款70%通过不可撤销的保兑的远期90天信用证支付。信用证应当在合同签订之后15个工作日内被卖方收到，且信用证的条款应当取得卖方的认可。', '包含运费和保费。保险应由卖方按照货值的110%购买一切险。运费每件约0.3美元。', '06', '01', '', '02', '', '02', '02', '无', '否', '无', '02', '', '03', '★★★★', '', null, null);
