INSERT INTO `crs_tabledata696` VALUES ('782', '{F1B1F6DA-9B2E-4931-AA1E-5C888151F4AB}', '143', 'INHE-0773', '2019-09-18 14:27:26', '0000-00-00 00:00:00', '2019-09-20 11:37:17', 'unchecked', 'n', 'n', '', '1', 'INHESC2019091801\r\n/EOI44/合同评审', '', 'Finmark Industries (Pvt) Ltd.', 'HELIFLEX INVESTMENTS PRIVATE', 'INHESC2019091801', 'EOI', 'EOI44', '165850', '竞标组', '林丹敏', '李忠鹏', '2019-09-18', '空运', '银河承担运保费', 'Harare哈拉雷国际机场', '中国任意机场', '按照EOI项目要求', '按照EOI项目要求', 'DDZ1513, DTZ1513', '02', '', 'EOI44为库存订单销售\r；\r\r\n\r20190908已收到本合同全款水单，跟进银行到账进度中。', '', '', '250', '145050', '20800', '{F1B1F6DA9B2E4931AA1E5C888151F4AB3E3FD1A05260451F8D948358003231C8}_Sales Contact for HELIFLEX INVESTMENTS PRIVATE 190918.pdf', '2019.09.24', '', '', '合同评审', '04', 'CIP Harare哈拉雷国际机场', '上述货物将在卖方收到买方T/T支付的合同全款后5天内，从卖方工厂发出。', '24个月', '否', '否', '否', '合同金额的100%在签订合同30天内作为预付款在发货前T/T支付。', '否', '05', '01', 'OA“EOI01报价审批”', '02', '', '02', '01', 'EOI和ZWS技术解析申请', '否', '否', '02', '', '', '', '', null, null);
INSERT INTO `crs_tabledata696` VALUES ('783', '{F933B7D1-482A-4FC9-90AF-B2BC2F8C8E4F}', '143', 'INHE-0773', '2019-09-18 15:12:46', '0000-00-00 00:00:00', '2019-09-20 11:33:37', 'unchecked', 'n', 'n', '', '1', 'INHESC2019091101/BAP07/合同评审', '', 'FactorFast (PTY) Ltd', 'FactorFast (PTY) Ltd', 'INHESC2019091101', 'BAP', 'BAP07', '3.4', '竞标组', '林丹敏', '李忠鹏', '2019-09-18', '无', '无', '无', '无', '无', '无', 'SmartVEND、SmartView', '01', '', 'BAP市场电表全部采用银河标准产品，配合银河SmartVEND、SmartView系统使用，代理已经买了服务器。201809银河已帮客户重新安装、调试SmartVEND、SmartView系统，License有效期为1年，201909已过期，并已提供新的License给客户。\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\n本合同计划作为对SmartVEND、SmartView系统按月收费的依据，从20190901至20190930为第一个月。由于数量是区间值，合同金额未定，计划每月提供收款PI作为合同的附件之一。\r烦请公司领导审批同意。\r\r\r\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\r\r\r\r\r\r\r\n根据OA“BAP07项目集抄、售电系统报价申请”审批意见：\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\n1、小客户、软件维护量不高。\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\n2、客服部负责维护，软件事业部支持。\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\n3、业务部负责计算收费。', '', '', '0', '0', '0', '', 'SmartVEND和SmartView已安装，按1年期License提供，到期更新。', '', '', '合同评审', '02', '无', 'SmartVEND和SmartView已安装，按1年期License提供，到期更新。', '无', '否', '否', '否', '100%的月费用应在签订合同后通过T/T方式支付，且在每月的第一天FACTORFAST需支付本月的费用，按以下计算公式进行：月费用 = 每月系统中接入的总电表数量 × 每月每套表费用；第一个收费月为2019年9月1日至2019年9月30日', '无', '05', '01', 'OA“BAP07项目集抄、售电系统报价申请”', '02', '', '02', '01', 'BAP02和BAP03项目申请客服部协助', '否', '否', '02', '', '', '', '{F933B7D1482A4FC990AFB2BC2F8C8E4F4654CAE914AA4B25B6892952453EBAEB}_Sales Contract INHESC2019091101 for Inhemeter Software.pdf', null, null);
INSERT INTO `crs_tabledata696` VALUES ('784', '{928BB9D7-F65B-479F-B2CB-D1E8EE0A96CE}', '61', 'INHE-0500', '2019-09-19 03:50:09', '0000-00-00 00:00:00', '2019-09-25 16:15:31', 'unchecked', 'n', 'n', '', '1', 'INHESC2019091901\r\n/EXJ02/合同评审', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'Nyamezela Metering (Pty) Ltd\r\n', 'INHESC2019091901', 'EXJ', 'EXJ02', '44850', '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '李忠鹏', '2019-09-19', '空运或者海运，客户指定货代', '客户承担', '江西工厂', '江西工厂', '请工厂和业务确认', '银河标准', 'I100,I200', '02', '', '变更后新增 40台BS安装三相四线一体式可更换通讯模块智能电表，带三相GPRS通讯模块\r\n和5台BOX300中电流表箱，均使用现有库存出货，无需再生产\r\n无其他变更', '', '', '2045', '44850', '0', '{391A84AB9C8F486D8C231A9DEDE77690D4CC22B6C7B643389146528155CECD45}_EXJ02销售合同变更20191219.docx', '货物将在卖方收到买方T/T支付的合同全款后45天内，从卖方工厂发出。\r\n', '', '', '合同评审', '02', 'FOB Shenzhen', '上述货物将在卖方收到买方T/T支付的合同全款后45天内，从卖方工厂发出。', '18个月', '否', '否', '否', '本合同项下的货款将采用美元支付，付款方式如下：每批次在发货前100% T/T付款。', '不含', '05', '01', '', '02', '', '01', '01', 'EXJ报价申请', 'N.A', 'N.A', '02', '', '', '', '', null, null);
