INSERT INTO `crs_tabledata696` VALUES ('788', '{224A0A32-C508-4747-B17A-B96476234309}', '75', 'INHE-0432', '2019-09-27 15:17:19', '0000-00-00 00:00:00', '2019-09-29 16:27:04', 'unchecked', 'n', 'n', '', '1', 'INHESC201092701/KLA/合同评审', '', 'The Kenya Power * Lighting Company Limited', 'INHEMETER AFRICA COMPANY LIMITED', 'INHESC2019092701', 'KLA', 'KLA', '2389000', 'INHEMETER AFRICA', '谭东羊(Timon)', '谭东羊', '2019-09-27', '1.KLA第一批大货：5000台空运；45000台海运；\r\n2.KLA合同数量变更为5万台（第一批大货）；另外5万台由于价格不一致，将单独销售合同评审流程。\r\n\r\n', '卖方', '买方仓库', '中国任意港口', '按照标书要求', '', 'i100', '02', '无', 'KLA立项时对应的客户名称为KPLC，但实质上，此为IAC与深圳银河的合同；KPLC与IAC的合同目前还没拿到，电力公司还在评标中。', '', '', '50000', '2389000', '0', '{4B072D50CFE74E31859BF822ABC74B40D4CC22B6C7B643389146528155CECD45}_1. KLA销售合同INHE和IAC20190926-5000PCS-空运.docx', '现在还没有和客户签合同，需要等确认项目落地后，与电力公司最终签订合同，根据电力公司给的交期交货。', '{4B072D50CFE74E31859BF822ABC74B409E19E8E731434A848B97C6F1C79E3A54}_3.KLA-01 5000台合同扫描版（未签字）20200118.pdf', '{4B072D50CFE74E31859BF822ABC74B40BA0F4BB9344A4053BE173BB06528647F}_2. KLA销售合同INHE和IAC20190926-45000PCS-海运.docx', '合同评审', '02', 'DDP(买方仓库)(含增值税)', '在合同签订日期后50天内，从卖方工厂发出（此为深圳银河与IAC的合同条款；实际发货时间，依据电力公司最终的合同和交期）', '卖方所提供货物的保修期为从卖方工厂发货之日起12个月（此为深圳银河与IAC的合同条款；IAC与KPLC的质保期为“满意交付后54个月或者发货后60个月，期效晚者为准”）', '是', '依据实际情况', '否', '每批发货的货值在提单日后120天采用T/T全款支付', '包含，DDP(买方仓库)(含增值税)单价为50.42USD，其中江西工厂至IAC仓库运费为0.89USD，保费为0.03USD/只表。注：实际最新的运保费待跟单组给出，目前只是参考KF03的。', '05', '03', 'KF03', '02', '', '02', '02', '技术规格同KF03一致。', '需要', 'FOB单价USD38.24，佣金为7.95% FOB，即USD3.04/只表', '02', '', '03', '★★★★', '', null, null);
