INSERT INTO `crs_tabledata696` VALUES ('802', '{C68FBCF0-835B-4A97-B9CF-42FAC2C2E33D}', '143', 'INHE-0773', '2019-11-11 09:26:13', '0000-00-00 00:00:00', '2019-11-14 16:25:05', 'unchecked', 'n', 'n', '', '1', 'INHESC2019110103/EOI48/合同评审', '', 'Finmark Industries (Pvt) Ltd.', 'PARAMOUNT CABLES PRIVATE LIMITED', 'INHESC2019110103', 'EOI', 'EOI48', '8093', '竞标组', '林丹敏', '李忠鹏', '2019-11-11', '空运', '银河承担从工厂至DHL深圳仓库的运输费用，买方承担余下运至哈拉雷机场的运费和保费。', '买方指定的DHL深圳仓库', '江西工厂', '按照EOI项目标准要求', '按照EOI项目标准要求', 'DTZ1513', '01', '', '全款水单已收到，待走完流程后，安排发货。', '', '', '77', '8093', '0', '{C68FBCF0835B4A97B9CF42FAC2C2E33D3E3FD1A05260451F8D948358003231C8}_Inhemeter Sales Contract INHESC2019110103.pdf', '2019.11.15', '', '', '合同评审', '03', 'FCA，深圳', '货物将在卖方收到买方T/T支付的合同全款后5天内，从卖方工厂发出。', '从卖方工厂发货之日起24个月。', '否', '否', '否', '欧元支付；合同金额的100%在签订合同后作为预付款在发货前30天内T/T支付。', '是，单价包含国内运输及杂费。', '05', '01', '详见OA“EOI01报价审批”', '02', '', '02', '01', '', '否', '无', '02', '', '', '', '', null, null);
INSERT INTO `crs_tabledata696` VALUES ('803', '{1689813E-DC13-4B35-A675-C8560CD1A224}', '61', 'INHE-0578', '2019-11-11 17:35:28', '0000-00-00 00:00:00', '2019-11-14 17:18:56', 'unchecked', 'n', 'n', '', '1', 'INHESC2019111101/ZWS01/合同评审', '', 'Finmark Industries (Pvt) Ltd.', 'Zimbabwe Electricity Transmission & Distribution Company (Private) Limited.', 'INHESC2019111101', 'ZWS', 'ZWS01', '930090.4', '国际二部 INTL.Business Dept.2', '覃湘君(June)', '李忠鹏', '2019-11-11', '海陆联运', '银河承担', 'CIP 哈拉雷电力公司仓库', '江西工厂', '按照ZWS项目包装要求', '按照ZWS项目验货标准', 'DDZ1513，DTZ1513', '01', '产品技术按照ZWS项目（中标项目）技术合同评审申请OA中确认为准，业务反馈为EOI翻单，具体生产时与业务确认。', '1.ZWS项目在2018年8月20日走过一次商务部分合同评审流程、但未执行；本次是根据执行情况走的合同评审流程，ZWS01订单以此流程为准；\r\r\r\r\r\n2.此前ZWS项目以电力公司标准合同模板签订合同，现下按照业务反馈与要求按照银河标准合同模板执行（质保、违约金等等均以银河合同模板为准）；\r\r\r\r\r\n3.发货条件中日期写为2019年12月25日，是为了赶在2019年底之前发货ZWS01订单；ZETDC开出的LC显示最后装船期为2020年1月31日；\r\r\r\r\r\n4.根据目前情况，合同附件仅包含“Bank Account Declaration” &　“Technical Configuration Sheet”；附件1收款银行显示为【中国银行】，附件2技术支持整理中，以相关OA终版审核为准。\r\r\r\n5.ZWS01的报价已经过公司审核、佣金已经过公司审核；信用证在OA“ZWS中标合同信用证开立和审核（电力公司直接开立信用证）”中已经过评审。', '', '', '9480', '930090.4', '0', '{F9068074762C44C09918F91A4309EBE4D4CC22B6C7B643389146528155CECD45}_ZWS01合同+ZWS01三款表技术规格书.pdf', '上述货物将在卖方收到覆盖 100%合同金额的不可撤销的保兑的远期 60 天的信用证款后 60 天内从卖方工厂发出；前提是信用证条款须被合同双方接受。【与信用证不冲突】\r\n', '{F9068074762C44C09918F91A4309EBE49E19E8E731434A848B97C6F1C79E3A54}_ZWS01合同+ZWS01三款表技术规格书（客户回签）.pdf', '', '合同评审', '03', 'CIP 哈拉雷，津巴布韦', '上述货物将在卖方收到覆盖100%合同金额的不可撤销的保兑的远期60天的信用证款后在2019年12月25日之前从卖方工厂发出；前提是信用证条款须被合同双方接受。', '按照银河标准合同执行：发货之日起12个月。', '否', '否', '否（当前按照银河标准合同执行则不涉及到违约金/罚金）', '合同金额的100%通过不可撤销的保兑的远期60天的信用证支付', '1. DIN导轨单相表，海运运保费2美金每台；2. BS单相表，海运运保费2.2美金每台；3. BS三相表，海运运保费3.2美金每台。以上为跟单组复核2018年ZWS合同评审运费报价，确认OK。', '01', '01', '', '02', '', '01', '01', 'ZWS项目（中标项目）技术合同评审申请', '是', '详情参考李忠鹏最新报批公司ZWS项目佣金计算OA。', '02', '', '', '', '', null, null);
