INSERT INTO `crs_tabledata696` VALUES ('815', '{8F6990F2-43EB-4F66-B4FB-7C4777C0D093}', '66', 'INHE-0634', '2019-12-11 13:40:27', '0000-00-00 00:00:00', '2019-12-13 11:50:49', 'unchecked', 'n', 'n', '', '1', 'INHESC2019120901/URV01/合同评审', '', 'Sipromad Group Company Limited', 'Global Technologies', 'INHESC2019120901', 'URV', 'URV01', '134937.492', '国际三部 INTL.Business Dept.3', '陈雁', '陈雁', '2019-12-11', '海运；运费相应变更', '银河', '马达加斯加Ivatok机场', '中国', '确保货物不在运输中被损坏即可', '符合标书要求即可', 'i6310T', '02', '', '（1）合同按照344台签订，上调344台的FOB单价，使其总价与原合同350台的总价一致；（2）另外6台作为样机快递发运，FOB费用已经在前述344台中支付，客户另外TT支付快递费，不报关，不用签订6台的合同。详见附件黄色高亮处。', '', '', '0', '0', '0', '{1597C4B9754244469794BD03D85E842FD4CC22B6C7B643389146528155CECD45}_URV01 掌机合同  上调344台掌机单价.doc', '2020年2月28日', '', '', '合同评审', '02', 'CIP Ivato机场，马达加斯加', '上述货物将在卖方收到T/T支付的合同金额的30%作为预付款及覆盖70%合同金额的不可撤销的保兑的即期的信用证后60天内，从卖方工厂发出；前提是信用证条款须被合同双方接受。', '1年', '否', '否', '否', '合同金额的30%在签订合同10天之内作为预付款T/T支付，70%余款通过不可撤销的保兑信用证支付。信用证应当在合同签订之后15天内被卖方收到，且在卖方工厂启动原材料备料前信用证的条款应当取得卖方的认可。', '否，运保费单独栏目收取，合计823美元', '03', '01', '', '02', '', '01', '01', 'URV项目解析申请', '否', '无', '02', '', '01', '★★', '', null, null);
INSERT INTO `crs_tabledata696` VALUES ('816', '{71AA3C0D-1F91-4110-A1CD-B12B0C571E4B}', '66', 'INHE-0634', '2019-12-12 08:36:28', '0000-00-00 00:00:00', '2019-12-16 16:39:51', 'unchecked', 'n', 'n', '', '1', 'INHESC2019121101/URV02/合同评审', '', 'Sipromad Group Company Limited', 'Global Technologies', 'INHESC2019121101', 'URV', 'URV02', '94000', '国际三部 INTL.Business Dept.3', '陈雁', '陈雁', '2019-12-12', '无运输方式', '无运费', '马达加斯加', '深圳软件部', '无特殊要求', '按照标书要求', '', '', '', '与电力局ERP Oracle JDEDWARDS Enterprise One System做兼容。', '', '', '0', '0', '94000', '{8AC929E4E2EC431AB21691D36D872186D4CC22B6C7B643389146528155CECD45}_CONTRAT INHEMETER SOFTWARE SIGN BY GT.PDF', '2020年2月28日', '{8AC929E4E2EC431AB21691D36D8721869E19E8E731434A848B97C6F1C79E3A54}_合同附件.zip', '', '合同评审', '02', '无', 'INHEMETER应于合同生效并收到GT预付款后60个工作日内将软件送达GT指定地点或区域。', '1年', '否', '否', '否', '-45％合同总值在签订合同后的10天内以电汇方式作为预付款支付；-45%合同总值在INHEMETER派遣兼容和培训团队到马达加斯加之前T/T支付；-10%余款在INHEMETER完成兼容和培训服务后T / T支付。只有支付完100％合同总值以后，INHEMETER才提供质保和维护服务。', '否', '03', '01', '', '02', '', '01', '01', 'URV项目解析申请', '否', '无', '02', '', '01', '★★', '{71AA3C0D1F914110A1CDB12B0C571E4B4654CAE914AA4B25B6892952453EBAEB}_URV软件服务销售合同.docx', null, null);
