INSERT INTO `crs_tabledata696` VALUES ('833', '{A7457F38-AA52-4753-A455-73644C7AE4AC}', '61', 'INHE-0916', '2020-01-16 09:46:23', '0000-00-00 00:00:00', '2020-01-17 14:13:18', 'unchecked', 'n', 'n', '', '1', 'INHESC2020011602/EOI52/合同评审', '', 'Finmark Industries (Pvt) Ltd.', 'ALVESTONE ESTATES PRIVATE LI', 'INHESC2020011602', 'EOI', 'EOI52', '44930', '国际二部 INTL.Business Dept.2', '赖星威', '李忠鹏', '2020-01-16', '空运', '客户承担运保费', '哈拉雷国际机场', '中国任意机场', '按照EOI项目标准', '按照EOI项目标准', 'DDZ1513/DTZ1513', '01', '用EOI现有库存出货。请领导尽快审批合同评审，入账后立即发货', '1. 本项目合同相对方为ALVESTONE ESTATES PRIVATE LI，与付款水单名称一致。实际收货方为Mining and Industrial Suppliers (Pvt) Ltd，已在合同中约定。请领导同意。 \r\n2. 本项目使用EOI现有DIN导轨表库存。', '', '', '563', '39335', '5595', '{A7457F38AA524753A45573644C7AE4AC3E3FD1A05260451F8D948358003231C8}_Sales Contract for Alveston Estate INHESC2020011602.docx', '2020/1/18', '', '', '合同评审', '03', 'CIP，哈拉雷国际机场', '货物将在卖方收到买方T/T支付的合同全款后30天内，从卖方工厂发出。', '保修期为从卖方工厂发货之日起24个月。', '否', '否', '否', '合同金额的100%在签订合同30天内作为预付款在发货前T/T支付。', '否', '05', '01', '', '02', '', '02', '01', 'EOI和ZWS项目技术规格解析', '否', '否', '02', '', '', '', '', null, null);
INSERT INTO `crs_tabledata696` VALUES ('834', '{36FC98C6-0DDC-4E24-BE7B-A35D71A69791}', '61', 'INHE-0654', '2020-02-04 13:24:37', '0000-00-00 00:00:00', '2020-02-06 09:38:45', 'unchecked', 'n', 'n', '', '1', 'INHESC2020011401/ADC-04/合同评审', '', 'Cashpower Sudamericana S.A.', 'Cashpower Sudamericana S.A.', 'INHESC2020020401', 'ADC', 'ADC-04', '106635', '国际二部 INTL.Business Dept.2', '李明(Ming)', '李明,胡云义', '2020-02-04', '海运', '买方', '深圳港口', '江西工业园', '公司标准', '符合IEC标准', 'DDZ1513,DDZ1513 DIN,DTZ1513,i310,IHM-4000(该市场按照固定的产品型号，不参照新命名）', '02', '无', '1.单相表的技术规格此前是按照客户部给的规格，客户有针对几点修改了一下；三相表和CT表技术规格在整理中，基本按照公司此前出的样机规格一致。2.付款方式：阿根廷ADD的客户，ADC的采购主要是作为给周边小型电力公司演示，推广测试，试点等使用，固种类比较多，此前中信保申请到给代理公司的额度是20万美金，便于资金周转，此次尾款的70%需要采用中信保投保。3.其他无特殊，请领导申请合同，预付款预估应在当地时间周五之前收到。', '', '', '2245', '71150', '0', '{2113400D11CF4C21B283AFEB2981F1F3D4CC22B6C7B643389146528155CECD45}_Sales_Contract_20200710.docx', '2020-03-10', '', '', '合同评审', '02', 'FOB', '本合同项下货物将在卖方收到买方预付款USD 31,557后60天内从卖方工厂发出。', '发货起12个月', '是', '是', '否', '本合同项下的货款将采用美金支付，付款方式如下：合同金额30% USD 31,557在签订合同10天内作为预付款T/T支付，70%余款USD 73,633在发货90天内通过T/T支付。余款USD 73,633将采用Sinosure投保,买方应及时支付卖方的所有货款及本条款提及的费用。', '否', '02', '01', '', '02', '', '01', '01', '', '否', '否', '02', '否', '', '', '', null, null);
INSERT INTO `crs_tabledata696` VALUES ('835', '{CB1CF4E3-5898-4504-ACE3-A16A1715C3F6}', '144', 'INHE-0771', '2020-01-17 09:00:48', '0000-00-00 00:00:00', '2020-02-04 09:47:50', 'unchecked', 'n', 'n', '', '1', '19000235 YS\r\n/MSQ02\r\n/合同评审', '', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'ERANOVE SA', '2020/JPT/002 - 20000004AP', 'MSQ', 'MSQ02\r\r\n', '70000', '投标组', '吴艳', '郑超波', '2020-01-17', '无\r\r\n', '无\r\n', '科特迪瓦\r\n', '深圳', '无\r\n		\r\n', '无\r\n		\r\n', '无（系统高可用性方案）', '02', '无', '无。CDN现场系统高可用性方案部署第二阶段，目前还未开始实施。支付方式，业务郑超波选择\r\r\r\r\n2.在项目的第2阶段结束时\r\r\r\r\r，部署报告和员工培训的完成后，将对总额的100%开具发票\r\r\r\r\r\r。\r\r\n\r\r		', '', '', '0', '0', '0', '{CB1CF4E358984504ACE3A16A1715C3F63E3FD1A05260451F8D948358003231C8}_MSQ02高可用方案第二阶段PO 翻译.docx', '将与CIE协议确定', '{CB1CF4E358984504ACE3A16A1715C3F67719915B5AFB4CFC8E75112B161686FE}_Fature Proforma v20191121.pdf', '', '合同评审', '02', 'FOB', '无', '1年', '是', '否', '逾期1天需将扣除订单总额的不含税总额的0.4%，该款项每天不低于100欧元。并赔偿采购方所有由于其失误造成的财务损失。', '1.或者，收到Eranove订单后>	总额的50% 将根据交付的银行保函 (由提供者提供的预付款保函) 开具发票, 及剩下部分>	在项目第二阶段结束时，根据部署报告和员工培训的完成，将对总额的50％\r\n开具发票。\r\n2.或者，在项目的第2阶段结束时>	部署报告和员工培训的完成后，将对总额的100%开具发票。\r\n预付款发票将在收到银行保函（由提供者提供的预付款保函）后通过银行转账支付余款发票将在出具45天后通过银行转帐支付。', '无', '02', '01', '', '02', '', '02', '02', '', '是', '需要支付佣金', '02', '', '', '', '{CB1CF4E358984504ACE3A16A1715C3F64654CAE914AA4B25B6892952453EBAEB}_Bon_Cde__ERANOVE_INHEMETER_-_Evolution_Archi_Haute_Dispo.pdf', null, null);
