INSERT INTO `crs_tabledata696` VALUES ('854', '{95C381A5-2BC1-48E4-8A78-A4C9CD689CD2}', '60', 'INHE-0560', '2020-03-05 08:55:00', '0000-00-00 00:00:00', '2020-03-17 10:34:53', 'unchecked', 'n', 'n', '', '1', 'E20_0403_D/白雪201/合同评审', '', 'Energomera CJSC', 'Energomera CJSC', 'E20_0403_D', '白雪', '白雪201', '4179.15', '国际一部 INTL.Business Dept.1', '李美娇', '邱洁,李美娇', '2020-03-05', '空运', '客户', '深圳', '深圳', '按空运运输标准运输', '按公司验收标准验收', '2900个 APC220-43                             750个 APC220-43-3', '02', '无', '因客观原因及设备条件限制，白雪客户无法在当地对其已经采购回去的3650个模块进行软件刷新升级服务。经多方确认及与客户协商，最终选择采用我司先从客户处进口该批模块，完成内部软件刷新服务后再出口给客户的方式协助客户完成刷新服务。此订单为我司再出口时的销售合同，对此订单补充说明如下：                                                    1、该订单模块货物从客户处进口，进口所产生的增值税，由客户承担（金额已补偿到此合同中）。我司不需备料生产，只需与客户签订进口合同，完成进口流程。                                                           2、模块刷新服务的费用+客户补偿的增值税全部均摊到模块单价中（为适应合同法规要求）                            3、开始刷新服务前，客户支付4179.5USD（模块升级服务费+补偿进口增值税）；发货前，客户支付24455USD（模块货款）	                                                                             4、我司在收到客户支付的24455USD模块货款后，再履行向其进口时的付款义务。	\r\r\r\n', '', '', '0', '0', '4179.15', '{C5A9393BD58341FB929EE79F9E198A6CD4CC22B6C7B643389146528155CECD45}_白雪201-20200708.PDF', '2020.4.10', '', '', '合同评审', '02', 'FCA深圳', '款到发货', '6年', '否', '否', '否', '4179.5USD（模块升级服务费+补偿进口增值税）-下单前TT支付  24455USD（货物从客户处进口，不需我司生产）-发货前TT支付', '否', '02', '02', '白雪905', '02', '', '01', '01', '', '否', '否', '02', '', '', '', '', '银河电力', '60');
