INSERT INTO `crs_tabledata696` VALUES ('861', '{DA5813DF-CA37-462F-AEE6-5CC8C6DC8071}', '61', 'INHE-0500', '2020-03-17 10:27:18', '0000-00-00 00:00:00', '2020-03-23 13:43:26', 'unchecked', 'n', 'n', '', '1', 'INHESC2020031901/EXJ09/合同评审', '', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'Nyamezela Metering PTY Ltd.', 'INHESC2020031901', 'EXJ', 'EXJ09', '6130', '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '李忠鹏', '2020-03-17', '空运，代理指定货代', '客户承担', '江西工厂提货', '江西工厂	\r\r\n', 'CDE项目包装，直接出货', 'CDE项目标准', 'I310', '01', '', 'EXJ09订单变更后为：\r\n\r\n30台BS三相四线直接接入式可更换通讯模块智能电表，带三相GPRS通讯模块\r\n18台BS安装三相四线直接接入式分体式（PLC通讯）智能电表\r\n1台BOX300中电流表箱\r\n6台CT/PT接入式可更换通讯模块多功能智能电表，带三相GPRS通讯模块\r\n\r\n其他合同条款保持不变。\r\n', '', '', '55', '6130', '0', '{16A259B32C88451CAC544CE8A179FD1BD4CC22B6C7B643389146528155CECD45}_EXJ09销售合同20200317.docx', '收到买方T/T支付的合同全款后10天内，从卖方工厂发出。\r\n', '', '', '合同评审', '02', 'EWX九江', '上述货物将在卖方收到买方T/T支付的合同全款后10天内，从卖方工厂发出。', '18个月', '否', '否', '否', '在生产前100% T/T付款。', '不含', '05', '01', '', '02', '', '02', '01', 'EXJ报价申请', 'N/A', 'N/A', '02', '', '', '', '', '银河电力', '61');
INSERT INTO `crs_tabledata696` VALUES ('862', '{BBDB1DBE-7C20-4028-91DD-5EF92A400DF7}', '61', 'INHE-0916', '2020-03-18 09:02:11', '0000-00-00 00:00:00', '2020-03-19 11:22:51', 'unchecked', 'n', 'n', '', '1', 'INHESC2020031701/EOI61/合同评审', '', 'Finmark Industries (Pvt) Ltd.', 'Friserv Investments (Private) Limited', 'INHESC2020031701', 'EOI', 'EOI61', '8097', '国际二部 INTL.Business Dept.2', '赖星威', '李忠鹏', '2020-03-18', '空运		\r\n		\r\n', '客户承担运保费		\r\n		\r\n', '哈拉雷国际机场		\r\n		\r\n', '中国任意机场		\r\n		\r\n', '按照EOI项目标准		\r\n		\r\n', '按照EOI项目标准		\r\n		\r\n', 'DDZ1513/DTZ1513		\r\n		\r\n', '01', '', '1. 该订单的实际支付方为 NKOSIKHONA NDLOVU，其为Friserv Investments (Private) Limited的股东。因客户不希望付款方的名称显示在合同上，根据公司要求，业务让客户签署了“委托第三方支付确认函”和“受托支付确认函”，现已通过OA发给了财务。\r\r\r\r\r\r\r\r\n2. 全款已到账\r\r\r\r\r\r\r\r\n3. 用EOI现有库存发货，请公司审批后尽快入账，以尽早安排发货\r\r\r\r\r\r\r\n4. 受全球新冠疫情影响，国际航班班次大幅减少且空运费暴涨，该订单空运费不足以支付实际运输费用，差额约为390美金。根据OA“EOI61,EOI63运费差额由银河承担申请”，公司已经审批通过让银河承担该差额。\r\n5. 报价在流程简化前，由谌总审批通过，详见OA“EOI01项目报价审批”', '', '', '112', '7016', '1081', '', '', '{BBDB1DBE7C20402891DD5EF92A400DF77719915B5AFB4CFC8E75112B161686FE}_Sales Contact for Friserv Investments (Private) Limited 20200317.pdf', '', '合同评审', '02', 'CIP，哈拉雷国际机场', '货物将在卖方收到买方T/T支付的合同全款后30天内，从卖方工厂发出。', '保修期为从卖方工厂发货之日起24个月。', '否', '否', '否', '合同金额的100%在签订合同30天内作为预付款在发货前T/T支付。', '否', '05', '01', '', '01', '{BBDB1DBE7C20402891DD5EF92A400DF7EA23E848092D41CC83988AEE534D6267}_第三方协议.7z', '02', '01', 'EOI和ZWS项目技术规格解析', '否', '否', '02', '', '', '', '', '银河电力', '61');
INSERT INTO `crs_tabledata696` VALUES ('863', '{BDD331E0-655F-4507-841D-B2E7E5EBF408}', '61', 'INHE-0725', '2020-03-18 18:02:20', '0000-00-00 00:00:00', '2020-03-20 15:48:52', 'unchecked', 'n', 'n', '', '1', 'INHESC2020022601/GA08/合同评审', 'GA08合同在OA【GA08项目软件合同评审及软件销售疑点澄清】中已通过合同评审（2020-03-12 15:15:11），但后来客户仍对合同两处有疑问，业务洽谈后已在合同中修改（黄色部分）合同中的软硬件表述是为客户定义，内部合同评审中已应黄总要求将掌机算作软件。', 'GVE Projects Limited', 'GVE Projects Limited', 'INHESC2020022601', 'GA', 'GA08', '94600', '国际二部 INTL.Business Dept.2', '赵政洁(Oscar)', '赵政洁', '2020-03-18', '软件压缩包发送，掌机快递邮寄', '买方', '中国深圳', '中国深圳', '无特殊要求，掌机快递时注意包裹在牢固的纸箱中防止颠簸', '银河标准', 'SmartAMI, SmartMessenger, SmartAgent, i6300', '01', '软件有库存，掌机需要重新生产，但客户计划先部署软件，对掌机未要求交货时间', '', '', '', '0', '0', '0', '', '3月31日', '{BDD331E0655F4507841DB2E7E5EBF4087719915B5AFB4CFC8E75112B161686FE}_Annex 1 服务水平协议_20200311.pdf', '{BDD331E0655F4507841DB2E7E5EBF4087842EE48FE5340F2BE4CBD5E93168F23}_Annex 2 GA08 软件功能列表.pdf', '合同评审', '02', 'EXW Shenzhen, China', '合同签订并收到预付款后通过压缩包发送软件，掌机交期客户并未要求（客户计划先部署软件）', '在软件完成验收后客户自行负责，软件出问题我方协助解决', '否', '否', '否', '1. 软件+远程协助服务：60%TT预付款在合同签订10天内支付，40%TT尾款在软件完成验收后五天内支付；2. 现场技术支持：单价1000美金/天，每次至少五天，在工程师出发五天前100%TT预付\r\n3.为推进合作，快速部署系统执行订单，业务建议掌机仍按照60%预付+40%尾款的模式支付。原因如下：\r\n1). 此前客户坚持40%预付款+60%尾款，经洽谈，客户做出让步，调整为60%预付款，40%尾款；同时在合同条款洽谈也做出了极大让步\r\n2). 合同60%预付款共计56760美金，掌机总金额仅为9600美金，可以Cover掌机成本.\r\n', '不含', '05', '01', '', '02', '', '01', '02', '', '否', '无', '02', '', '', '', '{BDD331E0655F4507841DB2E7E5EBF4084654CAE914AA4B25B6892952453EBAEB}_GA08 Sales Contract_20200318.pdf', '银河电力', '61');
INSERT INTO `crs_tabledata696` VALUES ('864', '{F6715212-384E-46E4-861F-2B5CF4F47656}', '61', 'INHE-0772', '2020-03-20 09:25:59', '0000-00-00 00:00:00', '2020-03-23 14:15:36', 'unchecked', 'n', 'n', '', '1', 'INHESC2020021901/MLD01/合同评审', '原MLD流程数据错误修改不了，郭主管在后台直接删除，现在重新提交，流程重走', 'Amadou Baiba KOUMA', 'Société IYA', 'INHESC2020021901', 'MLD', 'MLD01', '190000', '国际二部 INTL.Business Dept.2', '张子琦(Miranda)', '张子琦', '2020-03-20', '海运', '买家', '江西', '江西', '银河默认包装', '银河标准', 'i200（TTA去掉RF模块）', '01', '', '技术：欠压门限为138V', 'MLD合同评审流程后台数据错误删重新走。修改内容：1. 合同相对方； 2.部分是第三方付款。3. 交货条件已修改为：生产完成10天后且收到余款全额发货\r 4.合同附件增加：第三方支付委托文件\r\r\n ', '发货条件变更：生产完成10天后且收到余款全额发货。3. 第三方付款的委托函，确认函\"', '10000', '190000', '0', '{F6715212384E46E4861F2B5CF4F476563E3FD1A05260451F8D948358003231C8}_IYA Sales contract 20200312.docx', '60天', '', '', '合同评审', '02', 'FOB JIUJIANG CHINA', '生产完成10天后且收到余款全额发货', '12个月', '否', '否', '否', '合同金额的50%在签订合同10天内作为预付款T/T支付，50%余款在发货前T/T支付', '运费包含到九江港口', '05', '02', 'MLO的BS安装单相表样机技术规格', '01', '{F6715212384E46E4861F2B5CF4F47656EA23E848092D41CC83988AEE534D6267}_SHIVI 营业执照.jpg', '02', '01', 'MLO', '否', '否', '02', '', '01', '★★', '', '银河电力', '61');
INSERT INTO `crs_tabledata696` VALUES ('865', '{03DC138E-F1B5-47C8-BF02-87750949C212}', '61', 'INHE-0916', '2020-03-30 13:38:52', '0000-00-00 00:00:00', '2020-04-07 09:07:05', 'unchecked', 'n', 'n', '', '1', 'INHESC2020032301 /EOI63/合同评审', 'June已审核，请知悉', 'Finmark Industries (Pvt) Ltd.', 'SATAF PVT LTD', 'INHESC2020032301', 'EOI', 'EOI63', '6886', '国际二部 INTL.Business Dept.2', '赖星威', '李忠鹏', '2020-03-30', '空运\r\r\n', '客户承担运保费		\r\n		\r\n		\r\n', '哈拉雷国际机场		\r\n		', '中国任意机场		\r\n		\r\n		\r\n', '按照EOI项目标准		\r\n		\r\n		\r\n', '按照EOI项目标准		\r\n		\r\n		\r\n', '', '', '', '1. 全款已经到账。\r\r\r\r\r\r\r\r\n\r\r\r2. 用EOI现有库存出货。\r\r\r\r\r\n3. 报价高于谌总的基准报价，已经过公司审批\r\r。\r\r\r\n4. 运保费不足，根据OA\"EOI61,EOI63运费差额由银河承担申请\"，运费差额由公司承担				\r\r\r\r\r\r\r\r\n', '', '', '105', '5915', '971', '{03DC138EF1B547C8BF0287750949C2123E3FD1A05260451F8D948358003231C8}_Sales Contact for Sataf 20200323 (2).pdf', '', '', '', '合同评审', '02', 'CIP，哈拉雷国际机场', '货物将在卖方收到买方T/T支付的合同全款后10天内，从卖方工厂发出。', '保修期为从卖方工厂发货之日起24个月。', '否', '否', '否', '合同金额的100%在签订合同30天内作为预付款在发货前T/T支付。', '否', '05', '01', '', '02', '', '02', '01', 'EOI和ZWS项目技术规格解析', '否', '否', '02', '', '', '', '', '银河电力', '61');
INSERT INTO `crs_tabledata696` VALUES ('866', '{29BD3A2D-48FA-417A-ACBD-12DAE9D1A4BE}', '60', 'INHE-0066', '2020-03-30 16:10:02', '0000-00-00 00:00:00', '2020-03-31 17:39:40', 'unchecked', 'n', 'n', '', '1', 'INHESC2020033001/白云811/合同评审', '', '\"Aspan-Energy \" LTD', '\"Aspan-Energy \" LTD', 'INHESC2020033001', '白云', '白云811', '70000', '国际一部 INTL.Business Dept.1', '邱洁', '邱洁', '2020-03-30', '陆运', '客户', '深圳', '深圳', '按国际陆运运输标准', '按公司验收标准', '集中器', '02', '翻单', '无', '', '', '0', '0', '70000', '{29BD3A2D48FA417AACBD12DAE9D1A4BE3E3FD1A05260451F8D948358003231C8}_白云811合同-100шт.концентраторов-INHESC2020033001.doc', '2020年04月15日', '', '', '合同评审', '02', 'FCA深圳', '款到发货', '3年', '否', '否', '否', '50%T/T-预付款，50%T/T-发货前支付。', '否', '02', '02', '白云803', '02', '', '02', '02', '', '否', '无', '02', '', '', '', '', '银河电力', '60');
INSERT INTO `crs_tabledata696` VALUES ('867', '{FF863F54-150A-4F40-ABCA-736F5FCE04B6}', '153', 'INHE-0535', '2020-04-07 14:16:41', '0000-00-00 00:00:00', '2020-05-11 17:11:54', 'unchecked', 'n', 'n', '', '1', 'INHESC2020040701\r\n/JPM01/合同评审', 'JPM01', 'JAY AUTOCOMPONENTS LIMITED', 'JPM Industries Limited', 'INHESC2020040701', 'JPM', 'JPM01', '3873531', '重大项目部', '左亚楠', '王维,左亚楠', '2020-04-20', '合同项下的第一批和第二批货物的运输方式为空运。\r\n合同项下的第三批及以后的货物的运输方式为海运。\r\n', '空运费和保险费由买方承担，使用买方指定的中国和印度货代。\r\r\r\n海运费和保险费由卖方承担，包含在CIF孟买报价中。\r\r\r\n', '第一批和第二批空运交货地目的机场为印度英迪拉甘地国际机场。\r\r\n合同项下的第三批及以后的货物海运交货地目的港为孟买Nhava Sheva港口。', '深圳', '货物应该包装在牢固的纸箱里，方便海运或空运。\r\r\n', 'IS16444,IS15959标准', 'DDZ1513#FE54`DTZ1513', '01', '符合IS16444,IS15959标准', '', '', '', '200630', '3873531', '0', '{AD913FC4BF7045B1B922932EBAFAF409D4CC22B6C7B643389146528155CECD45}_PO of JPM01-4.PDF', '按批次', '', '', '合同评审', '02', '第一批和第二批为FCA深圳，第三批和第四批为CIF孟买', '1.第一批50台单相表和10台三相表整表货物应在本合同签订并按照条款5.2约定完成收款后立即从卖方工厂装运。2.第二批540单相表和30台三相表的整表将在收到TT全款后30-45天内空运发出。3.第三批SKD将分成不同批次装运，实际数量计划将根据客户要求在单独的订单/月度采购订单中确认。每批货物将在收到5.4条款要求的信用证后30-45天内从卖方工厂发出。4.第四批CKD将分成不同批次装运，实际数量计划将根据客户要求在单独的订单/月度采购订单中确认。每批货物将在收到5.4条款要求的信用证后30-45天内从卖方工厂发出。CKD的供货范围将在生产启动前由双方共同确认。', '1.卖方仅向买方承担供货义务，不对任何第三方负责。买方不得将其与任何第三方的合同义务转让给卖方。2.本合同 Batch 1 和 Batch 2货物的质量保证期为自装运之日起66个月。3.对于本合同Batch 3和Batch 4中卖方以SKD和CKD形式供应的货物，卖方将全面负责产品在测试、安装或使用过程中观察到的设计缺陷，并承担与此相关的缺陷整改费用。如果发现任何与产品设计有关的缺陷，除了用当前技术不可预见或无法察觉的缺陷外，INHEMETER将立即提供解决方案，而且不需要买方支付额外费用。此外，在零件进料质量检查中观察到的任何质量问题，如果是卖方的责任，卖方也将负责维修和/或更换。4.卖方将随每批货物免费提供0.5%的备品，用于维修和更换由于卖方设计原因引起的损坏，备件的使用应得到卖方的授权和批准。如果是由于买方生产制造原因引起的损坏，则买方应对此类损坏负责。5.卖方不对买方因本合同项下商品损坏而直接或间接遭受的任何损失负责。', '否', '否', '友好协商。', '1.第一批和第二批货款在合同签署及数量确认后7天内以T/T支付。2.第三批和第四批将采用不可撤销的远期120天保兑信用证支付。每批次的信用证应在启动原材料备料之前通知到卖方银行且信用证的条款应当获得卖方的认可。每批次的信用证将与对应的采购订单一起提供。3.买方已支付的15万美元合作保证金可从本合同下最后一批货物的付款中扣除。', '海运方式下单价中包含保费和运费，分别约为$0.03和$0.07。', '05', '01', '请参考OA“JPM产品报价”', '02', '', '01', '02', '可参考OA\"JPM项目\"研发技术支持', '否', '否', '02', '', '', '', '', '银河电力', '153');
INSERT INTO `crs_tabledata696` VALUES ('868', '{4A4CD108-0684-4469-928C-E6FA3A3BD1EE}', '143', 'INHE-0773', '2020-04-07 19:33:31', '0000-00-00 00:00:00', '2020-05-11 17:08:15', 'unchecked', 'n', 'n', '', '1', 'INHESC2020040702\r\n/ZWS02/合同评审', '', 'Finmark Industries (Pvt) Ltd.', 'Zimbabwe Electricity Transmission & Distribution Company (Private) Limited.', 'INHESC2020040702', 'ZWS', 'ZWS02', '1921121.4', '竞标组', '林丹敏', '李忠鹏,覃湘君', '2020-04-07', '海陆联运', '银河承担', 'CIP 哈拉雷电力公司仓库', '江西工厂', '按照ZWS01项目包装要求', '按照ZWS01项目验货标准', 'DDZ1513，DTZ1513', '02', '产品技术按照OA“ZWS项目（中标项目）技术合同评审申请”及附件双方签字版技术规格书为准，按ZWS01翻单，具体生产前须与业务确认。', '', '1. ZWS项目在2018年8月20日，以电力公司标准合同模板，走过一次商务合同评审流程，但未执行；第一批次ZWS01在2019年12月23日走完合同变更流程，已发货并收齐款项；本次依然根据分批发货执行情况及LC开立情况，制定第二批次ZWS02的销售合同，供内部审核，ZWS02订单执行流程请按此为准。\r\r\r\r\r\r\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\n \r\r\r\r\r\r\r\n2. 本次ZWS02合同附件仅包含“收款银行账户声明（中国银行）”、“双方签字的终版技术规格书”。\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\n\r\r\r\r\r\r\n3.ZWS02的报价已经过公司审核；佣金已经过公司审核；信用证在OA“ZWS中标合同信用证开立和审核（电力公司直接开立信用证）”在2020年4月2日开出，评审中，具体按最终版信用证为准。\r\r\r\r\r\r\r\r\r\r\n\r\r\r\r\r\r\n4. LC显示的最晚装船期是2020年6月15日，须着手启动生产准备。\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\n5. 业务确认将协调客户，按照银河标准合同模板签回ZWS项目所有批次整合一起的销售合同，后续签回后更新到相关流程中。\r\r\r\r\r\r\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\r\r\r\r\r\r\n', '', '20080', '1921121.4', '0', '{4A4CD10806844469928CE6FA3A3BD1EE3E3FD1A05260451F8D948358003231C8}_ZWS02中英销售合同 Revised Sales Contract INHESC2020040702.pdf', '信用证最迟装船期2020年6月15日', '{4A4CD10806844469928CE6FA3A3BD1EE7719915B5AFB4CFC8E75112B161686FE}_ZWS项目三款表最终签字确认规格书（扫描版）.zip', '', '合同评审', '02', 'CIP 哈拉雷，津巴布韦', '上述货物将在卖方收到覆盖100%合同金额的不可撤销的保兑的远期60天的信用证款后60天内从卖方工厂发出；前提是信用证条款须被合同双方接受。最晚最船期2020年6月15日', '发货之日起24个月', '否', '否', '否（当前按照银河标准合同执行则不涉及到违约金/罚金）', '合同金额的100%通过不可撤销的保兑的远期60天的信用证支付', '2018年ZWS合同评审运费报价如下：1. DIN导轨单相表，海运运保费2美金每台；2. BS单相表，海运运保费2.2美金每台；3. BS三相表，海运运保费3.2美金每台。复合2020年3月跟单组在OA“ZWS项目运费询价\"中更新的运费情况，确认运费足够。', '02', '01', '', '02', '', '01', '01', 'OA“ZWS项目（中标项目）技术合同评审申请”及附件双方签字版技术规格书', '是', '详情参考李忠鹏最新报批公司ZWS项目佣金计算OA。', '02', '', '', '', '', '银河电力', '143');
INSERT INTO `crs_tabledata696` VALUES ('869', '{9DD9D578-4FC8-4D7E-8615-E609DEBFDF07}', '61', 'INHE-0578', '2020-04-15 09:32:30', '0000-00-00 00:00:00', '2020-05-11 17:07:18', 'unchecked', 'n', 'n', '', '1', 'Finmark Industries (Pvt) Ltd./INHESC2020040801/EOI65/合同评审', '', 'Finmark Industries (Pvt) Ltd.', 'FINMARK HOLDINGS PVT LTD', 'INHESC2020040801', 'EOI', 'EOI65', '156823.86', '国际二部 INTL.Business Dept.2', '覃湘君(June)', '李忠鹏', '2020-04-15', '海运', '买家向银河支付运保费', '哈拉雷', '江西工厂', '按照EOI项目要求', '按照EOI项目要求', 'DDZ1513', '01', '无', '1.该单属于EOI项目，代号EOI65；使用EOI项目库存；海陆联运。\r\r\r\r\r\r\r\r\r\r\r\r\r\r\n2.该单支付方式为：抵扣掉ZWS01项目的全部佣金，抵扣部分服务合同费用；详见合同内结算表达。在佣金支付条件满足后方安排发货。\r\r\r\r\r\r\r\r\r\r\r\r\r\r\n3.单价USD38美元经过公司评审，高于此客户其它订单执行的价格（EUR34.32/RMB260.00）；运保费按照跟单组报价1.1倍报出，足够（跟单组报价20GP、深圳出货：7000USD）。\r\r\r\r\r\r\r\r\r\r\n4.实际合同相对方为：FINMARK HOLDINGS PVT LTD，与ZWS01佣金签署方保持一致。\r\r\r\r\r\r\r\r\r\r\n5.报价，公司同意佣金抵扣，合同及佣金协议补充协议等评审，均体现在OA“ZWS01佣金部分转换为EOI订单申请_20200324”。鉴于使用库存出货，所有条款均已经过公司评审，建议仍按照EOI项目简化流程处理。', '', '', '3920', '148960', '7863.86', '{9DD9D5784FC84D7E8615E609DEBFDF073E3FD1A05260451F8D948358003231C8}_Sales_Contract_of_3,920_meters_to_FHL.pdf', '2020年4月24日', '{9DD9D5784FC84D7E8615E609DEBFDF077719915B5AFB4CFC8E75112B161686FE}_ZWS01_Commission_AGRT_Supplementry_042020.pdf', '{9DD9D5784FC84D7E8615E609DEBFDF077842EE48FE5340F2BE4CBD5E93168F23}_ZWS01_Service_AGRT_Supplementry_042020.pdf', '合同评审', '02', 'CIP哈拉雷', '满足佣金支付条件、电表生产完成后发货', '从卖方工厂发货之日起24个月', '否', '否', '否', '合同全款使用FHL的佣金抵扣', '不包含，运保费单独收费。', '05', '01', '', '02', '', '02', '01', 'EOI和ZWS技术规格解析', '否', '/', '02', '', '', '', '', '银河电力', '61');
INSERT INTO `crs_tabledata696` VALUES ('870', '{F7FAED27-66E7-41CE-ADC0-C02B81553457}', '61', 'INHE-0725', '2020-04-16 13:54:52', '0000-00-00 00:00:00', '2020-05-11 17:06:54', 'unchecked', 'n', 'n', '', '1', 'Nayo Tropical Technology Limited/INHESC2020041401/AN04/合同评审', '', 'Nayo Tropical Technology Limited', 'Nayo Tropical Technology Limited', 'INHESC2020041401', 'AN', 'AN04', '2000', '国际二部 INTL.Business Dept.2', '赵政洁(Oscar)', '赵政洁', '2020-04-16', '软件远程部署交付，可以压缩包或邮件形式', '软件无运费', '中国深圳', '中国深圳', '无', '银河标准', 'SmartVend', '01', '', '', '', '', '0', '0', '0', '{F7FAED2766E741CEADC0C02B815534573E3FD1A05260451F8D948358003231C8}_Annex 1 Service Description.pdf', '5月10日', '', '', '合同评审', '02', 'EXW Shenzhen, China', '收到100%预付款10天内为客户更新2年期售电Lincese，采用云平台部署，从2020年1月1日开始计费', '提供系统License后由客户自行负责，系统出问题银河协助解决', '否', '否', '否', '合同签订10天内支付100%预付款', '不包含运费或保费', '05', '01', '', '02', '', '02', '02', '', '否', '无', '02', '', '', '', '{F7FAED2766E741CEADC0C02B815534574654CAE914AA4B25B6892952453EBAEB}_AN04 Sales Contract_20200414.pdf', '银河电力', '61');
INSERT INTO `crs_tabledata696` VALUES ('871', '{EFEBF9E7-FD3E-4E72-A299-21033CDA5C79}', '61', 'INHE-0772', '2020-04-21 16:05:34', '0000-00-00 00:00:00', '2020-05-11 17:06:30', 'unchecked', 'n', 'n', '', '1', 'La Société Nationale dElectricité du Burkina/SL/FT/N000394/MLF01/合同评审', '', 'La Société Nationale dElectricité du Burkina', 'La Société Nationale dElectricité du Burkina', 'SL/FT/N000394', 'MLF', 'MLF01', '120000', '国际二部 INTL.Business Dept.2', '张子琦(Miranda)', '张子琦,胡亚婵', '2020-04-21', '无', '无', '瓦加杜古', '深圳', '无', '银河标准', '', '', '', '1. 电力公司要求按照他提供合同模板						\r\r\r\r\r\n2. 合同编号暂定：SL/FT/N000394，后续以电力公司盖章版本为准。3.沟通T/T方式付款，按照当地的采购规定，\r\r\r\r\r\n我们需要开出同等金额的保函。4.提单问题：软件可以邮寄一个快递，出提单。\r5. 合同：1式7份，通过DHL寄送\r\r\r\n', '', '', '0', '0', '0', '', '2020-06-24', '', '', '合同评审', '02', 'EXW', '信用证后64天', '纳入BFN的软件维护合同中', '是', 'NO', 'NO', '不可撤销信用证', '无', '02', '01', '', '02', '', '02', '01', 'MLF项目技术支持申请', '是', '15000美金', '02', '', '02', '★★★', '{EFEBF9E7FD3E4E72A29921033CDA5C794654CAE914AA4B25B6892952453EBAEB}_MLF 合同 20200428.rar', '银河电力', '61');
INSERT INTO `crs_tabledata696` VALUES ('872', '{D45E7EB1-FBC1-4684-A267-0C0BA32E67B8}', '61', 'INHE-0721', '2020-04-24 12:45:55', '0000-00-00 00:00:00', '2020-05-11 17:06:08', 'unchecked', 'n', 'n', '', '1', 'MESSEN S.A.S/INHESC2020042201\r\n/PSA17-04/合同评审', '实际已收款为USD 4,000.00', 'MESSEN S.A.S', 'MESSEN S.A.S', 'INHESC2020042201', 'PSA17', 'PSA17-04', '11000', '国际二部 INTL.Business Dept.2', '胡云义(Anita)', '胡云义', '2020-04-24', '/', '/', '/', '/', '/', '参考合同附件2', '', '', '', '合同软件服务安排线上远程实施。', '', '', '0', '0', '0', '', '2020.05.31', '{D45E7EB1FBC14684A2670C0BA32E67B87719915B5AFB4CFC8E75112B161686FE}_Appendix1：Content of Software Service.docx', '{D45E7EB1FBC14684A2670C0BA32E67B87842EE48FE5340F2BE4CBD5E93168F23}_Appendix 2-Acceptance?For?Software Services.docx', '合同评审', '02', '/', '合同生效并收到MESSEN全款后, 依据合同附件1完成软件服务', '/', '否', '否', '否', '已通过T/T支付叁仟美金（USD 3,000) 作为预付款，客户MESSEN 将在2020年5月内通过T/T支付捌仟美金（USD 8,000) 尾款', '/', '05', '01', '', '02', '', '01', '01', 'PSA项目技术支持', '否', '无', '02', '', '', '', '{D45E7EB1FBC14684A2670C0BA32E67B84654CAE914AA4B25B6892952453EBAEB}_Contrato de software-PSA17-04.docx', '银河电力', '61');
INSERT INTO `crs_tabledata696` VALUES ('873', '{1D022493-1401-4D5A-A805-A1FB9D1290E8}', '144', 'INHE-0859', '2020-04-27 09:04:03', '0000-00-00 00:00:00', '2020-05-11 17:05:43', 'unchecked', 'n', 'n', '', '1', 'INHEMETER (T) LIMITED/INHESC2019051801-7\r\n/TTL01-7\r\n/合同评审', '附件补充合同', 'INHEMETER (T) LIMITED', 'INHEMETER (T) LIMITED', 'INHESC2019051801-7', 'TTL', 'TTL01-7\r\n', '961347.35', '投标组', '陈金珠', '汤伟', '2020-04-27', '海运', '银河电力', 'Dar es Salaam（达累斯萨拉姆）', '江西工厂', '工厂成品仓常规包装，须有纸箱等备品', 'IEC/EN', 'DDZ1513', '01', '无', '海运费暂按2500USD/40HQ结算，因为该合同去年报价为FOB报价，而EXW报价方案今年才开始执行。', '暂无', '', '25002', '961347.35', '0', '{1D02249314014D5AA805A1FB9D1290E83E3FD1A05260451F8D948358003231C8}_TTL01-7_PI和客户签字合同.pdf', '预计2020/5月/6日（待定）', '', '', '合同评审', '02', 'CIF', '本合同项下的货物将在卖方收到USD163，429.05的预付款后30天内，从卖方工厂发出', '卖方所提供货物的保修期为从卖方工厂发货之日起18个月', '是', '是', '否', '中信保承保的赊销T/T', '否', '经销', '01', 'TTL', '02', '', '01', '01', 'TTA项目试生产和批量生产会议', '是', '单只表0.5USD', '02', '', '', '', '', '银河电力', '144');
