INSERT INTO `crs_tabledata696` VALUES ('881', '{B377726E-3541-451D-8D99-02EB11F1997B}', '66', 'INHE-0634', '2020-05-27 14:07:31', '0000-00-00 00:00:00', '2020-06-02 09:50:42', 'unchecked', 'n', 'n', '', '1', 'Dynamax (Macau) Limited/PO-2005-1773/MOC03/合同评审', '', '达明（澳门）有限公司Dynamax (Macau) Limited', 'Dynamax (Macau) Limited', 'PO-2005-1773', 'MOC', 'MOC03', '5710', '国际三部 INTL.Business Dept.3', '陈雁', '陈雁', '2020-05-27', '顺丰快递到付', '客户', '深圳', 'Unit K, 15th Floor, Tong Nam Ah Commercial Centre\r\nNo.180 Alameda Dr. Carlos D\'Assumpcao, Macau\r\n澳門新口岸宋玉生廣場180號東南亞商業中心15樓K座\r\n', '确保运输过程中不损坏货物', '软件部验收', 'i6300', '01', '', '(1)客户原本采购的旧款掌机无法抄读CT表（RF通信），因此再买一台新掌机以解决问题。				(2)第三方付款文件正在制作中，客户很配合，无太大困难签回。		\r\r\n', '', '', '0', '0', '0', '{B377726E3541451D8D9902EB11F1997B3E3FD1A05260451F8D948358003231C8}_PO译文-1773 Inhemeter Smartphone.docx', '6月8日', '{B377726E3541451D8D9902EB11F1997B7719915B5AFB4CFC8E75112B161686FE}_PI-MOC03-IN RMB.pdf', '{B377726E3541451D8D9902EB11F1997B7842EE48FE5340F2BE4CBD5E93168F23}_MOC03 RMB5170 转账水单.pdf', '合同评审', '04', 'FOB SHENZHEN', '收到全款后尽早发货', '1年', '否', '否', '否', '100%TT预付，付款水单请见附件', '否', '02', '01', '', '01', '', '02', '01', 'MOC02客户培训', '否', '否', '02', '否', '', '', '{B377726E3541451D8D9902EB11F1997B4654CAE914AA4B25B6892952453EBAEB}_PO原文-1773 Inhemeter Smartphone.pdf', '银河电力', '66');
INSERT INTO `crs_tabledata696` VALUES ('882', '{647F4EF5-8E9D-48FC-BE5A-A218EE5F3E18}', '61', 'INHE-0913', '2020-06-08 10:23:13', '0000-00-00 00:00:00', '2020-06-09 16:40:43', 'unchecked', 'n', 'n', '', '1', 'SETH/SC NO.1907/007/20/MEC01/合同评审', '1.请和客户协商，MEC01和02签署成一份合同，或整理成一个评审，节省评审资源消耗；2.合同中请准确，明确价格术语。暂时不能明确，请签署EXW，发货前再一次性变更。', 'SETH', 'Sociedade de Empreitadas e Trabalhos Hidráulicos, S.A', 'SC NO.1907/007/20', 'MEC', 'MEC01', '26346.6', '国际二部 INTL.Business Dept.2', '魏紫薇(Valentine)', '魏紫薇', '2020-06-08', '无', '买方，SETH', '江西九江', '江西工厂', '无', '工厂内部自检+SGS/FAT', 'DIN-III（CIP-FSK）#FE54`一代三相四线直接接入式分体代码表(PLC通讯)', '02', '无', '合同签订基于FOB JIUJIANG价格术语，但在合同中银河将同样提供CIF价格术语，即FOB JIUJIANG基础上包含海运运费和保险费，由客户在发货前10天内决定是否激活CIF条款。\r\r\n此项条款存在原因在于，客户正在推进第三份合同，预计有一万多台的电表，希望能够在MEC01,MEC02发货前推进第三份合同签订，以便能够将MEC01,MEC02以及第三份合同包含的三批货物一起发货，节省运费。(MEC01 和MEC02将会一批发货)因此，客户将根据第三份合同的推进进度，发货之前10天之内决定是否由银河负责运输', '1.价格术语：虽然客户发送合同条款内容为FCA SHENZHEN，与客户协商之后客户同意FOB JIUJIANG条款，合同签订将基于FOB JIUJIANG价格术语签订；同时，合同中银河将同样提供CIF价格术语（即基于报价单的FOB价格加上运费和保险费），在发货前10天内，将由客户决定是否激活CIF条款。\r\r\n2.交货期限：预付款支付后60天\r\r\n3.付款方式：如果客户采用FOB条款，付款方式依据合同内容；若客户采用CIF条款，30%预付费依旧基于FOB价格的30%支付，剩余70%将与运费和保险一起在发货前支付\r\r\n4.交货逾期罚款：交货逾期需缴付罚款，但银河不负责由任何不可抗力事件以及客户原因造成的延期\r\r\n\r\r\n', '客户货物要求较急，如需客户重新修改合同签字，内部流程花费时间过长，将以邮件协商内容作为凭证，并在发货之前签订合同变更补充协议。', '765', '26346.6', '0', '{647F4EF58E9D48FCBE5AA218EE5F3E183E3FD1A05260451F8D948358003231C8}_Sale_Contract_1907_007_20_Inhemeter.pdf', '预付款支付后60天', '{647F4EF58E9D48FCBE5AA218EE5F3E187719915B5AFB4CFC8E75112B161686FE}_MEC01 合同翻译件.docx', '', '合同评审', '02', 'FOB JIUJIANG,CHINA', '在发货前需支付剩余70%尾款以及签订销售合同变更补充协议', '交货单发出后18个月/电表投入使用后12个月', '否', '否', '是，逾期后每天需支付千分之一的罚款', '合同金额的30%在签订合同10天内作为预付款T/T支付，70%余款在发货前T/T支付', '不包含保费和运费，但包含佣金', '05', '01', '', '02', '', '01', '01', 'MEC技术支持申请', '是', 'FOB价格的5%', '02', '', '01', '★★', '', '银河电力', '61');
INSERT INTO `crs_tabledata696` VALUES ('883', '{AE885214-D1E1-4BEF-BE3D-B90853E39093}', '61', 'INHE-0913', '2020-06-08 15:13:38', '0000-00-00 00:00:00', '2020-06-09 16:36:09', 'unchecked', 'n', 'n', '', '1', 'SETH/SC NO.1907/008/20/MEC02/合同评审', '1.请和客户协商，MEC01和02签署成一份合同，或整理成一个评审，节省评审资源消耗；2.合同中请准确，明确价格术语。暂时不能明确，请签署EXW，发货前再一次性变更。', 'SETH', 'Sociedade de Empreitadas e Trabalhos Hidráulicos, S.A', 'SC NO.1907/008/20', 'MEC', 'MEC02', '23507.4', '国际二部 INTL.Business Dept.2', '魏紫薇(Valentine)', '魏紫薇', '2020-06-08', '无', '买方，SETH', '江西九江', '江西工厂', '无', '工厂内部自检+SGS/FAT', 'DIN-III（CIP-FSK）#FE54`一代三相四线直接接入式分体代码表(PLC通讯)', '02', '无', '合同签订基于FOB JIUJIANG价格术语，但在合同中银河将同样提供CIF价格术语，即FOB JIUJIANG基础上包含海运运费和保险费，由客户在发货前10天内决定是否激活CIF条款。\r\r\n此项条款存在原因在于，客户正在推进第三份合同，预计有一万多台的电表，希望能够在MEC01,MEC02发货前推进第三份合同签订，（MEC01和MEC02将一批发货）以便能够将MEC01,MEC02以及第三份合同包含的三批货物一起发货，节省运费。因此，客户将根据第三份合同的推进进度，发货之前10天之内决定是否由银河负责运输', '1.价格术语：虽然客户发送合同条款内容为FCA SHENZHEN，与客户协商之后客户同意FOB JIUJIANG条款，合同签订将基于FOB JIUJIANG价格术语签订；同时，合同中银河将同样提供CIF价格术语（即基于报价单的FOB价格加上运费和保险费），在发货前10天内，将由客户决定是否激活CIF条款。\r\r\n2.交货期限：预付款支付后60天\r\r\n3.付款方式：如果客户采用FOB条款，付款方式依据合同内容；若客户采用CIF条款，30%预付费依旧基于FOB价格的30%支付，剩余70%将与运费和保险一起在发货前支付\r\r\n4.交货逾期罚款：交货逾期需缴付罚款，但银河不负责由任何不可抗力事件以及客户原因造成的延期\r\r\n\r\r\n', '客户货物要求较急，如需客户重新修改合同签字，内部流程花费时间过长，将以邮件协商内容作为凭证，并在发货之前签订合同变更补充协议', '671', '23507.4', '0', '{AE885214D1E14BEFBE3DB90853E390933E3FD1A05260451F8D948358003231C8}_Sale_Contract_1907_008_20_Inhemeter.pdf', '预付款支付后60天', '{AE885214D1E14BEFBE3DB90853E390937719915B5AFB4CFC8E75112B161686FE}_MEC02 合同翻译件.docx', '', '合同评审', '02', 'FOB JIUJIANG,CHINA', '在发货前需支付剩余70%尾款以及签订销售合同变更补充协议', '交货单发出后18个月/电表投入使用后12个月', '否', '否', '是，逾期后每天需支付千分之一的罚款', '合同金额的30%在签订合同10天内作为预付款T/T支付，70%余款在发货前T/T支付', '不包含保费和运费，但包含佣金', '05', '01', '', '02', '', '01', '01', 'MEC技术支持申请', '是', 'FOB价格的5%', '02', '', '01', '★★', '', '银河电力', '61');
INSERT INTO `crs_tabledata696` VALUES ('884', '{E78E7A13-5A66-41AD-9AA2-01C923FC5C9B}', '66', 'INHE-0774', '2020-06-08 16:46:45', '0000-00-00 00:00:00', '2020-07-01 12:07:10', 'unchecked', 'n', 'n', '', '1', 'Palestinian energy and Natural Resources Authority/PEA WB-RPP 01/2019/BAL/合同评审', '', 'MOSECO C Modern Scientific & Electronics Co.', 'Palestinian energy and Natural Resources Authority', 'PEA WB-RPP 01/2019', 'BAL', 'BAL', '4092851.2141814', '国际三部 INTL.Business Dept.3', '何森华', '何森华', '2020-06-08', '海运', '银河', '巴勒斯坦Jericho 电力公司仓库', '江西', '1. \r所有的货物应该装在防水的集装箱中，并用适当的包装以在运输和存储过程中保护货物（尤其是零配件）。集装箱外的标记应包含商业发票描述内含的货物和一个清楚印上买方和目的地的标签。集装箱需留余量以便买方在确认配件数量后能重新密封集装箱。\r\r\n\r\r\n2.包装应为货物提供足够的保护，以防止其运输到最终目的地时受到机械损坏，包括在海上，铁路和公路运输中以及从一种运输方式转到另一种运输方式中的粗暴处理；3. 包装应为坚固，结实，厚度合适的木板箱，适当的支撑和捆扎，并在内部衬以防水材料或同样坚固的外壳。钢结构型材和类似物品可以捆绑在一起，但前提是要充分保护端部，并且围带或金属丝结实。\r\r\r\r\r\r\n4. 室内电气设备必须装在包装箱内的焊接聚乙烯外壳中，并且外壳应抽成真空或内部装有干燥剂。\r\r\r\r\r\r\n5. 箱子或板条箱中的所有物品均应固定好，以免它们随意移动且在运输中不能松动。 如果旋转零件在其轴承或安装件中运输，则必须充分支撑和约束它们，以防止其相对运动。 松散的物品应放在箱子中的袋子中，每个袋子上都缝有一个标签，标明其内容物的数量和性质。 如果使用填充材料限制移动或提供其他保护，则填充材料必须是无机且不吸湿的。\r\r\r\n6.应采取措施确保水分，霉菌，昆虫或啮齿动物不会损坏绝缘材料。 包括易受潮气损坏的材料在内的物品应装在装有硅胶或其他批准的干燥剂的密封容器中。\r\r\r\r\r\r\n7. 箱体应标有大写字母，以表明箱体的哪一侧朝上；如果内装物品易碎，则在大号字母上用国际酒杯符号标记“易碎品”。 包装上应标明目的地，粗暴处理或天气影响不能去除或抹除。 每件物品均应标有其毛重，对于超过两吨的所有提升物，箱子上的标记应显示正确的吊索位置\r\r\r\r\r\r\n8. 运输过程中应采取特殊措施防止盗窃。挂锁铭牌等可能被撕下或拧开物件不能被取下。\r\r\r\r\r\r\n9. 每个包装箱的内容应准备一份描述性且详尽的清单。 该清单的副本应放在防水信封中，该信封在固定在箱子一端外面的金属或其他合适的板下，并通过在箱子上的图案指示其位置。 适当时，应在箱子内部放置显示有关物品的安装标记的图纸。\r\r\r\r\r\r\n10.所有包装箱，除集装箱\r外，归买方所有。\r\r\r\r\r\r\n\r\r\r\r\r\r\n\r\r\r\r\r\r\n\r\r\r\r\r\r\n\r\r\r\r\r\r\n\r\r\r\r\r\r\n\r\r\r\n', 'I FAT\r\r\r\n1. FAT应包含报价方案的所有内容，不仅仅是硬件；\r\r\r\n2. 根据适用的IEC标准或指定的条件或买方认可的标准进行。\r\r\r\n3. 买方可以自由要求在制造商的地点，现场或其他地方进行任何其他测试，以验证设备是否符合规范的条件。\r\r\r\n4. 测试程序应至少在测试开始前1个月提交买方，以供批准。 供应商有责任至少提前1个月通知买方货物准备好检验。\r\r\r\n5. 电表应由买方批准，如有需要，应在认可实验室中由供应商承担费用进行认证。\r\r\r\n6.投标人必须提交由信誉良好的独立测试机构（例如SGS，必维国际检验集团，CESI或任何其他知名机构）进行的所提供电表的型式测试。\r\r\r\n7. 供应商应提供必要的设施，设备和文件，以完成所有检查并核实是否按照本规范制造和维护电表和软件包。\r\r\r\n8. 只有通过了FAT电力局才会授权发货，在电表和软件验证达到要求前电力局不会接受发货。\r\r\r\nII 电表现场验收测试：\r\r\r\n1. 电力局保留执行技术规格中详细说明的所有电表功能测试并通过按照IEC 62058-11-31标准进行测试来验证是否合格的权利。\r\r\r\n2.电力局保留在电力局代表在场的情况下，由认可的实验室或在制造商的实验室中进行此类测试的权利。\r\r\r\n3.供应商需派一个技术人员去现场支持测试\r\r\r\n4. 如果电表不能通过测试，整个批次电表被认为不合格，供应商需要自费更换整个批次电表；\r\r\r\n\r\r\r\nIII 现场系统验收测试\r\r\r\n1. 现场验收测试独立于其他测试，必须视为系统验收的最后一步，是付款进度的组成\r\r\r\n2. 供应商必须对每个电力公司进行完整的集成系统现场验收测试，其中包括：安装系统的所有组件（电表，AMR，MDM和第三方软件），测试系统的总体功能和特性， 性能测试和安全性测试。 验收测试将从可能的最少仪表开始，直到安装仪表的20％\r\r\r\n3. 必须完成对远程操作的完整测试，其中包括：远程数据读取，测试预付费和后付费电表操作的功能和特性以及AMI功能（电表数据下载，电表远程连接和断开）。 执行测试的目的是验证系统与电表远程通信的能力。\r\r\r\n验收测试要求在标书技术规格3.51-3.60详细描述\r\r\r\n\r\r\r\n', 'DDZ1513，DTZ1513，I6300', '02', '', '关于价格差异说明：第1.1.4 项下的3相预付费表价格客户算成了145.79美元，而我们报价180.80美元；同时，每项的加总也因为小数点保留显示的原因有差异。导致中标合同价格比我们最终核算总价少286.53美元。', '', '', '16200', '1930014.0805814', '3577.6068', '{E78E7A135A6641AD9AA201C923FC5C9B3E3FD1A05260451F8D948358003231C8}_Contract.docx', '电表、软件交付、AMR/MDM安装、配置、测试：签定合同后90天内，其他服务：签定合同后120天内', '', '', '合同评审', '02', 'CIP', '收到80%合同金额后发货', '软件：3年，电表和通信设备：2年', '否', '否', '违约金：0.1%每个工作日，最高10%合同金额', '1.10%预付款在合同签定后30天内，收到预付款保函后支付；2.70%在发货前通过不可撤销保兑信用证支付；3.20%在验收合格后30天内支付', '保费：4920.43美元海运费：7647.77美元目的国内陆运费+清关手续费：13081.15美元以色列进口关税：179517.31美元VAT(以色列)：254316.18美元', '01', '01', '', '02', '', '01', '01', 'BAL项目 合同文本技术规格部分审核确认', '是', '电表和软件FOB价的15%', '02', '', '02', '★★★', '', '银河电力', '66');
INSERT INTO `crs_tabledata696` VALUES ('886', '{08BC434B-63BA-4548-8C07-E879B5FBF69A}', '61', 'INHE-0916', '2020-06-09 17:30:42', '0000-00-00 00:00:00', '2020-06-11 15:13:21', 'unchecked', 'n', 'n', '', '1', 'ZECHER INVESTMENTS/INHESC2020060901/EOI68/合同评审', 'June已审核，满足条件见“特殊要求说明”，请知悉', 'Finmark Industries (Pvt) Ltd.', 'ZECHER INVESTMENTS', 'INHESC2020060501', 'EOI', 'EOI68', '8460', '国际二部 INTL.Business Dept.2', '赖星威', '李忠鹏', '2020-06-09', '空运\r\n', '客户承担运保费', '哈拉雷国际机场', '中国任意机场\r\n', '按照EOI项目要求\r\n', '按照EOI项目要求\r\n', 'DTZ1513', '01', '用EOI现有库存(烧掉HE LOGO)出货', '1. 本项目合同相对方为ZECHER INVESTMENTS,与付款水单名称一致。实际收货方为ALTIMATE COMMUNICATIONS，已在合同中约定。\r\r\r\r\r\r\r\r\n2. 全款已到账\r\r\r\r\r\r\r\n3. 有库存，用现有EOI库存出货\r\r\r\r\r\r\r\n4. 价格高于谌总审批的底价（135.00 USD）\r\r\r\r\r\r\r\n5. 运保费比跟单组最新报价高20%', '', '', '50', '7000', '1460', '{08BC434B63BA45488C07E879B5FBF69A3E3FD1A05260451F8D948358003231C8}_EOI68 Sales Contract for ZECHER INVESTMENTS 20200605.docx', '', '', '', '合同评审', '02', 'CIP，哈拉雷国际机场', '上述货物将在卖方收到买方T/T支付的合同全款后10天内，从卖方工厂发出。', '保修期为从卖方工厂发货之日起24个月。', '否', '否', '否', '合同金额的100%在签订合同30天内作为预付款在发货前T/T支付。', '否', '05', '01', '', '02', '', '02', '01', 'ZWS和EOI技术规格解析申请', '否', '否', '02', '', '', '', '', '银河电力', '');
INSERT INTO `crs_tabledata696` VALUES ('887', '{5230B8F0-3658-4924-9CF0-CD982D3DE167}', '61', 'INHE-0721', '2020-06-11 13:01:42', '0000-00-00 00:00:00', '2020-06-15 12:35:03', 'unchecked', 'n', 'n', '', '1', 'MESSEN S.A.S/INHESC2020061001\r\n/PSA17-06/合同评审', '', 'MESSEN S.A.S', 'MESSEN S.A.S', 'INHESC2020061001', 'PSA17', 'PSA17-06', '10600', '国际二部 INTL.Business Dept.2', '胡云义(Anita)', '胡云义', '2020-06-11', '海运', '客户', '九江', '江西工厂', '货物应该包装在牢固的纸箱里，方便海运', '按IEC标准', 'DTZ1513', '', '', 'PSA市场在当地3家电力公司均有供货CT表，现场时常出现个别CT表技术问题，远程分析、解决，加上时差影响，经常无法较快帮助客户解决，影响电力公司对大用户数据的及时采集、分析报表等，而电力公司非常重视大用户数据，所以代理希望采购一定数量的CT表做库存，以便在个别CT表出现问题时，能够及时提供替换电表，响应客户，维系好关系，争取更多的时间来处理、解决技术问题，提高产品售后服务质量。\r\r\n', '', '', '130', '10600', '0', '{5230B8F0365849249CF0CD982D3DE1673E3FD1A05260451F8D948358003231C8}_Sales contract销售合同-PSA17-06.doc', '2020/07/11', '', '', '合同评审', '02', 'FOB 九江', '收到全款后发货', '36个月', '否', '否', '否', '合同金额的30%在签订合同10天内作为预付款T/T支付，70%余款在生产完成前10天T/T支付。', '否', '05', '02', 'PSA17-03', '02', '', '02', '01', '', '否', '/', '02', '', '', '', '', '银河电力', '61');
INSERT INTO `crs_tabledata696` VALUES ('888', '{432B0FEC-AC5F-4D74-84A7-48A94A34276E}', '61', 'INHE-0913', '2020-06-11 14:37:04', '0000-00-00 00:00:00', '2020-06-15 12:34:39', 'unchecked', 'n', 'n', '', '1', 'Sociedade de Empreitadas e Trabalhos Hidráulicos, S.A/SC NO.1907/007/20-REV1 and NO.1907/008/20-REV1/MEC01/合同评审', '', 'SETH', 'Sociedade de Empreitadas e Trabalhos Hidráulicos, S.A', 'SC NO.1907/007/20-REV1 and NO.1907/008/20-REV1', 'MEC', 'MEC01', '52254', '国际二部 INTL.Business Dept.2', '魏紫薇(Valentine)', '魏紫薇(Valentine)', '2020-06-11', '无', '买方，SETH', '莫桑比克，贝拉港口', '江西工厂', '无', '工厂内部自检+SGS/FAT', 'DIN-III（CIP-FSK）#FE54`一代三相四线直接接入式分体代码表(PLC通讯)', '02', '无', '合同签订基于EXW价格术语，但在合同中银河将同样提供FOB和CIF价格术语，即FOB JIUJIANG基础上包含海运运费和保险费，由客户在发货前10天内决定是否激活CIF条款。\r\r\r\r\r\r\n此项条款存在原因在于，客户正在推进第三份合同，预计有一万多台的电表，希望能够在MEC01发货前推进第三份合同签订，（MEC01包含两份合同）以便能够将MEC01以及第三份合同包含的货物一批发货，节省运费。因此，客户将根据第三份合同的推进进度，发货之前10天之内决定是采用FOB条款还是CIF条款', '已签订的合同条款为EXW\r\r\r\r\r\n发货前十天内将签订销售合同变更补充协议，客户确定最终价格条款:\r即是否变更为CIF\r\r\r\n\r\r\r\r\n', '', '1436', '49854', '0', '{360E2A13433B4ECEA1BE91086013B942D4CC22B6C7B643389146528155CECD45}_1907_007_20_REV1_Inhemeter.pdf', '预付款支付之后60天', '{360E2A13433B4ECEA1BE91086013B9429E19E8E731434A848B97C6F1C79E3A54}_1907_008_20_REV1_Inhemeter.pdf', '{360E2A13433B4ECEA1BE91086013B942BA0F4BB9344A4053BE173BB06528647F}_PROFORMA INVOICE.pdf', '合同评审', '02', 'EXW', '在发货前需支付剩余70%尾款以及签订销售合同变更补充协议', '提单发出后18个月/电表投入使用后12个月', '否', '否', '是，逾期后每天需支付千分之一的罚款', '合同金额的30%在签订合同10天内作为预付款T/T支付，70%余款在发货前T/T支付', '不包含保费和运费，但包含佣金', '05', '01', '', '02', '', '01', '01', 'MEC技术支持申请', '是', 'EXW报价的5%', '02', '', '01', '★★', '', '银河电力', '61');
INSERT INTO `crs_tabledata696` VALUES ('889', '{861F9B71-BB8C-4ED2-873A-330F6B619B0B}', '61', 'INHE-0500', '2020-06-16 17:56:21', '0000-00-00 00:00:00', '2020-06-18 14:37:58', 'unchecked', 'n', 'n', '', '1', 'DELEGATE IBERICA LDA/INHESC2020061601\r\n/EAB04/合同评审', '', 'Baltazar Fernandes and Moreira,lda', 'DELEGATE IBERICA LDA', 'INHESC2020061601', 'EAB', 'EAB04', '96000', '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '李忠鹏(Evans)', '2020-06-16', '空运', '客户承担', '江西工厂', '江西工厂', '同EAB03', '同EAB03', 'I100', '02', '', '请按照EAB03订单直接翻单生产和交付。', '', '', '3000', '96000', '0', '{861F9B71BB8C4ED2873A330F6B619B0B3E3FD1A05260451F8D948358003231C8}_Annex_Default Parameter Setting Confirmation Sheet (2).pdf', '上述货物将在卖方收到买方T/T支付的合同全款后45天内，从卖方工厂发出。\r\n', '{861F9B71BB8C4ED2873A330F6B619B0B7719915B5AFB4CFC8E75112B161686FE}_EAB04销售合同.docx', '', '合同评审', '02', 'FCA 九江', '上述货物将在卖方收到买方T/T支付的合同全款后45天内，从卖方工厂发出。', '12个月', '否', '否', '否', '合同项下的37000美金需在生产前支付，合同项下的尾款59000美金需在合同签订后5天内并在发货前支付。', '不含', '05', '01', '', '02', '', '01', '01', 'EAB01项目生产通知单', '否', '否', '02', 'N/A', '', '', '', '银河电力', '61');
INSERT INTO `crs_tabledata696` VALUES ('890', '{D7BDED19-7516-4B01-ADCC-A1827677D04E}', '61', 'INHE-0725', '2020-06-22 08:38:29', '0000-00-00 00:00:00', '2020-06-28 11:33:24', 'unchecked', 'n', 'n', '', '1', 'Ampersand Logistics/INHESC2020061602/MNP03/合同评审', '', 'ACOB Lighting Technology Ltd', 'Ampersand Logistics', 'INHESC2020061602', 'MNP', 'MNP03', '2000', '国际二部 INTL.Business Dept.2', '赵政洁(Oscar)', '赵政洁(Oscar)', '2020-06-22', '软件远程部署交付，可以压缩包或邮件形式', '软件无运费', '中国深圳', '中国深圳', '无', '银河标准', 'SmartVend', '01', '', '', '', '', '0', '0', '0', '', '2020年7月10日', '{D7BDED1975164B01ADCCA1827677D04E7719915B5AFB4CFC8E75112B161686FE}_Annex 1 Service Description for MNP03.pdf', '', '合同评审', '02', 'EXW Shenzhen, China', '收到100%预付款10天内为客户更新2年期售电License，采用云平台部署。从客户正式给表计售电时开始计费', '提供系统License后有客户自行负责，系统出问题银河协助解决', '否', '否', '否', '合同签订10天内支付100%预付款', '无运费或保费', '02', '01', '', '02', '', '02', '02', '', '否', '无', '02', '', '00', '', '{D7BDED1975164B01ADCCA1827677D04E4654CAE914AA4B25B6892952453EBAEB}_Sales Contract MNP03_20200616.pdf', '银河电力', '61');
