INSERT INTO `crs_tabledata696` VALUES ('892', '{195BC71D-059D-434B-A7C6-207040432FAC}', '167', 'INHE-0771', '2020-07-01 11:28:33', '0000-00-00 00:00:00', '2020-07-02 17:38:20', 'unchecked', 'n', 'n', '', '1', 'ERANOVE SA/N° 2020/JPT/003 - 20000005AP\r\n/SEN01/合同评审', '', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'ERANOVE SA', 'N° 2020/JPT/003 - 20000005AP', 'SEN', 'SEN01', '186400', '投标法语组', '吴艳', '郑超波', '2020-07-01', '/\r\n', '/\r\n', '科特迪瓦\r\n', '深圳\r\n', '无\r\n', '无\r\n', 'AMI兼容服务\r\n', '02', '无', '原SEN01合同评审未通过，最终PO条款未做更改。\r\r\r\nPO金额186400欧，发票金额184000欧，银河已收款184000欧，验收函已签订。\r\r\r\n\r\r具体讨论细节见OA标题【SEN项目（CDN-AMI）合同审核和执行研讨及策略】、\r【2020年软件收款】\r\r\r\n财务要求日期签在6月底之前，财务6月确认收入。\r\r\r\n\r\r\r\r\r\r\n\r\r\r\r\r\n\r\r\r\r\n\r\r\r\n', '', '', '0', '0', '0', '{195BC71D059D434BA7C6207040432FAC3E3FD1A05260451F8D948358003231C8}_202002 SEN_AMI兼容PO 翻译 Lucie校对版本 v20200229.pdf', '与CIE协商确定\r\n', '{195BC71D059D434BA7C6207040432FAC7719915B5AFB4CFC8E75112B161686FE}_各厂家的设备型号版本协议.pdf', '{195BC71D059D434BA7C6207040432FAC7842EE48FE5340F2BE4CBD5E93168F23}_CI et PV d\'intégration G3 PLC 发票与验收函.pdf', '合同评审', '03', '不适用', '无', '1年', '否', '否', '当没有遵守合约交期时（开始及结束日期，任务执行，保留项消除，修复等），逾期1天需将扣除订单总额的不含税总额的0.4%，该款项每天不低于100欧元。并赔偿采购方所有由于其失误造成的财务损失。', '发票将在出具45天后通过银行转帐支付。', '否', '02', '01', '', '02', '', '01', '01', 'CDN系统兼容性讨论', '是', '需要支付佣金', '02', '', '02', '★★★', '{195BC71D059D434BA7C6207040432FAC4654CAE914AA4B25B6892952453EBAEB}_Bon Cde  ERANOVE INHEMETER - Projet Intégration DCU & Compteurs.pdf', '银河电力', '167');
