INSERT INTO `crs_tabledata696` VALUES ('898', '{972A9F49-959B-4D74-AB0D-2AE3DF86C144}', '144', 'INHE-0859', '2020-07-14 09:57:13', '0000-00-00 00:00:00', '2020-07-16 09:31:36', 'unchecked', 'n', 'n', '', '1', 'INHEMETER (T) LIMITED/INHESC2020060601\r\n/TTL02/合同评审', '', 'INHEMETER (T) LIMITED', 'INHEMETER (T) LIMITED', 'INHESC2020060601', 'TTL', 'TTL02', '8267083.85', '投标英语组', '陈金珠', '汤伟', '2020-07-14', '海运', '银河电力', '达累斯萨拉姆\r\n', '江西工厂', '工厂成品仓常规包装，须有纸箱等备品', 'IEC/EN', 'DDZ1513 DTZ1513', '02', '', '赊销产生的融资费用及保费改为由卖家承担，因此单相表的单价由37.2USD变更为37.7USD，以此抵消相关费用；具体可参考TTL02报价相关OA；', '', '', '205002', '8267083.85', '0', '{972A9F49959B4D74AB0D2AE3DF86C1443E3FD1A05260451F8D948358003231C8}_TTL02_205000_SKD_Single_and_Three_Phase_Meters_202007015.docx', '分批交货，第一批预计为2020.09.30', '{972A9F49959B4D74AB0D2AE3DF86C1447719915B5AFB4CFC8E75112B161686FE}_TTL02_PI_for_205000_SKD_Single_and_Three_Phase_Meter_20200715-Bank_of_China.xlsx', '{972A9F49959B4D74AB0D2AE3DF86C1447842EE48FE5340F2BE4CBD5E93168F23}_TTL02技术规格.pdf', '合同评审', '02', 'CIF', '收到每一批的100%信用证后分批从卖方工厂发出', '卖方所提供货物的保修期为从卖方工厂发货之日起18个月。', '是', '是', '否', '付款方式采用如下方式之一：（1)合同金额的100%通过不可撤销的保兑的远期180天的信用证支付。(2)对应批次预付款合同金额的30%将在签订合同后7天内通过T/T支付。余款合同金额的70%将在提单日后90天内通过T/T支付，并由卖方在SINOSURE投保。', '否', '03', '01', 'TTL', '02', '', '01', '01', 'TTL02合同评审所需技术规格书申请', '是', '单相表0.5USD/只；三相表3USD/只', '02', '', '', '', '', '银河电力', '144');
