INSERT INTO `crs_tabledata696` VALUES ('903', '{51CC4634-6488-4067-9B6F-9F14354C91B0}', '61', 'INHE-0916', '2020-07-27 10:02:18', '0000-00-00 00:00:00', '2020-07-29 11:46:36', 'unchecked', 'n', 'n', '', '1', 'FINMARK ENERGY PVT LTD/INHESC2020070801\r\n/EOI71/合同评审', '', 'Finmark Industries (Pvt) Ltd.', 'FINMARK ENERGY PVT LTD', 'INHESC2020070801', 'EOI', 'EOI71', '325198.8', '国际二部 INTL.Business Dept.2', '赖星威', '李忠鹏', '2020-07-27', '海运', '此订单和EOI80一起发货，因此运保费分了部分到EOI80订单内，相应的本订单的运保费较上一次有所减少。', '哈拉雷', '江西工厂', '按照EOI项目要求', '按照EIU项目要求', 'DDZ1513，DTZ1513', '01', '', '1.本订单为ZWS02项目佣金兑换为EOI项目订单，编号为EOI71；兑换方式/报价/发货条件等均已经过公司审核同意，OA“ZWS01佣金部分转换为EOI订单申请”。\r\r\r\r运保费足够。\r\r\n2.本合同相关附件为ZWS02佣金协议和服务协议，在佣金OA中备案。因为客户信息调用问题，本流程为覃湘君使用赖星威OA走的流程；审核过程中如有疑问，请对接覃湘君。', '', '', '5965', '307120', '0', '{1B8915B285C347E7BB6745C0484D452BD4CC22B6C7B643389146528155CECD45}_04. ZWS02_Service_AGRT_Supplementry_20200916.pdf', '2020年8月15日', '{1B8915B285C347E7BB6745C0484D452B9E19E8E731434A848B97C6F1C79E3A54}_05. 4800+1165meters contract_Supplementry_20200916.pdf', '', '合同评审', '02', 'CIP 哈拉雷', '上述产品在生产完成后，在买方履行第 INHEAGRT20070801 号合作协议、第 INHEAGRT20070802 号进口服务合同的义务和条件后，从卖方工厂发货。', '发货后24个月', '否', '否', '否', 'USD 268,663.00 应从买家在合作协议 INHEAGRT20070801 下的佣金扣除。USD 29,453.26 应从买家在进口服务合同 INHEAGRT20070802 下的服务佣金扣除。', '否', '02', '01', '', '02', '', '02', '01', 'EOI和ZWS项目技术规格解析', '否', 'N/A', '02', '', '', '', '', '银河电力', '61');
