INSERT INTO `crs_tabledata696` VALUES ('906', '{29A0A2B7-A4C5-432E-ADA3-C5FB08636761}', '61', 'INHE-0654', '2020-07-29 09:09:12', '0000-00-00 00:00:00', '2020-07-31 15:03:45', 'unchecked', 'n', 'n', '', '1', 'MEDIDAS ELECTRONICAS CENTRALIZADAS/INHESC2020072801\r\n/MCM01/合同评审', '', 'MEDIDAS ELECTRONICAS CENTRALIZADAS', 'Medidas electronicas centralizadas sas', 'INHESC2020072801', 'MCM', 'MCM01', '447200', '国际二部 INTL.Business Dept.2', '李明(Ming)', '李明(Ming)', '2020-07-29', '海运', '客户承担', '货交九江指定货代，卸货港为布埃纳文图拉港，哥伦比亚', '九江', '货物将用坚固的纸箱包装并打上适于海运的托盘', '按照IEC标准', 'i210、i310、i250、iT30', '02', '请参照技术规格', '1.客户对合同没有异议，且已支付预付款，预计本周可以收到；2.新客户，希望公司能给予较好的交期；3.从工厂到九江港口的运输费用，我已将GPRS模块单价增加1美金，共500美金，足以支付运费；4.公司暂时没有两相三线的命名，业务暂时命名为i250方便做合同和发票给客户；5.已将DTZ1513命名更改为iT30；', '', '', '13400', '413000', '34200', '{29A0A2B7A4C5432EADA3C5FB086367613E3FD1A05260451F8D948358003231C8}_Sales Contract MEC 202007 liming.docx', '2020年9月15日', '{29A0A2B7A4C5432EADA3C5FB086367617719915B5AFB4CFC8E75112B161686FE}_技术规格.zip', '', '合同评审', '02', 'FOB九江', '本合同项下货物将在卖方收到买方预付款USD134,160.00后60天内从卖方工厂发出，70%余款USD 313,040.00在发货前通过T/T支付。', '24个月', '否', '否', '否', '合同金额30% USD 134,160.00在签订合同7天内作为预付款T/T支付，70%余款USD 313,040.00在发货前通过T/T支付。', '否', '02', '01', '', '02', '', '01', '01', 'MCM项目技术解析', '否', '否', '02', '', '01', '★★', '', '银河电力', '61');
INSERT INTO `crs_tabledata696` VALUES ('907', '{B93C9E94-B542-4577-9A6D-A9480A735157}', '61', 'INHE-0916', '2020-07-31 11:05:37', '0000-00-00 00:00:00', '2020-08-04 11:11:04', 'unchecked', 'n', 'n', '', '1', 'FRISERV INVESTMENTS PVT LTD/INHESC2020072401/EOI73/合同评审', 'June已审核。重要信息详见“特殊要求说明”', 'Finmark Industries (Pvt) Ltd.', 'FRISERV INVESTMENTS PVT LTD', 'INHESC2020072401', 'EOI', 'EOI73', '27957', '国际二部 INTL.Business Dept.2', '赖星威', '李忠鹏,赖星威', '2020-07-31', '空运		\r\n		\r\n', '客户承担运保费		\r\n		\r\n', '哈拉雷国际机场		\r\n		\r\n', '中国任意机场		\r\n		\r\n', '按照EOI项目标准		\r\n		\r\n', '按照EOI项目标准		\r\n		\r\n', 'DDZ1513/DTZ1513/CIU-CIP\r\r\n		\r\r\n', '01', '', '\r\r1. 该订单全款由客户分期支付。目前已经到账3500美元，剩余24457.00美元待支付。因此未达到发货条件。此次合同评审目的：提供双方签字版合同给财务，以完成货款的入账工作\r（财务需要在30天内完成入账）\r\r\r\r\r\r\r\r\n2. 有库存，用EOI现有库存出货。\r预计八月底待全款入账后发货。\r\r\r\r\r\r\r\r\n3. 报价高于谌总的基准报价\r\r\n4. 运保费和跟单组确认，足够该订单的发货。							\r\n\r\r\n', '', '', '325', '22605', '5352', '{B93C9E94B54245779A6DA9480A7351573E3FD1A05260451F8D948358003231C8}_Sales Contact for Friserv Investments (Private) Limited 20200317.docx', '', '', '', '合同评审', '02', 'CIP，哈拉雷国际机场', '货物将在卖方收到买方T/T支付的合同全款后10天内，从卖方工厂发出。', '保修期为从卖方工厂发货之日起24个月。', '否', '否', '否', '合同金额的100%在签订合同40天内作为预付款在发货前T/T支付。', '否', '05', '01', '', '02', '', '02', '01', 'EOI和ZWS项目技术规格解析', '否', '否', '02', '', '', '', '', '银河电力', '61');
INSERT INTO `crs_tabledata696` VALUES ('908', '{6C1719EA-A5DA-412F-9ADA-A8A2C234F2BE}', '61', 'INHE-0916', '2020-07-31 10:44:25', '0000-00-00 00:00:00', '2020-08-04 11:11:36', 'unchecked', 'n', 'n', '', '1', 'HELIFLEX INVESTMENTS PRIVATE LIMI/INHESC2020072701/EOI74/合同评审', 'June已审核。重要信息详见“特殊要求说明”', 'Finmark Industries (Pvt) Ltd.', 'HELIFLEX INVESTMENTS PRIVATE LIMI', 'INHESC2020072701', 'EOI', 'EOI74', '225670.59', '国际二部 INTL.Business Dept.2', '赖星威', '李忠鹏,赖星威', '2020-07-31', '空运', '客户承担运保费	\r\n', '哈拉雷国际机场		\r\n				\r\n', '中国任意机场	\r\n', '按照EOI项目标准', '按照EOI项目标准		', 'DDZ1513', '01', '', '1. 该订单货款和运保费客户分开支付。目前货款已经到账，但是运保费尚未到账。因此未达到发货条件。此次合同评审目的：提供双方签字版合同给财务，以完成货款的入账工作\r（财务需要在30天内完成入账）\r\r\r\r\r\r\n2. 有库存，用EOI现有库存出货。\r待全款入账后发货。\r\r\r\r\r\r\n3. 报价基于谌总最新的基准报价，按照财务提供的汇率折算为人民币\r\r\r\r\r\r\n4. 运保费和跟单组确认，足够该订单的发货。			', '', '', '580', '181192', '44478.59', '{6C1719EAA5DA412F9ADAA8A2C234F2BE3E3FD1A05260451F8D948358003231C8}_(Revised CIP Harare) EOI74 Sales Contract for HELIFLEX INVESTMENTS PRIVATE LIMI 20200724.pdf', '', '', '', '合同评审', '04', 'CIP HARARE', '货物将在卖方收到买方T/T支付的合同全款后7天内，从卖方工厂发出。', '保修期为从卖方工厂发货之日起24个月。', '否', '否', '否', '合同金额的100%在签订合同30天内作为预付款在发货前T/T支付。', '否', '05', '01', '', '02', '', '02', '01', 'EOI和ZWS项目技术规格解析', '否', '否', '02', '', '', '', '', '银河电力', '61');
