INSERT INTO `crs_tabledata696` VALUES ('920', '{201B08FC-7FA5-49CD-A0ED-8818788B54F9}', '61', 'INHE-0853', '2020-08-13 17:09:35', '0000-00-00 00:00:00', '2020-08-18 11:08:22', 'unchecked', 'n', 'n', '', '1', 'The energy of cameroon/2007039804/CMN01/合同评审', '', 'The energy of cameroon', 'The energy of cameroon', '2007039804', 'CMN', 'CMN01', '1044000.8', '国际二部 INTL.Business Dept.2', '胡亚婵(Zoe)', '', '2020-08-13', '海运', '客户承担', '杜阿拉港口', '', '', 'IEC标准', '', '', '', '1.L/C费用由我司承担。2.供应套件包含电表、配CIU、差动断路器、用户卡、操作手册。3.目前下的是第一个PO，剩余采购数量还在确认，预计将签订的合同为客户提供模板的框架合同。', '', '', '20000', '1044000.8', '0', '{FEE7DC6223B74A2DB68D77ECFF4D7BE7D4CC22B6C7B643389146528155CECD45}_CMN框架合同最终版-法语.pdf', '60天', '{FEE7DC6223B74A2DB68D77ECFF4D7BE79E19E8E731434A848B97C6F1C79E3A54}_PO和形式发票.rar', '{FEE7DC6223B74A2DB68D77ECFF4D7BE7BA0F4BB9344A4053BE173BB06528647F}_供应商罚则-Ch.docx', '合同评审', '03', 'FOB（EXW+3%佣金比例）', '收到信用证之后发货', '12月', '否', '否', '根据标书规定：1.交期延迟超过15天以上，每天罚款合同金额的0.2%。2.总罚金超过合同金额的10%时，将解除合同。', '100%信用证60天远期信用证支付', '不含', '01', '01', '', '02', '', '02', '02', 'CMN供货方案', '否', '否', '02', '', '02', '★★★', '', '银河电力', '61');
