INSERT INTO `crs_tabledata696` VALUES ('939', '{04E23225-548D-49E0-93A5-AEE1C2507A83}', '171', 'INHE-0929', '2020-09-04 14:38:57', '0000-00-00 00:00:00', '2020-09-08 16:51:19', 'unchecked', 'n', 'n', '', '1', 'ELECTRICITE DE GUINEE/36670/ALP01/合同评审', '', 'ELECTRICITE DE GUINEE', 'ELECTRICITE DE GUINEE', '36670', 'ALP', 'ALP01', '24901.8', '西非区WAC', '崔莹(Claudette)', '张柳芳(Alexie),郑超波(Mike),崔莹(Claudette)', '2020-09-04', 'DHL', '600USD ELECTRICITE DE GUINEE\r\r\n', 'Cité Chemin de fer, Kaloum Conakry', '深圳', '包装上要有公司的标志', '', 'iT30,HHU-I9000S,表箱BOX-T05', '02', '', '表箱内配有安装板，CT表有LED报警灯；此项目为试点项目，试点成功后讨论后续订单；发票一式三份，包装和发票上都要有订单号N° Commande:36670,；\r\r\r\r\r\n\r\r\r\r\r\n\r\r\r\r\r\n注：1.PO表箱单价和总额客户填写有误，单价应为43.7，总额为174.8，合同总金额无误，按照24901.80美元执行。\r\r\r\r\r\n2.付款条件为：发货后月末30天付款，除非经过特殊约定，经与客户约定提交发票后5个工作日内TT付款。	\r\r\r\n\r\r\r\r\n\r\r\r\r\r\n\r\r\r\r\r\n', '', '', '4', '1932', '1234.8', '{04E23225548D49E093A5AEE1C2507A833E3FD1A05260451F8D948358003231C8}_ALP项目PO 中法对照版.pdf', '2020/09/08', '{04E23225548D49E093A5AEE1C2507A837719915B5AFB4CFC8E75112B161686FE}_TDRs Comptage Totalisateur Distribution EN.docx', '', '合同评审', '02', 'CPT', '收到PO，公司审批后发货', '无', '是', '不需要', '否', '约定提交发票后5个工作日内TT付款', '不包含', '02', '01', '', '02', '', '01', '01', 'ALP电表技术支持', '是', 'EXW*0.15', '02', '', '02', '★★★', '', '银河电力', '171');
INSERT INTO `crs_tabledata696` VALUES ('940', '{D91ED1FC-078C-4095-8E12-FF20BA6FFA2B}', '144', 'INHE-0931', '2020-09-04 16:05:38', '0000-00-00 00:00:00', '2020-09-10 14:50:32', 'unchecked', 'n', 'n', '', '1', 'The Kenya Power * Lighting Company Limited/INHESC2020090401/KFE/合同评审', '', 'The Kenya Power * Lighting Company Limited', 'The Kenya Power * Lighting Company Limited', 'KP1/9A.3/OT/34/19-20', 'KFE', 'KFE01', '67881800', '投标英语组', '杨睛睛', '谭东羊(Timon)', null, '海陆联运', '卖方承担运费', '交货到KPLC Ruaraka Stores', '中国任意港口', '按照标书技术规格要求', '', 'DDZ1513', '02', '', '备注：1.此销售合同评审为KPLC与IAC的外部合同评审，同时附上IAC与银河电力的内部销售合同，一起评审；（如附件）。2.IAC与银河电力内部合同结算价格，如OA核算审批：DDP含税单价8.93USD/台，内部合同总额：625,100USD。', '', '', '70000', '67881800', '0', '{D91ED1FC078C40958E12FF20BA6FFA2B3E3FD1A05260451F8D948358003231C8}_1. KFE合同KPLC&IAC.pdf', '2020/10/30', '{D91ED1FC078C40958E12FF20BA6FFA2B7719915B5AFB4CFC8E75112B161686FE}_2.KFE销售合同70000PCS（IAC&INHE）.docx', '', '合同评审', '05', 'DDP(买方仓库)(含增值税)', '实际发货时间，依据电力公司后续提供PO上的交期', '自货物在最终交货地点交付后5年', '是', '是', '每迟延一天交付，扣除交付或装运价款的0.5%，总违约金额不超过合同价款的10%。', '在厂家达成满意交付的30天后开始支付货款，对于本地供应商，以KPLC的支票或者实时全额支付系统（RTGS）进行结算。', '单价包含运保费0.25 USD/台，其中江西工厂至肯尼亚蒙巴萨为0.14USD/台；蒙巴萨到KPLC仓库 0.11 USD/台', '01', '01', '/', '02', '', '01', '01', 'KFE（后付费简单表）技术解析', '是', '根据最终IAC投标单价DDP含增值税9.06USD（即969.74KSH）反推，计算佣金金额0.5USD/台——参考OA：KFE投标报价申请及核算', '02', '否', '01', '★★', '', '银河电力', '144');
