INSERT INTO `crs_tabledata696` VALUES ('960', '{D175156F-BDB9-418B-83E0-18E63AE75D92}', '175', 'INHE-0654', '2020-09-27 15:44:38', '0000-00-00 00:00:00', '2020-09-30 10:37:46', 'unchecked', 'n', 'n', '', '1', 'Cashpower Sudamericana S.A./INHESC2020092702/ADC-5/合同评审', '', 'Cashpower Sudamericana S.A.', 'Cashpower Sudamericana S.A.', 'INHESC2020092702', 'ADC', 'ADC-5', '59275', '南美区S. America', '李明(Ming)', '', '2020-09-27', '海运，(端子盖可能考虑到空运）', '卖方', '布宜诺斯港口', '九江', '公司标准', '工厂验收', 'DDZ1513/DTZ1513', '02', '', '1.谌总报价为EXW,CT价格140$,业务安装145$收，多出400美金部分用于扣除工厂到九江港口的运费，其余剩余的钱留在客户的账户上，用于后续邮寄快递使用（已与客户说明）；2.CT表的功能如果有部分不符合，可以接受默认，只要能实现短信上报功能、停电上报、脉冲常数为10000即可，王工表示要使用BAL程序；3.端子盖和电池后盖，希望可以优先生产，因为当地已安装的电表端子盖都被盗窃；4.G3-PLC模块希望可以深圳实验室先给出，便于现场做测试使用。', '', '', '1080', '41600', '17675', '{D175156FBDB9418B83E018E63AE75D923E3FD1A05260451F8D948358003231C8}_Sales Contract 20200927.docx', '11.20', '{D175156FBDB9418B83E018E63AE75D927719915B5AFB4CFC8E75112B161686FE}_CT表技术规格 Configuracio?n DTZ1513 CT stock 7-2020-2的副本.docx', '', '合同评审', '02', 'FOB JIUJIANG', '收到50%尾款后发货', '12', '否', '否', '尽量不要延期交货', '50%预付款T/T+50%发货前尾款T/T', '否', '05', '01', 'OA：ADC项目报价', '02', '', '02', '01', 'ADC', '否', '否', '02', '', '', '', '', '银河电力', '175');
INSERT INTO `crs_tabledata696` VALUES ('961', '{3007E114-EDB2-4400-BB18-E2E630753F6C}', '171', 'INHE-0772', '2020-09-27 13:30:39', '0000-00-00 00:00:00', '2020-09-30 10:39:41', 'unchecked', 'n', 'n', '', '1', 'La Société Nationale dElectricité du Burkina/待定/MAA01/合同评审', '', 'La Société Nationale dElectricité du Burkina', 'La Société Nationale dElectricité du Burkina', '待定', 'MAA', 'MAA01', '5435200', '西非区WAC', '张子琦(Miranda)', '张子琦(Miranda)', '2020-09-27', '海运', '银河', '电力公司仓库：Magasin General de Distribution de Kossodo，Ouagadougou', '江西', '有', '客户到工厂验收+当地实验室检测', 'i210', '02', '“零线恢复”功能不满足', '价格术语可以是CIP到客户仓库，也可以是DDP不含VAT。 影响：做收入确认时判定模糊。合同中报价以CIP客户仓库为基础，银河交关税和当地保险，但不交增值税交税主体是电力公司，也不由银河负责。参考BFN03当时遇到同样的问题，可以通过客户书面确认CIP条款文件来界定。						\r\r\r', '', '', '240000', '5409600', '25600', '{3007E114EDB24400BB18E2E630753F6C3E3FD1A05260451F8D948358003231C8}_MAA合同 20200924.rar', '开工令起120天', '', '', '合同评审', '02', 'CIP Magasin General de Distribution de Kossodo，Ouagadougou', '收到预付款后，合同规定时间内发货即可', '12个月', '是', '是', '是', 'T/T出示预付款保函和30%发票，支付30%合同款；出示发货单据，保险单和40%发票，支付40%合同款；出示验收文件后和余款30%发票，支付30%合同款。', '是；运费为', '01', '01', '', '02', '', '01', '01', 'BFC技术规格解析/MAA项目技术资料准备（原BFC项目）', '是', '5%EXW；0.9*240000=216000 USD', '02', 'N/A', '03', '★★★★', '', '银河电力', '171');
